# ---- student side ----
@app.post("/api/class/join")
def join_class(body: JoinIn, user: User = Depends(current_user),
               db: Session = Depends(get_db)):
    """Codes: a subject-slot code (from a head teacher) claims that subject
    and locks the teacher to it; a classroom's student code enrols a student."""
    raw = body.code.strip()
    code = raw.upper()

    # 1) Any staff code — head-teacher, subject slot, or a school's generic
    #    teacher code. apply_school_code is what signup has always used, and
    #    its docstring has always said "signup / join"; join simply never
    #    called it, so it handled subject slots and nothing else. A head
    #    teacher who already had an account and was handed a HEAD- code was
    #    told "no class or subject found with that code" — the code was real,
    #    and the only way to redeem it was to make a second account.
    role = apply_school_code(db, user, raw)
    if role:
        db.commit()
        slot = db.query(SubjectSlot).filter(
            func.upper(SubjectSlot.code) == code).first()
        k = db.get(Klass, slot.class_id) if slot else None
        return {"ok": True, "class": (k.name if k else ""),
                "subject": (slot.subject if slot else ""),
                "role": "school admin" if role == "head" else "teacher"}

    # 2) A classroom student code.
    k = db.query(Klass).filter(func.upper(Klass.join_code) == code).first()
    if not k:
        raise HTTPException(404, "No class or subject found with that code")
    if k.teacher_id == user.id:
        return {"ok": True, "class": k.name, "role": "school admin"}
    # Head/admin viewing does not need enrolment; everyone else enrols as student.
    exists = db.query(ClassMember).filter(
        ClassMember.class_id == k.id, ClassMember.user_id == user.id).first()
    if not exists:
        _one_class_only(db, user, k)
        db.add(ClassMember(class_id=k.id, user_id=user.id))
        db.commit()
    return {"ok": True, "class": k.name, "role": "student"}


def _one_class_only(db, user, k):
    """A learner belongs to ONE classroom, and this is where that is decided.

    A teacher holds several classes — that is what a timetable is. A student
    holds one, and it is the thing everything else about them hangs off: the
    subjects they are taught, who teaches each one, whose register they are
    on, whose attendance they are in. A second class does not add a room; it
    makes every one of those questions have two answers, and the screens that
    ask them show whichever came back first.

    Institutions only. Outside one, "class" means a study group somebody
    joined off their own bat and there is no reason to hold them to one.
    """
    if not _cl.is_institution(_scope_of(db, user)):
        return
    other = (db.query(ClassMember)
               .join(Klass, Klass.id == ClassMember.class_id)
               .filter(ClassMember.user_id == user.id,
                       ClassMember.class_id != k.id)
               .first())
    if other is None:
        return
    where = db.get(Klass, other.class_id)
    raise HTTPException(409,
        f"You are already in {where.name if where else 'a class'}. A student "
        f"belongs to one classroom — ask a teacher to move you if that is "
        f"the wrong one.")


@app.post("/api/class/leave/{cid}")
def leave_class(cid: int, user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    row = db.query(ClassMember).filter(
        ClassMember.class_id == cid, ClassMember.user_id == user.id).first()
    if row:
        db.delete(row)
        db.commit()
    return {"ok": True}


@app.get("/api/class/mine")
def my_enrolled_classes(user: User = Depends(current_user),
                        db: Session = Depends(get_db)):
    """Everything the student needs for the weekly table across all teachers."""
    memberships = db.query(ClassMember, Klass).join(Klass, Klass.id == ClassMember.class_id) \
        .filter(ClassMember.user_id == user.id).all()
    mine = {r.assignment_id: r for r in db.query(Submission)
            .filter(Submission.user_id == user.id).all()}
    my_subs = set(mine)
    classes = []
    for cm, k in memberships:
        teacher = db.get(User, k.teacher_id)
        assignments = db.query(Assignment).filter(Assignment.class_id == k.id) \
            .order_by(Assignment.due_date.asc(), Assignment.created_at.desc()).all()
        sched = db.query(ScheduleItem).filter(ScheduleItem.class_id == k.id) \
            .order_by(ScheduleItem.position, ScheduleItem.id).all()
        classes.append({
            "id": k.id, "name": k.name, "school": k.school,
            "teacher": teacher.name if teacher else "",
            "schedule": [{"day": s.day, "text": s.text} for s in sched],
            "assignments": [
                {**_asg_json(a, a.id in my_subs),
                 "reviewed": bool(mine[a.id].reviewed_at) if a.id in mine else False,
                 "feedback": (mine[a.id].feedback or "") if a.id in mine else ""}
                for a in assignments],
        })
    return {"classes": classes}


@app.get("/api/assignment/{aid}")
def assignment_detail(aid: int, user: User = Depends(current_user),
                      db: Session = Depends(get_db)):
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    member = db.query(ClassMember).filter(
        ClassMember.class_id == a.class_id, ClassMember.user_id == user.id).first()
    k = db.get(Klass, a.class_id)
    if not member and not (k and (k.teacher_id == user.id or user.is_admin)):
        raise HTTPException(403, "Not in this class")
    sub = db.query(Submission).filter(
        Submission.assignment_id == aid, Submission.user_id == user.id).first()
    teacher = db.get(User, a.teacher_id)
    return {**_asg_json(a, bool(sub)),
            "class_name": k.name if k else "",
            "teacher_name": teacher.name if teacher else "",
            "my_response": sub.response if sub else "",
            "submitted_at": sub.updated_at.isoformat() if sub and sub.updated_at else None,
            # The verdict, where there is one. A student who has submitted
            # and heard nothing should be able to see that plainly rather
            # than reading it as silence from a teacher.
            "feedback": (sub.feedback or "") if sub else "",
            "reviewed_at": (sub.reviewed_at.isoformat()
                            if sub and sub.reviewed_at else None)}


@app.post("/api/assignment/{aid}/submit")
def submit_assignment(aid: int, body: SubmitIn, user: User = Depends(current_user),
                      db: Session = Depends(get_db)):
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    member = db.query(ClassMember).filter(
        ClassMember.class_id == a.class_id, ClassMember.user_id == user.id).first()
    if not member:
        raise HTTPException(403, "Not in this class")
    # Closed means closed, or the status is decoration. It is checked here
    # rather than only drawn on the page, because a button that is hidden is
    # not a rule — and a learner who hands in through a stale tab would
    # otherwise land work on a teacher who had finished marking.
    if getattr(a, "closed_at", None):
        raise HTTPException(
            403, "Your teacher has closed this one. You can still read it and "
                 "what you wrote, but it cannot be handed in now.")
    text = body.response.strip()
    sub = db.query(Submission).filter(
        Submission.assignment_id == aid, Submission.user_id == user.id).first()
    if not text:
        # empty submission = un-submit / mark not done
        if sub:
            db.delete(sub)
            db.commit()
        return {"done": False}
    if sub:
        sub.response = text[:20000]
    else:
        db.add(Submission(assignment_id=aid, user_id=user.id, response=text[:20000]))
    db.commit()
    return {"done": True}


# ---- per-assignment chat (student <-> the teacher who set it) ----
def _asg_and_access(db, aid, user):
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    k = db.get(Klass, a.class_id)
    # Who counts as the teacher here.
    #
    # This asked whether the user CREATED the class, which is always the
    # school admin — so a subject teacher was not a teacher of their own
    # assignment. They were not a ClassMember either, so they fell through to
    # 403 and could neither read nor answer a message a child had sent them.
    # The whole messaging feature worked for the admin and for nobody else.
    #
    # _my_subjects is the existing answer to "does this person teach here":
    # None for a head or admin, and the subjects they hold otherwise.
    teaches = _my_subjects(db, a.class_id, user)
    is_teacher = bool(
        user.is_admin
        or (k and k.teacher_id == user.id)
        or teaches is None
        or teaches)
    is_member = db.query(ClassMember).filter(
        ClassMember.class_id == a.class_id, ClassMember.user_id == user.id).first()
    if not (is_teacher or is_member):
        raise HTTPException(403, "Not allowed")
    return a, k, bool(is_teacher)


@app.get("/api/assignment/{aid}/messages")
def get_messages(aid: int, student_id: int = 0, user: User = Depends(current_user),
                 db: Session = Depends(get_db)):
    a, k, is_teacher = _asg_and_access(db, aid, user)
    sid = student_id if is_teacher else user.id
    if not sid:
        return {"messages": [], "student_id": 0,
                "subject": a.subject or "", "title": a.title or ""}
    msgs = db.query(AssignmentMessage).filter(
        AssignmentMessage.assignment_id == aid,
        AssignmentMessage.student_id == sid).order_by(AssignmentMessage.created_at).all()
    # The subject travels with the thread. A teacher who takes Physics in two
    # classes, and Maths in a third, was reading messages with no indication
    # of which subject they were about — and a student's question only means
    # something next to the subject it is about.
    return {"student_id": sid, "subject": a.subject or "",
            "title": a.title or "", "messages": [{
        "from_teacher": m.from_teacher, "body": m.body,
        "at": m.created_at.isoformat() if m.created_at else None} for m in msgs]}


@app.post("/api/assignment/{aid}/message")
def post_message(aid: int, body: MessageIn, user: User = Depends(current_user),
                 db: Session = Depends(get_db)):
    a, k, is_teacher = _asg_and_access(db, aid, user)
    sid = body.student_id if is_teacher else user.id
    if not sid:
        raise HTTPException(400, "No student thread specified")
    db.add(AssignmentMessage(assignment_id=aid, student_id=sid, sender_id=user.id,
                             from_teacher=is_teacher, body=body.body.strip()[:4000]))
    db.commit()
    return {"ok": True}


@app.get("/api/teacher/assignment/{aid}/submissions")
def assignment_submissions(aid: int, user: User = Depends(teacher_user),
                           db: Session = Depends(get_db)):
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    _own_class(db, a.class_id, user)
    members = db.query(ClassMember, User).join(User, User.id == ClassMember.user_id) \
        .filter(ClassMember.class_id == a.class_id).all()
    subs = {s.user_id: s for s in db.query(Submission)
            .filter(Submission.assignment_id == aid).all()}
    students = []
    for cm, u in members:
        s = subs.get(u.id)
        fresh = bool(s and s.reviewed_at and s.updated_at
                     and s.updated_at > s.reviewed_at)
        students.append({"id": u.id, "name": u.name,
                         "response": s.response if s else "",
                         "submitted": bool(s),
                         "feedback": (s.feedback or "") if s else "",
                         "reviewed": bool(s and s.reviewed_at) and not fresh,
                         "resubmitted": fresh,
                         "at": s.updated_at.isoformat() if s and s.updated_at else None})
    students.sort(key=lambda r: (not r["submitted"], r["reviewed"],
                                 r["name"].lower()))
    return {"id": a.id, "subject": a.subject, "title": a.title, "body": a.body,
            "students": students}


class AsgCloseIn(BaseModel):
    closed: bool = True


@app.post("/api/teacher/assignment/{aid}/close")
def close_assignment(aid: int, body: AsgCloseIn,
                     user: User = Depends(teacher_user),
                     db: Session = Depends(get_db)):
    """Close work, or open it again.

    A due date is a request. Closing is the decision, and it is a teacher's:
    plenty of classes hand in late and are marked anyway, and a date that shut
    the door by itself would take that judgement away from the person who
    should have it.

    Closed work stays readable. A learner can still see what was asked and
    what they wrote — taking the questions away the moment the deadline passes
    would punish the person revising from them.
    """
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    _own_class(db, a.class_id, user)
    mine = _my_subjects(db, a.class_id, user)
    if mine is not None and (a.subject or "") not in mine:
        raise HTTPException(
            403, f"{a.subject or 'That subject'} is taught by somebody else.")
    if body.closed:
        a.closed_at = now()
        a.closed_by = user.id
    else:
        a.closed_at = None
        a.closed_by = 0
    db.commit()
    return {"ok": True, "closed": bool(a.closed_at),
            "closed_by": a.closed_by or 0}


@app.get("/api/teacher/messages")
def teacher_message_inbox(user: User = Depends(teacher_user),
                          db: Session = Depends(get_db)):
    """Every message waiting for this teacher, across every class they take.

    Messages hang off an assignment, so finding them meant opening assignments
    one at a time and hoping. A question asked on Tuesday sat unanswered
    because nobody thought to look at that particular worksheet — which is not
    a teacher ignoring a child, it is a product hiding one.

    Grouped by class and subject, and ordered so the ones waiting for a reply
    come first. A teacher's actual question is never "what messages exist", it
    is "who is waiting for me".
    """
    # The classes this person teaches in, and which subjects in each. An
    # admin gets everything at their school, because that is their job.
    classes = {}
    if is_school_admin(user, db):
        sid = _school_of_anyone(user, db)
        q = db.query(Klass)
        if not user.is_admin:
            q = q.filter(Klass.school_id == sid)
        for k in q.all():
            classes[k.id] = None            # None = every subject
    else:
        for sl in db.query(SubjectSlot).filter(
                SubjectSlot.teacher_id == user.id).all():
            classes.setdefault(sl.class_id, set())
            if classes[sl.class_id] is not None:
                classes[sl.class_id].add(sl.subject or "")
    if not classes:
        return {"threads": [], "waiting": 0}

    asgs = (db.query(Assignment)
              .filter(Assignment.class_id.in_(list(classes)))
              .all())
    mine = {}
    for a in asgs:
        allowed = classes.get(a.class_id)
        if allowed is None or (a.subject or "") in allowed:
            mine[a.id] = a
    if not mine:
        return {"threads": [], "waiting": 0}

    msgs = (db.query(AssignmentMessage)
              .filter(AssignmentMessage.assignment_id.in_(list(mine)))
              .order_by(AssignmentMessage.created_at.asc()).all())
    if not msgs:
        return {"threads": [], "waiting": 0}

    names = {u.id: (u.name or "A student") for u in db.query(User).filter(
        User.id.in_([m.student_id for m in msgs] or [0])).all()}
    klass = {k.id: k.name for k in db.query(Klass).filter(
        Klass.id.in_(list(classes)) if classes else False).all()}

    # One thread per (assignment, student). The last message decides whether
    # it is waiting: if the student spoke last, nobody has answered them.
    threads = {}
    for m in msgs:
        a = mine[m.assignment_id]
        key = (m.assignment_id, m.student_id)
        t = threads.setdefault(key, {
            "assignment_id": m.assignment_id, "student_id": m.student_id,
            "student": names.get(m.student_id, "A student"),
            "class_id": a.class_id, "class_name": klass.get(a.class_id, ""),
            "subject": a.subject or "", "title": a.title or "",
            "messages": 0, "last": "", "at": "", "waiting": False})
        t["messages"] += 1
        t["last"] = (m.body or "")[:200]
        t["at"] = m.created_at.isoformat() if m.created_at else ""
        t["waiting"] = not m.from_teacher

    out = sorted(threads.values(),
                 key=lambda t: (not t["waiting"], t["at"]), reverse=False)
    out.sort(key=lambda t: (not t["waiting"], "" ))
    # Waiting first, then newest — a teacher works down a list of people who
    # need an answer, not a chronology.
    out = (sorted([t for t in out if t["waiting"]],
                  key=lambda t: t["at"], reverse=True)
           + sorted([t for t in out if not t["waiting"]],
                    key=lambda t: t["at"], reverse=True))
    return {"threads": out[:200],
            "waiting": sum(1 for t in out if t["waiting"])}


@app.get("/api/teacher/assignment/{aid}/threads")
def assignment_threads(aid: int, user: User = Depends(teacher_user),
                       db: Session = Depends(get_db)):
    """Which students have messaged the teacher about this assignment."""
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    _own_class(db, a.class_id, user)
    # And only about a subject this teacher actually takes. _own_class admits
    # every teacher of the classroom, which is right for reading the register
    # and wrong for reading what a child wrote privately to the person who
    # teaches them Physics. The school admin keeps the whole view, because
    # answering a parent about a message is their job.
    mine = _my_subjects(db, a.class_id, user)
    if mine is not None and (a.subject or "") not in mine:
        raise HTTPException(
            403, f"{a.subject or 'That subject'} is taught by somebody else. "
                 f"These messages are between them and their students.")
    sids = [r[0] for r in db.query(AssignmentMessage.student_id)
            .filter(AssignmentMessage.assignment_id == aid).distinct().all()]
    out = []
    for sid in sids:
        u = db.get(User, sid)
        last = db.query(AssignmentMessage).filter(
            AssignmentMessage.assignment_id == aid,
            AssignmentMessage.student_id == sid).order_by(
            AssignmentMessage.created_at.desc()).first()
        out.append({"student_id": sid, "name": u.name if u else "student",
                    "last": last.body if last else "",
                    "from_teacher": last.from_teacher if last else False})
    return {"threads": out, "subject": a.subject or "",
            "title": a.title or ""}


@app.post("/api/assignment/{aid}/help")
async def assignment_help(aid: int, body: HelpIn, user: User = Depends(current_user),
                          db: Session = Depends(get_db)):
    """AI help scoped to this assignment. Guides, does not just hand answers."""
    a, k, _ = _asg_and_access(db, aid, user)
    if not ASK_ENABLED:
        raise HTTPException(503, "The AI helper is not switched on")
    subject = a.subject or "the subject"
    prompt = (
        f"You are a patient tutor helping a student with a school assignment. "
        f"Subject: {subject}. Assignment title: {a.title}. "
        f"The teacher's instructions were: {a.body[:1500]}\n\n"
        f"The student asks: \"{body.question}\"\n\n"
        f"Help them UNDERSTAND and make progress. Explain the idea and give a "
        f"worked hint or example. Do NOT simply write their final answer for "
        f"them to copy. Keep it short, clear, and matched to a school student. "
        f"Reply as plain helpful text (no JSON)."
    )
    try:
        import httpx
        async with httpx.AsyncClient(timeout=45) as client:
            if AI_PROVIDER == "gemini":
                r = await client.post(
                    f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent",
                    headers={"x-goog-api-key": GEMINI_API_KEY, "content-type": "application/json"},
                    json={"contents": [{"parts": [{"text": prompt}]}],
                          "generationConfig": {"maxOutputTokens": 800, "temperature": 0.5}})
                _upstream_ok(r, "gemini")
                text = "".join(p.get("text", "") for c in r.json().get("candidates", [])
                               for p in c.get("content", {}).get("parts", [])).strip()
            elif AI_PROVIDER == "groq":
                r = await client.post(
                    "https://api.groq.com/openai/v1/chat/completions",
                    headers={"Authorization": f"Bearer {GROQ_API_KEY}", "content-type": "application/json"},
                    json={"model": GROQ_MODEL, "max_tokens": 800, "temperature": 0.5,
                          "messages": [{"role": "user", "content": prompt}]})
                _upstream_ok(r, "groq")
                text = r.json().get("choices", [{}])[0].get("message", {}).get("content", "").strip()
            else:
                r = await client.post(
                    "https://api.anthropic.com/v1/messages",
                    headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01",
                             "content-type": "application/json"},
                    json={"model": ANTHROPIC_MODEL, "max_tokens": 800,
                          "messages": [{"role": "user", "content": prompt}]})
                _upstream_ok(r, "claude")
                text = "".join(b.get("text", "") for b in r.json().get("content", [])
                               if b.get("type") == "text").strip()
    except Exception as e:
        print(f"Assignment help failed ({AI_PROVIDER}): {type(e).__name__}: {e}")
        raise HTTPException(503, "The helper could not respond just now. Try again.")
    return {"answer": text or "I could not think of a hint just now — try rephrasing."}


# ---- admin: teacher codes and roles ----
# ============ Head teacher: run a school ============
class SubjectIn(BaseModel):
    subject: str = Field(min_length=1, max_length=80)


class RequestIn(BaseModel):
    class_id: int = 0
    message: str = Field(min_length=2, max_length=2000)


def _slot_json(db, s):
    tu = db.get(User, s.teacher_id) if s.teacher_id else None
    # The teacher's address travels with the subject, because the question a
    # head asks at this row is "how does she get in", and the answer was on a
    # different screen. A board code was sitting next to a teacher's name and
    # reading as her sign-in; the actual sign-in belongs beside it.
    return {"id": s.id, "subject": s.subject, "code": s.code,
            "status": s.status, "teacher": tu.name if tu else "",
            "teacher_email": (tu.email if tu else ""),
            "teacher_id": s.teacher_id or 0}


@app.get("/api/head/overview")
def head_overview(user: User = Depends(head_user), db: Session = Depends(get_db)):
    t = teacher_row(user, db)
    sid = t.school_id if t else 0
    classes = (db.query(Klass).filter(Klass.school_id == sid).all() if sid
               else db.query(Klass).filter(Klass.teacher_id == user.id).all())
    out = []
    for k in classes:
        slots = db.query(SubjectSlot).filter(SubjectSlot.class_id == k.id) \
            .order_by(SubjectSlot.subject).all()
        nstu = db.query(func.count(ClassMember.id)).filter(ClassMember.class_id == k.id).scalar()
        out.append({"id": k.id, "name": k.name, "join_code": k.join_code,
                    "students": nstu,
                    # So the screen can say "archived" and offer to bring it
                    # back, rather than showing a finished class as current.
                    "archived": bool(k.archived_at),
                    "subjects": [_slot_json(db, s) for s in slots]})
    reqs = db.query(TeacherRequest).filter(
        TeacherRequest.school_id == sid, TeacherRequest.status == "open").all()
    requests = []
    for r in reqs:
        ru = db.get(User, r.teacher_id)
        requests.append({"id": r.id, "teacher": ru.name if ru else "",
                         "message": r.message, "class_id": r.class_id})
    return {"school": (t.school if t else ""), "classrooms": out, "requests": requests}


@app.post("/api/head/class/{cid}/slot")
def head_add_slot(cid: int, body: SubjectIn, user: User = Depends(head_user),
                  db: Session = Depends(get_db)):
    _head_or_admin(db, cid, user)
    s = SubjectSlot(class_id=cid, subject=body.subject.strip()[:80],
                    code=_gen_slot_code(db))
    db.add(s)
    db.commit()
    db.refresh(s)
    return _slot_json(db, s)


@app.post("/api/head/slot/{sid}/rotate")
def head_rotate_slot(sid: int, user: User = Depends(head_user),
                     db: Session = Depends(get_db)):
    s = db.get(SubjectSlot, sid)
    if not s:
        raise HTTPException(404, "Not found")
    _head_or_admin(db, s.class_id, user)
    s.code = _gen_slot_code(db)
    # The teacher STAYS on the subject.
    #
    # This used to set teacher_id = 0, which was right when the code was a
    # ticket somebody redeemed to claim the slot: rotating it took the slot
    # back so it could be given to somebody else.
    #
    # The code is now the teacher's sign-in. Rotating it is what a school does
    # when a code has been read off a board or passed around a class — it
    # replaces a credential. Unassigning the teacher as a side effect meant
    # the new code let nobody in at all, and the teacher was quietly dropped
    # from a class they still teach. Rotate to replace a code; use
    # /api/head/assign to change who holds the subject.
    db.commit()
    return _slot_json(db, s)


@app.delete("/api/head/slot/{sid}")
def head_delete_slot(sid: int, user: User = Depends(head_user),
                     db: Session = Depends(get_db)):
    s = db.get(SubjectSlot, sid)
    if s:
        _head_or_admin(db, s.class_id, user)
        db.delete(s)
        db.commit()
    return {"ok": True}


@app.post("/api/head/class/{cid}/rotate")
def head_rotate_class(cid: int, user: User = Depends(head_user),
                      db: Session = Depends(get_db)):
    k = _head_or_admin(db, cid, user)
    k.join_code = _gen_join_code(db)
    db.commit()
    return {"join_code": k.join_code}


@app.post("/api/teacher/request")
def teacher_request(body: RequestIn, user: User = Depends(teacher_user),
                    db: Session = Depends(get_db)):
    """A subject teacher asks the head for a new subject/class."""
    t = teacher_row(user, db)
    db.add(TeacherRequest(school_id=(t.school_id if t else 0),
                          class_id=body.class_id, teacher_id=user.id,
                          message=body.message.strip()[:2000]))
    db.commit()
    return {"ok": True}


@app.post("/api/head/request/{rid}/done")
def head_close_request(rid: int, user: User = Depends(head_user),
                       db: Session = Depends(get_db)):
    r = db.get(TeacherRequest, rid)
    if r:
        r.status = "done"
        db.commit()
    return {"ok": True}


# ---- notifications / messages inbox ----
def _aware(d):
    if d is None:
        return dt.datetime.min.replace(tzinfo=dt.timezone.utc)
    return d if d.tzinfo else d.replace(tzinfo=dt.timezone.utc)


def _disposition(name, how="inline"):
    """A Content-Disposition a real filename can survive.

    HTTP headers are latin-1. A filename with an em dash in it — which is
    what this product names things with, "Worksheet — marked.pdf" — raises
    UnicodeEncodeError while BUILDING the response, so the download is a 500
    with no clue in it. Any Indian-language filename does the same, which is
    worse and likelier: a teacher uploading a chapter named in Tamil got a
    file that could never be opened again.

    RFC 5987: an ASCII fallback for anything old, and filename* with the
    real name percent-encoded as UTF-8 for everything since about 2011.
    """
    raw = (name or "file")[:120]
    ascii_name = raw.encode("ascii", "replace").decode("ascii")
    ascii_name = ascii_name.replace('"', "'").replace("\\", "_") or "file"
    return {"Content-Disposition":
            f'{how}; filename="{ascii_name}"; '
            f"filename*=UTF-8''{quote(raw, safe='')}"}


def _money(paise, currency="INR"):
    """Paise as money a parent can read.

    Amounts are stored in the smallest unit so a balance is never out by a
    rounding error. A notification is read by the family, so it has to say
    ₹4,500 rather than 450000 — and with the Indian grouping, because that
    is where this is read.
    """
    try:
        whole, rest = divmod(int(paise or 0), 100)
    except Exception:
        return ""
    s = str(whole)
    if len(s) > 3:
        # 12,34,567 — last three, then pairs.
        head, tail = s[:-3], s[-3:]
        parts = []
        while len(head) > 2:
            parts.insert(0, head[-2:])
            head = head[:-2]
        if head:
            parts.insert(0, head)
        s = ",".join(parts + [tail])
    sym = {"INR": "₹", "USD": "$", "GBP": "£", "EUR": "€"}.get(
        (currency or "INR").upper(), (currency or "").upper() + " ")
    return f"{sym}{s}" + (f".{rest:02d}" if rest else "")


@app.get("/api/notifications")
def notifications(user: User = Depends(current_user), db: Session = Depends(get_db)):
    items = []
    # Background job alerts come first: they are time-sensitive in a way that
    # a teacher reply is not.
    for a in db.query(JobAlert).filter(JobAlert.user_id == user.id).order_by(
            JobAlert.created_at.desc()).limit(15).all():
        items.append({"type": a.kind, "icon": a.icon or "\U0001f4bc",
                      "text": a.text, "url": a.url or "",
                      "when": _aware(a.created_at).isoformat(),
                      "unread": not a.seen})
    t = teacher_row(user, db)
    if not t and not user.is_admin:
        # STUDENT: teacher replies to me, and assignments set in my classes
        for m in db.query(AssignmentMessage).filter(
                AssignmentMessage.student_id == user.id,
                AssignmentMessage.from_teacher == True).order_by(  # noqa: E712
                AssignmentMessage.created_at.desc()).limit(20).all():
            a = db.get(Assignment, m.assignment_id)
            if a:
                items.append({"type": "reply", "icon": "💬",
                              "text": f"Teacher replied on “{a.title}”",
                              "when": _aware(m.created_at).isoformat(), "aid": a.id})
        # What the office has recorded against them, raised and received.
        #
        # The fee screen existed and nothing pointed at it, so a bill was
        # only ever found by somebody who went looking. A fee is the one
        # thing here with a date attached that costs a family money to miss,
        # which makes it the last thing that should wait to be discovered.
        #
        # Derived, like everything else on this screen — no new table and no
        # backfill, so fees recorded before today appear too. A raised fee
        # is dated by when it was raised; a received one by when it was
        # marked, so paying shows as its own line rather than silently
        # removing the reminder.
        for f in db.query(FeeItem).filter(
                FeeItem.user_id == user.id).order_by(
                FeeItem.created_at.desc()).limit(20).all():
            owed = max(0, int(f.amount or 0) - int(f.paid or 0))
            money = _money(f.amount, f.currency)
            if f.paid_at and owed <= 0:
                items.append({
                    "type": "fee", "icon": "✅",
                    "text": f"Fee received: {f.title} · {money}",
                    "when": _aware(f.paid_at).isoformat()})
            else:
                due = f" · due {f.due_on}" if (f.due_on or "").strip() else ""
                items.append({
                    "type": "fee", "icon": "💳",
                    "text": (f"Fee: {f.title} · {_money(owed, f.currency)} "
                             f"to pay{due}"),
                    "when": _aware(f.created_at).isoformat()})

        my_cids = [cm.class_id for cm in db.query(ClassMember).filter(
            ClassMember.user_id == user.id).all()]
        if my_cids:
            for a in db.query(Assignment).filter(Assignment.class_id.in_(my_cids)) \
                    .order_by(Assignment.created_at.desc()).limit(20).all():
                items.append({"type": "assignment", "icon": "📌",
                              "text": f"Assignment: {a.subject+' · ' if a.subject else ''}{a.title}",
                              "when": _aware(a.created_at).isoformat(), "aid": a.id})
    else:
        # TEACHER: students messaging me on my assignments
        my_aids = [a.id for a in db.query(Assignment).filter(
            Assignment.teacher_id == user.id).all()]
        if my_aids:
            for m in db.query(AssignmentMessage).filter(
                    AssignmentMessage.assignment_id.in_(my_aids),
                    AssignmentMessage.from_teacher == False).order_by(  # noqa: E712
                    AssignmentMessage.created_at.desc()).limit(25).all():
                a = db.get(Assignment, m.assignment_id)
                su = db.get(User, m.student_id)
                items.append({"type": "msg", "icon": "💬",
                              "text": f"{su.name if su else 'A student'} messaged on “{a.title if a else ''}”",
                              "when": _aware(m.created_at).isoformat(),
                              "aid": (a.id if a else 0), "cid": (a.class_id if a else 0)})
        if t and t.role == "head":
            for r in db.query(TeacherRequest).filter(
                    TeacherRequest.school_id == t.school_id,
                    TeacherRequest.status == "open").order_by(
                    TeacherRequest.created_at.desc()).limit(20).all():
                ru = db.get(User, r.teacher_id)
                items.append({"type": "request", "icon": "🙋",
                              "text": f"{ru.name if ru else 'A teacher'} requests: {r.message[:80]}",
                              "when": _aware(r.created_at).isoformat()})
    items.sort(key=lambda x: x["when"], reverse=True)
    items = items[:40]
    # unread = newer than the last time they opened the inbox
    seen_row = db.query(Note).filter(Note.user_id == user.id, Note.k == "__notif_seen__").first()
    seen = seen_row.v if seen_row else ""
    unread = sum(1 for it in items if it["when"] > seen)
    return {"items": items, "unread": unread}


@app.post("/api/notifications/seen")
def notifications_seen(user: User = Depends(current_user), db: Session = Depends(get_db)):
    stamp = now().isoformat()
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == "__notif_seen__").first()
    if row:
        row.v = stamp
    else:
        db.add(Note(user_id=user.id, k="__notif_seen__", v=stamp))
    db.commit()
    return {"ok": True}


# ============ Admin: enrol schools and head teachers ============
class SchoolIn(BaseModel):
    name: str = Field(min_length=1, max_length=200)
    city: str = ""
    country: str = ""
    # The first administrator's name. The code created here is how they sign
    # in — there is no email and no password — so it has to carry the name
    # the account will be made under.
    admin_name: str = Field(default="", max_length=120)


@app.post("/api/admin/school")
def admin_create_school(body: SchoolIn, user: User = Depends(admin_user),
                        db: Session = Depends(get_db)):
    sc = School(name=body.name.strip()[:200], city=body.city.strip()[:120],
                country=body.country.strip()[:120])
    db.add(sc)
    db.commit()
    db.refresh(sc)
    # auto-create the school admin's code for this school
    code = _gen_head_code(db)
    db.add(TeacherCode(code=code, school=sc.name, school_id=sc.id,
                       is_head=True, label=body.admin_name.strip()[:120]))
    db.commit()
    return {"id": sc.id, "name": sc.name, "head_code": code,
            "admin_name": body.admin_name.strip()}


class HeadCodeIn(BaseModel):
    # Whose code this is. An administrator signs in with the code alone, so
    # the code has to carry the name the account will be created under — it
    # cannot invent one, and "Administrator" for four different people in one
    # office is a record nobody can read.
    name: str = Field(default="", max_length=120)
    replace_all: bool = False


@app.post("/api/admin/school/{sid}/head-code")
def admin_new_head_code(sid: int, body: HeadCodeIn = HeadCodeIn(),
                        replace_all: bool = False,
                        user: User = Depends(admin_user),
                        db: Session = Depends(get_db)):
    """Issue an admin code for a school. Several may be live at once.

    This used to deactivate every previous head code before issuing a new
    one. The intention was revocation — a head who leaves must not be able to
    re-register — and the effect was that a school could only ever have one
    administrator: giving the second one their code cancelled the first one's,
    silently, and the first person found out the next time they tried to use
    it.

    A school of any size has more than one person in the office. So issuing
    is now just issuing, and revoking is its own act with its own route,
    which is the honest shape: one button that does two things is how you
    take away access you meant to grant.

    replace_all=true keeps the old behaviour for the case it was really for —
    an administrator has left and every code issued so far should stop
    working.
    """
    sc = db.get(School, sid)
    if not sc:
        raise HTTPException(404, "School not found")
    revoked = 0
    if body.replace_all:
        replace_all = True
    if replace_all:
        for old in db.query(TeacherCode).filter(
                TeacherCode.school_id == sid,
                TeacherCode.is_head == True,                    # noqa: E712
                TeacherCode.active == True).all():              # noqa: E712
            old.active = False
            revoked += 1
    code = _gen_head_code(db)
    db.add(TeacherCode(code=code, school=sc.name, school_id=sc.id,
                       is_head=True, label=body.name.strip()[:120]))
    db.commit()
    live = db.query(func.count(TeacherCode.id)).filter(
        TeacherCode.school_id == sid,
        TeacherCode.is_head == True,                            # noqa: E712
        TeacherCode.active == True).scalar()                    # noqa: E712
    return {"head_code": code, "revoked": revoked, "live_codes": live}


@app.get("/api/admin/school/{sid}/head-codes")
def admin_list_head_codes(sid: int, user: User = Depends(admin_user),
                          db: Session = Depends(get_db)):
    """Every admin code for a school, live and spent, and who redeemed it.

    Issuing without a list is issuing into the dark: nobody could say how many
    codes were out, which had been used, or by whom — so revoking one meant
    revoking all of them and starting again.
    """
    sc = db.get(School, sid)
    if not sc:
        raise HTTPException(404, "School not found")
    rows = (db.query(TeacherCode)
              .filter(TeacherCode.school_id == sid,
                      TeacherCode.is_head == True)              # noqa: E712
              .order_by(TeacherCode.id.desc()).limit(100).all())
    # Who is actually a school admin here, so an unredeemed code is visibly
    # different from one somebody is using.
    heads = (db.query(User, TeacherAccess)
               .join(TeacherAccess, TeacherAccess.user_id == User.id)
               .filter(TeacherAccess.school_id == sid,
                       TeacherAccess.role == "head").all())
    return {
        "school": sc.name,
        "codes": [{"id": c.id, "code": c.code, "active": bool(c.active)}
                  for c in rows],
        "admins": [{"user_id": u.id, "name": u.name, "email": u.email}
                   for u, _ta in heads],
    }


@app.delete("/api/admin/school/{sid}/head-code/{code_id}")
def admin_revoke_head_code(sid: int, code_id: int,
                           user: User = Depends(admin_user),
                           db: Session = Depends(get_db)):
    """Stop one admin code working, leaving the others alone.

    The counterpart to issuing. A code is deactivated rather than deleted, so
    the record that it existed survives — a school asking "who was given
    access, and when did it stop" is asking a question a deleted row cannot
    answer.

    This does not remove anybody who has already redeemed it. A code is how
    somebody became an administrator, not what keeps them one; taking their
    access away is done on the staff list, where you can see who they are.
    """
    c = db.get(TeacherCode, code_id)
    if not c or c.school_id != sid or not c.is_head:
        raise HTTPException(404, "No such code for that school")
    c.active = False
    db.commit()
    return {"ok": True, "code_id": code_id, "active": False,
            "note": "Anyone who already redeemed this code is still an "
                    "administrator. Remove them on the school's staff list."}


@app.delete("/api/admin/school/{sid}")
def admin_delete_school(sid: int, confirm: str = "",
                        user: User = Depends(admin_user),
                        db: Session = Depends(get_db)):
    """Delete a school and everything that belongs to it.

    It used to delete the School row alone. Nothing else references it by
    foreign key — school_id is a plain integer on the teacher codes, the
    staff access rows and the classrooms — so the school vanished from the
    list and its teachers, its codes and its classes all stayed behind,
    attached to a school that no longer existed. The admin screen showed
    "Schools: none yet" above three teachers and two classrooms.

    Now it takes them with it, in the order that leaves nothing orphaned:

      * every classroom, through the same explicit clean-up delete_class
        uses — the register, assignments, submissions, discussion, material
        and timetable — because SQLite does not enforce ON DELETE CASCADE
        and relying on it means two databases behaving differently;
      * the staff access rows, so nobody is left a teacher of nowhere;
      * the school's codes, so none of them can be redeemed afterwards.

    Accounts are NOT deleted. A teacher's account may be their own — an
    ordinary sign-in at another school, or a personal one — and a platform
    administrator removing a school has no business deleting a person. What
    goes is their access to a school that no longer exists. A code-issued
    account left with no access is inert: it can sign in and see nothing.

    Confirmed by typing the school's name, for the same reason deleting a
    class is: this removes a year of other people's work, and a yes/no box
    is answered without reading.
    """
    sc = db.get(School, sid)
    if not sc:
        return {"ok": True, "deleted": ""}

    classes = db.query(Klass).filter(Klass.school_id == sid).all()
    staff = db.query(TeacherAccess).filter(TeacherAccess.school_id == sid).all()
    codes = db.query(TeacherCode).filter(TeacherCode.school_id == sid).all()
    held = {"classes": len(classes), "staff": len(staff), "codes": len(codes),
            "students": db.query(RosterName).filter(
                RosterName.class_id.in_([k.id for k in classes]),
                RosterName.claimed_by != 0).count() if classes else 0}

    # Codes are deliberately NOT counted here. Creating a school mints one, so
    # counting them meant a school made thirty seconds ago and never used
    # still demanded its name typed back — and a confirmation that fires when
    # there is nothing to lose is one people learn to click through.
    # Classrooms, staff and signed-in children are what make this expensive.
    substantial = held["classes"] or held["staff"] or held["students"]
    if substantial and confirm.strip().lower() != (sc.name or "").lower():
        raise HTTPException(409, {
            "message": (
                f"{sc.name} still has {held['classes']} classroom(s), "
                f"{held['staff']} member(s) of staff and {held['students']} "
                f"signed-in student(s). Deleting it removes the classes and "
                f"everything in them, and takes away every teacher's access. "
                f"Type the school's name to confirm."),
            "needs_confirm": sc.name, "holds": held})

    for k in classes:
        aids = [a.id for a in
                db.query(Assignment).filter(Assignment.class_id == k.id).all()]
        if aids:
            db.query(Submission).filter(
                Submission.assignment_id.in_(aids)).delete(synchronize_session=False)
            db.query(AssignmentMessage).filter(
                AssignmentMessage.assignment_id.in_(aids)).delete(synchronize_session=False)
        for model in (Assignment, RosterName, ClassMember, ClassroomTeacher,
                      SubjectSlot, ClassPost, Material, ScheduleItem):
            db.query(model).filter(model.class_id == k.id).delete(
                synchronize_session=False)
        db.delete(k)

    db.query(TeacherAccess).filter(
        TeacherAccess.school_id == sid).delete(synchronize_session=False)
    db.query(TeacherCode).filter(
        TeacherCode.school_id == sid).delete(synchronize_session=False)
    db.delete(sc)
    db.commit()
    return {"ok": True, "deleted": sc.name, "removed": held,
            "note": "Accounts were kept. What was removed is their access to "
                    "this school — a platform administrator deleting a school "
                    "should not delete people."}


class ProductIn(BaseModel):
    product: str = Field(default="craxlearn", max_length=16)


@app.post("/api/admin/school/{sid}/product")
def admin_set_product(sid: int, body: ProductIn,
                      user: User = Depends(admin_user),
                      db: Session = Depends(get_db)):
    """Turn the job board on or off for one institution.

    The switch a school actually asks about, and the reason School.product
    exists. Admin only: a head teacher deciding their own pupils may see a
    job board is the one person who should not be able to.

    Takes effect on the institution's next request — the gate reads this
    row every time rather than caching it, precisely so a mistake here can
    be undone in one press.
    """
    sc = db.get(School, sid)
    if not sc:
        raise HTTPException(404, "No such school")
    want = (body.product or "").strip().lower()
    if want not in ("craxlearn", "both"):
        raise HTTPException(
            400, 'Product must be "craxlearn" (teaching only) or "both" '
                 '(teaching and the job board).')
    sc.product = want
    db.commit()
    n = (db.query(func.count(ClassMember.id))
           .join(Klass, Klass.id == ClassMember.class_id)
           .filter(Klass.school_id == sid).scalar() or 0)
    return {"ok": True, "product": want, "learners_affected": n,
            "note": ("The job board is now open to learners here who are 18 "
                     "or over. Under-18s and class-code logins still cannot "
                     "reach it." if want == "both" else
                     "The job board is closed to everybody at this school.")}


class ResetUsersIn(BaseModel):
    # Typed out in full, by hand, every time. A confirm flag is a checkbox
    # somebody ticks without reading; a sentence they have to type is a
    # sentence they have to read first.
    confirm: str = Field(default="", max_length=80)
    keep_schools: bool = True


RESET_PHRASE = "DELETE ALL NON ADMIN ACCOUNTS"


@app.get("/api/admin/reset-users/preview")
def admin_reset_preview(user: User = Depends(admin_user),
                        db: Session = Depends(get_db)):
    """What deleting every non-admin account would actually destroy.

    Shown before, never after. The counts that matter are the ones somebody
    would regret: paid subscriptions, submitted work, saved resumes. A
    number on the screen is the only thing standing between "start fresh"
    and finding out on Monday what start fresh meant.
    """
    q = db.query(User).filter(User.is_admin == False)          # noqa: E712
    ids = [r[0] for r in q.with_entities(User.id).all()]
    paid = q.filter(User.plan != "free").count()
    return {
        "phrase": RESET_PHRASE,
        "users": len(ids),
        "paying": paid,
        "submissions": (db.query(func.count(Submission.id))
                        .filter(Submission.user_id.in_(ids)).scalar() or 0
                        if ids else 0),
        "resumes": (db.query(func.count(Note.id))
                    .filter(Note.user_id.in_(ids),
                            Note.k.like("resume%")).scalar() or 0
                    if ids else 0),
        "teachers": db.query(func.count(TeacherAccess.id)).scalar() or 0,
        "warning": ("This cannot be undone. Paying subscribers keep being "
                    "billed by the payment provider after their account is "
                    "gone — cancel those first."),
    }


@app.post("/api/admin/reset-users")
def admin_reset_users(body: ResetUsersIn, user: User = Depends(admin_user),
                      db: Session = Depends(get_db)):
    """Delete every non-admin account so everybody signs up again.

    Guarded three ways, because it is the most destructive thing this
    codebase can do and it is one request away from being done by accident:
    admin only, the exact phrase typed out, and a preview endpoint that
    exists to be read first.

    Schools, classes and rosters are kept by default. Deleting those too
    would take the join codes with them, and then nobody can come back in —
    a "start fresh" that also destroys the way back is not a reset, it is
    an outage with extra steps.
    """
    if body.confirm.strip().upper() != RESET_PHRASE:
        raise HTTPException(
            400, f'To confirm, send confirm="{RESET_PHRASE}" exactly. '
                 f"Read /api/admin/reset-users/preview first.")

    ids = [r[0] for r in db.query(User.id)
           .filter(User.is_admin == False).all()]                # noqa: E712
    if not ids:
        return {"ok": True, "deleted": 0}

    # Rosters first, and by hand: claimed_by is a plain integer, not a
    # foreign key, so nothing would cascade and every name would stay
    # claimed by an account that no longer exists — a register where
    # nobody can sign in and the teacher cannot see why.
    freed = (db.query(RosterName).filter(RosterName.claimed_by.in_(ids))
               .update({RosterName.claimed_by: 0, RosterName.claimed_at: None},
                       synchronize_session=False))

    # Everything else hangs off users.id with ON DELETE CASCADE, so the
    # rows go with the account. Deleted in chunks: a single IN clause over
    # tens of thousands of ids is a statement Postgres will refuse to plan.
    gone = 0
    for i in range(0, len(ids), 500):
        chunk = ids[i:i + 500]
        gone += (db.query(User).filter(User.id.in_(chunk))
                   .delete(synchronize_session=False))
        db.commit()

    print(f"ADMIN RESET: {gone} accounts deleted by {user.email}, "
          f"{freed} roster names freed")
    return {"ok": True, "deleted": gone, "roster_names_freed": freed,
            "kept": "admins, schools, classes and class codes"}


@app.get("/api/admin/schools")
def admin_list_schools(user: User = Depends(admin_user), db: Session = Depends(get_db)):
    out = []
    for sc in db.query(School).order_by(School.created_at.desc()).all():
        heads = db.query(TeacherAccess, User).join(User, User.id == TeacherAccess.user_id) \
            .filter(TeacherAccess.school_id == sc.id, TeacherAccess.role == "head").all()
        classes = db.query(Klass).filter(Klass.school_id == sc.id).all()
        active_code = db.query(TeacherCode).filter(
            TeacherCode.school_id == sc.id, TeacherCode.is_head == True,  # noqa: E712
            TeacherCode.active == True).order_by(TeacherCode.created_at.desc()).first()  # noqa: E712
        out.append({
            "id": sc.id, "name": sc.name, "city": sc.city, "country": sc.country,
            "product": sc.product or "craxlearn",
            "head_code": active_code.code if active_code else None,
            "heads": [{"id": u.id, "name": u.name, "email": u.email} for ta, u in heads],
            "classrooms": [{"id": k.id, "name": k.name, "code": k.join_code} for k in classes],
        })
    return {"schools": out}


@app.get("/api/admin/teacher-codes")
def list_teacher_codes(user: User = Depends(admin_user), db: Session = Depends(get_db)):
    codes = db.query(TeacherCode).order_by(TeacherCode.created_at.desc()).all()
    teachers = db.query(TeacherAccess, User).join(User, User.id == TeacherAccess.user_id).all()
    online_since = now() - dt.timedelta(minutes=10)

    # classrooms with head teacher, code, counts
    classrooms = []
    subjects = set()
    for k in db.query(Klass).order_by(Klass.created_at.desc()).all():
        head = db.get(User, k.teacher_id)
        nstu = db.query(func.count(ClassMember.id)).filter(ClassMember.class_id == k.id).scalar()
        nco = db.query(func.count(ClassroomTeacher.id)).filter(ClassroomTeacher.class_id == k.id).scalar()
        for (s,) in db.query(Assignment.subject).filter(Assignment.class_id == k.id).distinct():
            if s:
                subjects.add(s)
        classrooms.append({"id": k.id, "name": k.name, "code": k.join_code,
                           "school": k.school, "head": head.name if head else "",
                           "students": nstu, "teachers": (nco or 0) + 1})

    return {
        "codes": [{"id": c.id, "code": c.code, "school": c.school, "active": c.active}
                  for c in codes],
        "teachers": [{"id": u.id, "name": u.name, "email": u.email, "school": ta.school,
                      "online": bool(u.last_seen and (u.last_seen if u.last_seen.tzinfo
                                     else u.last_seen.replace(tzinfo=dt.timezone.utc)) >= online_since)}
                     for ta, u in teachers],
        "schools": sorted({(ta.school or "").strip() for ta, u in teachers if (ta.school or "").strip()}),
        "classrooms": classrooms,
        "subjects": sorted(subjects),
    }


