# ---------------------------- curriculum ----------------------------------
def serialise_track(t: Track, include_unpublished=False):
    lessons = [l for l in t.lessons if l.published or include_unpublished]
    return {
        "id": t.slug, "icon": t.icon, "name": t.name, "level": t.level,
        "color": t.color, "weeks": t.weeks, "lang": t.lang, "desc": t.desc,
        "audience": t.audience or "graduate",
        "outcomes": json.loads(t.outcomes or "[]"),
        "quiz": json.loads(t.quiz or "[]"),
        "published": t.published,
        "lessons": [{
            "id": l.slug, "title": l.title, "mins": l.mins, "lang": l.lang,
            "content": l.content,
            # Normalised on the way out as well as in. Seeding skips a track
            # that already exists, so every database seeded before _links
            # existed still holds the {"title","url"} rows that rendered as
            # "undefined" — and those are the live ones. Doing it here fixes
            # them without a migration and without re-seeding anybody's
            # curriculum.
            "videos": _links(json.loads(l.videos or "[]")),
            "refs": _links(json.loads(l.refs or "[]")),
            "lab": json.loads(l.lab or "{}"),
            "exercises": json.loads(l.exercises or "[]"),
            "worksheet": json.loads(l.worksheet or "[]"),
            "published": l.published,
        } for l in lessons],
    }


@app.get("/api/curriculum")
def curriculum(user: User = Depends(_reader_or_board),
               db: Session = Depends(get_db)):
    tracks = db.query(Track).filter(Track.published == True).order_by(Track.position).all()  # noqa: E712
    return {"tracks": [serialise_track(t) for t in tracks]}


XP_PER_EXERCISE = 10
XP_PER_LESSON = 25
XP_PER_QUIZ = 50
XP_PER_LEVEL = 250


def _compute_stats(rows, all_quizzes, notes):
    """XP, level and streak, derived from existing records.

    Derived rather than stored: it can never be double-awarded, and it
    stays correct even if progress rows are edited or deleted.
    """
    lessons_done = sum(1 for r in rows if r.completed)
    ex_passed = sum(1 for n in notes if n.k.startswith("ex_") and n.v == "1")
    quiz_passed = len({q.track_slug for q in all_quizzes if q.passed})

    xp = (ex_passed * XP_PER_EXERCISE
          + lessons_done * XP_PER_LESSON
          + quiz_passed * XP_PER_QUIZ)
    level = 1 + xp // XP_PER_LEVEL

    # Streak: consecutive days (ending today or yesterday) with any activity.
    days = set()
    for r in rows:
        d = r.updated_at or r.completed_at
        if d:
            days.add(d.date())
    for q in all_quizzes:
        if q.created_at:
            days.add(q.created_at.date())

    today = now().date()
    day = today if today in days else today - dt.timedelta(days=1)
    streak = 0
    while day in days:
        streak += 1
        day -= dt.timedelta(days=1)

    return {
        "xp": xp, "level": level, "streak": streak,
        "level_progress": (xp % XP_PER_LEVEL) / XP_PER_LEVEL,
        "next_level_at": (xp // XP_PER_LEVEL + 1) * XP_PER_LEVEL,
    }


@app.get("/api/progress")
def get_progress(user: User = Depends(current_user), db: Session = Depends(get_db)):
    rows = db.query(Progress).filter(Progress.user_id == user.id).all()
    all_quizzes = db.query(QuizResult).filter(QuizResult.user_id == user.id).all()
    notes = db.query(Note).filter(Note.user_id == user.id).all()
    return {
        "done": {r.lesson_slug: True for r in rows if r.completed},
        "code": {r.lesson_slug: r.code for r in rows if r.code},
        "quiz": {q.track_slug: True for q in all_quizzes if q.passed},
        # Saved explanations are whole lessons and are deliberately
        # absent here. This payload is sent on every page load; their
        # bodies are fetched by the notes page when it is opened.
        #
        # Ask's saved answers need their TITLES on every page load — that is
        # what draws the "Saved answers" list — and nothing more. They used
        # to arrive whole, which is why the client kept them under five
        # thousand characters with a blind slice: a page load carrying twenty
        # lessons is twenty lessons nobody asked for. A stub draws the list;
        # the body is fetched when one is opened or downloaded.
        "notes": {n.k: (_saved_stub(n.v) if n.k.startswith(ASK_SAVED_PREFIX)
                        else n.v)
                  for n in notes if not n.k.startswith(SAVED_PREFIX)},
        "path": user.path,
        "stats": _compute_stats(rows, all_quizzes, notes),
    }


@app.post("/api/progress")
def set_progress(body: ProgressIn, user: User = Depends(current_user), db: Session = Depends(get_db)):
    row = db.query(Progress).filter(
        Progress.user_id == user.id, Progress.lesson_slug == body.lesson).first()
    if not row:
        row = Progress(user_id=user.id, lesson_slug=body.lesson)
        db.add(row)
    if body.attempt:
        row.attempts = (row.attempts or 0) + 1
    if body.code is not None:
        row.code = body.code[:20000]
    if body.completed is not None:
        row.completed = body.completed
        row.completed_at = now() if body.completed else None
    db.commit()
    return {"ok": True}


@app.post("/api/quiz")
def post_quiz(body: QuizIn, user: User = Depends(current_user), db: Session = Depends(get_db)):
    passed = body.total > 0 and body.score == body.total
    db.add(QuizResult(user_id=user.id, track_slug=body.track,
                      score=body.score, total=body.total, passed=passed))
    db.commit()
    return {"passed": passed}


SAVED_PREFIX = "sbsave_"
# Ask Axle keeps its answers under a prefix of its own. It is a saved lesson
# by every measure that matters here — same size, same "it fails when you
# read it back, not when you save it" failure — and it was missing from
# every rule written for the other one.
ASK_SAVED_PREFIX = "asksave_"
SAVED_PREFIXES = (SAVED_PREFIX, ASK_SAVED_PREFIX)


def _saved_stub(v: str) -> str:
    """Enough of a saved answer to list it, and none of the lesson.

    The list needs a title, the question and when it was kept. Returning the
    whole thing on every page load is how the client ended up slicing lessons
    to 4,900 characters to keep the payload down — and a lesson cut at 4,900
    characters is invalid JSON, which fails silently when it is read back.
    """
    try:
        d = json.loads(v)
    except Exception:
        return v          # already unreadable; hand it over rather than hide it
    return json.dumps({"title": d.get("title") or "Saved answer",
                       "q": d.get("q") or "",
                       "subject": d.get("subject") or "",
                       "level": d.get("level") or "",
                       "ts": d.get("ts") or 0,
                       "stub": True})


@app.get("/api/notes/saved")
def saved_list(user: User = Depends(current_user), db: Session = Depends(get_db)):
    """What a person has kept, without the keeping.

    Titles and dates only. The bodies are whole lessons and there is no reason
    to send twenty of them to draw a list of twenty titles.
    """
    rows = db.query(Note).filter(Note.user_id == user.id,
                                 Note.k.startswith(SAVED_PREFIX)).all()
    out = []
    for r in rows:
        try:
            d = json.loads(r.v)
        except Exception:
            continue          # truncated or hand-edited; not worth a 500
        out.append({"key": r.k,
                    "title": d.get("title") or "Untitled",
                    "topic": d.get("topic") or "",
                    "when": d.get("when") or ""})
    out.sort(key=lambda x: x["when"], reverse=True)
    return {"items": out}


@app.get("/api/notes/saved/{key}")
def saved_one(key: str, user: User = Depends(current_user),
              db: Session = Depends(get_db)):
    """One saved explanation, opened on purpose."""
    if not key.startswith(SAVED_PREFIXES):
        raise HTTPException(400, "Not a saved explanation.")
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == key).first()
    if not row:
        raise HTTPException(404, "That one is not saved any more.")
    try:
        return json.loads(row.v)
    except Exception:
        raise HTTPException(422, "That saved explanation did not survive "
                                 "storage and cannot be opened.")


@app.post("/api/note")
def post_note(body: NoteIn, user: User = Depends(current_user), db: Session = Depends(get_db)):
    if body.key == "__path__":
        user.path = body.value[:40]
        db.commit()
        return {"ok": True}
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == body.key).first()
    if body.value == "":
        if row:
            db.delete(row)
            db.commit()
        return {"ok": True}
    if not row:
        row = Note(user_id=user.id, k=body.key[:120])
        db.add(row)
    # Resume payloads (which can include a base64 photo and a full positional
    # layout) are much larger than a checklist note, so give resume keys plenty
    # of room; everything else stays modest.
    # A saved explanation is a whole lesson, not a checklist line. At
    # 5000 it was truncated into invalid JSON, which fails when it is
    # read back rather than when it is saved — the worst place to
    # find out that something did not keep.
    if body.key.startswith("resume"):
        cap = 600_000
    elif body.key.startswith(SAVED_PREFIXES):
        cap = 80_000
    else:
        cap = 5000
    row.v = body.value[:cap]
    db.commit()
    return {"ok": True}


