import re as _re

# Who the tutor is, what grade she is pitching at, and the short list of
# panels she is allowed to open. Kept out of this file because the same
# persona has to reach the board, the voice and the corner bot, and three
# copies of it drifted into three different teachers.
import dalia as _dalia                                              # noqa: E402

# Where a learner's questions are kept, and where answers may be sourced
# from. Both halves of that are policy rather than plumbing, so they live in
# one readable file instead of being spread across the endpoints that
# happen to enforce them.
import craxlearn as _cl                                             # noqa: E402

# The allowlisted arithmetic evaluator. Imported again further down for the
# lesson checks; imported here too so the classroom calculator's dependency
# is visible beside the endpoint that uses it rather than 7,000 lines away.
# The measured-structure sources and the picture search, both used by the
# board further down and by Craxlearn's own structure and search screens.
# Imported here so those endpoints' dependencies are visible beside them.
import scene as _scene
import models3d as _models3d                                              # noqa: E402
import lattice as _lattice                                          # noqa: E402
import layers as _layers                                            # noqa: E402
import orbits as _orbits                                            # noqa: E402
import molecule as _molecule                                        # noqa: E402
import protein as _protein                                          # noqa: E402
import images as _images                                            # noqa: E402
import reference as _reference                                      # noqa: E402
import papers as _papers                                            # noqa: E402
import maths as _maths                                              # noqa: E402


def _scope_of(db, user):
    """Which pool this person's questions and answers belong to.

    A teacher's institution is on their access row. A student's comes
    through the class they joined, which is the only link a student has to a
    school at all.

    Read on every cached request, so it is one indexed lookup and then a
    second only for people who are not teachers. Wrong in the safe direction
    on failure: anybody the query cannot resolve who nonetheless has a class
    membership is treated as an institution learner with an unknown school,
    never as a member of the public pool.
    """
    ta = (db.query(TeacherAccess)
            .filter(TeacherAccess.user_id == user.id).first())
    if ta:
        return _cl.scope_of(ta.school_id, in_institution=True)
    row = (db.query(Klass.school_id)
             .join(ClassMember, ClassMember.class_id == Klass.id)
             .filter(ClassMember.user_id == user.id).first())
    if row is None:
        return _cl.PUBLIC
    return _cl.scope_of(row[0], in_institution=True)


def _record_learning(db, user, scope, kind, text, subject="", level=""):
    """Note that this was asked, inside the asker's own institution.

    Fire and forget, exactly like the client-side history it sits beside: an
    answer must never fail because the record did. A learner who gets a 500
    instead of a lesson because a logging table was locked has been failed
    by the part of the system that was supposed to be invisible.
    """
    text = _cl.redact(text)
    if not text or kind not in _cl.RECORD_KINDS:
        return
    try:
        db.add(LearnRecord(user_id=user.id, scope=scope,
                           school_id=_cl.school_id_of(scope), kind=kind,
                           text=text, subject=(subject or "")[:60],
                           level=(level or "")[:60]))
        db.commit()
        # Trimmed here rather than by a sweep, so the table cannot grow
        # unbounded between deploys on a site with no scheduled jobs.
        n = (db.query(func.count(LearnRecord.id))
               .filter(LearnRecord.user_id == user.id).scalar() or 0)
        if n > _cl.KEEP_PER_LEARNER:
            old = (db.query(LearnRecord.id)
                     .filter(LearnRecord.user_id == user.id)
                     .order_by(LearnRecord.created_at.asc())
                     .limit(n - _cl.KEEP_PER_LEARNER).all())
            (db.query(LearnRecord)
               .filter(LearnRecord.id.in_([r[0] for r in old]))
               .delete(synchronize_session=False))
            db.commit()
    except Exception as e:
        db.rollback()
        print(f"Learning record not stored: {type(e).__name__}: {e}")


class AskIn(BaseModel):
    question: str = Field(..., min_length=2, max_length=500)
    subject: str = Field("General", max_length=60)
    level: str = Field("School", max_length=60)


def _cached_json(db, row, what="lesson", need="steps"):
    """A cached row's payload, or None if it cannot be used.

    Reading a cache must not be able to fail. A row that will not parse, or
    that parses into something without the field the caller needs, is treated
    as though it had never been written: dropped, and reported as a miss.

    Deleting it matters. A row that raises on every read but stays in the
    table means the next request regenerates and pays for a model call again,
    which turns a display bug into a recurring cost.
    """
    if row is None:
        return None
    try:
        data = json.loads(row.lesson)
    except Exception as e:
        print(f"Cache row {getattr(row, 'qkey', '?')!r} will not parse "
              f"({type(e).__name__}) — dropping it and rebuilding")
        data = None
    else:
        if not isinstance(data, dict) or (need and not data.get(need)):
            print(f"Cache row {getattr(row, 'qkey', '?')!r} has no {need!r} "
                  f"— dropping it and rebuilding")
            data = None
    if data is None:
        try:
            db.delete(row)
            db.commit()
        except Exception:
            db.rollback()
        return None
    return data


def _norm_q(s: str) -> str:
    """Collapse a question to a stable cache key so trivial differences in
    spacing, case or punctuation all hit the same stored answer."""
    return _re.sub(r"\s+", " ", _re.sub(r"[^a-z0-9\s]", "", s.lower())).strip()


def _fallback_lesson(subject: str, level: str) -> dict:
    return {
        "title": "AI teacher not set up yet",
        "steps": [
            "Axle's ask-anything teacher needs an API key to think.",
            "The site owner adds a free GEMINI_API_KEY in the server settings.",
            "Once it is set, ask any question on any subject.",
            "Answers you get are saved, so asking again is instant and free.",
        ],
        "takeaway": "Everything else on Craxle works without this.",
    }


# What the three levels actually mean, in the only place it can matter.
#
# The picker offers Beginner, Intermediate and Advanced, and the prompt said
# "the learner's level is: Advanced" and, further down, "language matched to
# the stated level". A model given that writes the same lesson three times
# with slightly different adjectives — which is what a teacher saw: three
# buttons and one answer.
#
# A level is not a tone. It is a decision about what may be assumed, how far
# to go, and what to leave out, so it is written here as those decisions.
_LEVELS = {
    "Beginner":
        "LEVEL: BEGINNER. Assume no background at all. Define every term the "
        "first time it appears, in ordinary words, before using it. Prefer a "
        "concrete picture to a general rule, and put the picture first. No "
        "symbol where a word will do, and no formula without the sentence "
        "saying what it means. Short lines, more of them, one small step at a "
        "time. Better to leave out an exception than to lose them on it.\n\n",
    "Intermediate":
        "LEVEL: INTERMEDIATE. Assume the ordinary school grounding in this "
        "subject and do not re-teach it. Use the standard terms and notation, "
        "defining only what is genuinely new here. Give the rule AND the "
        "reason it holds. One worked example, then the general case. Name the "
        "common mistake and why it is tempting.\n\n",
    "Advanced":
        "LEVEL: ADVANCED. Assume fluency: the standard results, the notation "
        "and the vocabulary are known and are not explained. Go to the "
        "mechanism — why it is true, where it fails, what it is a special "
        "case of, how it meets the neighbouring ideas. State conditions and "
        "edge cases precisely. Do not spend lines on definitions they already "
        "have; the value here is depth, not breadth.\n\n",
    # Nobody said. This is now the normal case on Ask Axle: the three chips
    # were removed because they were a question asked before the question,
    # and the answer to them was already sitting in the words of the thing
    # being asked. "What is a derivative" and "prove the chain rule from the
    # limit definition" do not need a picker to tell them apart.
    #
    # The named levels above stay, for the callers that genuinely know one —
    # the classroom board is told the class it is teaching.
    "": "LEVEL: READ IT FROM THE QUESTION. Nobody has stated a level, and "
        "the question itself says more than a chip would: what it takes for "
        "granted, the notation it reaches for, whether it asks what a thing "
        "IS or why it holds. Pitch it there. Define a term when the question "
        "suggests it is new, and do not re-explain what the asker has "
        "clearly already got. When it is genuinely ambiguous, teach the "
        "middle and let the depth come at the end, where it costs a reader "
        "who did not need it nothing.\n\n",
}


def _ask_prompt(question: str, subject: str, level: str) -> str:
    return (
        f"You are Axle, a warm, patient teacher in India explaining on a "
        f"blackboard. A learner asked: \"{question}\"\n\n"
        f"{_LEVELS.get(level or '', _LEVELS[''])}"
        'NO GREETING, NO PREAMBLE. The first line is the first real thing you have to say. Never open with "Welcome", "Dear students", "Let us look at this together", "Great question" or any other pleasantry, and never spend a line restating the question back — the learner has it in front of them and the board only shows a few lines at a time, so a line that carries nothing is a line of the lesson thrown away. Begin with the substance and keep going.\n\nANSWER THE QUESTION THAT WAS ASKED. Read it closely enough to notice what it is really asking, then answer that. If it is a problem to solve, solve it and reach the actual answer — do not restate the setup, describe an approach, and stop. Work each step so the reader can follow the arithmetic or the argument, and finish. If the question has no clean answer, or the answer is that no solution exists, say so and show what rules the others out. Every claimed answer gets substituted back into the original problem and checked before you state it.\n\nINDIA FIRST, WHEN AN EXAMPLE IS NEEDED. Set examples here: rupees rather than dollars, Indian cities, Indian firms, the exams and boards people here actually sit, Indian regulations and Indian case law. Use a foreign example only when the subject genuinely is foreign — a US statute in a lesson on US law, a landmark experiment done where it was done. Never reach for another country\'s setting when a local one would serve.\n\n'
        f"Explain it the way a good teacher writes on the board: short lines, "
        f"one idea per line, at the level set above, with a "
        f"small real-life Indian example where natural. Be accurate. The "
        f"question says what it is about; answer THAT, whatever field it "
        f"turns out to belong to. If it "
        f"asks for something unsafe or inappropriate for a student, gently "
        f"redirect to safe learning instead.\n\n"
        f"Respond with ONLY valid JSON, no markdown, no backticks, in exactly "
        f"this shape:\n"
        f'{{"title": "<topic in 2-6 words>", "steps": ["<line 1>", "<line 2>", '
        f'"... use as many short lines as the question needs: a few for a '
        f'simple question, more for a detailed one (up to about 25)"], '
        f'"takeaway": "<one sentence to remember>"}}'
    )


def _parse_lesson(text: str, question: str) -> dict:
    """Every provider returns plain text; turn it into a validated lesson."""
    clean = (text or "").replace("```json", "").replace("```", "").strip()
    try:
        les = json.loads(clean)
    except Exception:
        lines = [
            _re.sub(r"^[-*\d.\s]+", "", ln).strip()
            for ln in _re.split(r"\n+", clean) if ln.strip()
        ]
        les = {"title": question[:40], "steps": lines[:9], "takeaway": ""}
    if not isinstance(les.get("steps"), list) or not les["steps"]:
        raise ValueError("empty lesson")
    return {
        "title": str(les.get("title", question))[:120],
        "steps": [str(s)[:300] for s in les["steps"]][:40],
        # Text only. Drawings — flat or 3D — are the Pro board's, which is
        # where the room and the step structure to hang them on exists.
        "takeaway": str(les.get("takeaway", ""))[:300],
    }


def _upstream_ok(r, provider):
    """Raise a readable error carrying the provider's own message, so a bad
    key or a wrong model name shows up clearly instead of a generic failure."""
    if r.status_code >= 400:
        body = (r.text or "")[:300].replace("\n", " ")
        raise RuntimeError(f"{provider} HTTP {r.status_code}: {body}")


AI_DAILY_LIMIT = 50   # resume AI checks per user per day (admins exempt)

# Whole papers, per person, per day.
#
# A paper is not one AI call. Sixty questions is a reading pass over twenty
# pages and twenty solving calls on the strongest model configured, and it is
# the only thing here that can run up a real bill in an afternoon — a class of
# thirty with a folder of past papers is a plausible Tuesday. Five is a
# teacher's working day and nowhere near a script's.
#
# Counted on the READING, because that is what a paper is. Re-solving a paper
# already read costs nothing and is not counted: every question is cached, so
# opening yesterday's paper again is free and stays free.
PAPERS_PER_DAY = int(env("PAPERS_PER_DAY", "5") or 5)

# ---- plans ---------------------------------------------------------------
# Prices in the smallest unit (paise / cents), which is what both gateways
# expect and avoids float rounding on money.
PLANS = {
    "free": {"name": "Free", "ai_total": 0, "kits_total": 0,
             "inr": None, "intl": None},
    # One price worldwide, charged in US dollars through Stripe — Indian cards
    # convert it themselves, the same way foreign cards used to convert the
    # rupee price. Kept as a single tier on purpose: two tiers make people stop
    # and compare instead of deciding. Amounts are in cents.
    "pro": {"name": "Pro", "ai_month": None, "kits_month": None,   # unlimited
            # The longer terms keep the same 10 / 20 / 25% discounts, and the
            # percentages on the plans page are computed from these numbers
            # rather than written next to them — so a price change can never
            # leave the page advertising a saving that is not real.
            "usd_month": 999,         # $9.99    —  $9.99/mo
            "usd_quarter": 2699,      # $26.99   —  $9.00/mo, 10% off
            "usd_half": 4799,         # $47.99   —  $8.00/mo, 20% off
            "usd_year": 8999},        # $89.99   —  $7.50/mo, 25% off
}
PAID_PLANS = ("pro",)

# The free view of the job board: only postings at least this old, and only
# this many of them. Being early is what wins an interview, so freshness is
# the thing Pro actually sells.
# The board is free. All of it, the day it is crawled.
#
# It used to be delayed a week and capped at fifty for free accounts,
# on the theory that being early is what Pro sells. It is not: the
# postings cost nothing to serve once crawled, and a job board that
# hides jobs has nothing to be judged on. What Pro sells is the AI that
# acts on a posting — apply kits, interview prep, the tutor — and a
# crawl run on demand rather than on the hour.
#
# Set either variable above zero to bring the old limits back.
FREE_JOB_DELAY_DAYS = int(env("FREE_JOB_DELAY_DAYS", "0") or 0)
FREE_JOB_CAP = int(env("FREE_JOB_CAP", "0") or 0)

# The billing periods on sale. `days` is the access granted on payment and runs
# a little past the term on purpose — a renewal that lands a day late must not
# lock someone out of the product they have paid for.
BILLING_PERIODS = {
    "month":   {"label": "Monthly",   "months": 1,  "interval": "month",
                "count": 1, "days": 32},
    "quarter": {"label": "3 months",  "months": 3,  "interval": "month",
                "count": 3, "days": 96},
    "half":    {"label": "6 months",  "months": 6,  "interval": "month",
                "count": 6, "days": 187},
    "year":    {"label": "12 months", "months": 12, "interval": "year",
                "count": 1, "days": 372},
}


def _period_from_span(started, expires):
    """Which period a subscriber is on, read back from the access they were
    granted. Used where the period was not recorded — old rows, and renewal
    invoices that carry no metadata."""
    if not started or not expires:
        return "month"
    days = (_aware(expires) - _aware(started)).days
    # Match the closest term rather than using thresholds, so adding a period
    # later does not silently reclassify existing subscribers.
    return min(BILLING_PERIODS,
               key=lambda k: abs(BILLING_PERIODS[k]["days"] - days))


#: Accounts a school issued. All three sign in with a code and no password:
#: a pupil off the register, a teacher with a subject code, an administrator
#: with the school's ten digits.
SCHOOL_KINDS = ("classcode", "schoolcode", "schoolstaff")


def plan_of(user) -> str:
    """The plan actually in force, expiry included."""
    if getattr(user, "is_admin", False):
        return "pro"
    # A school has paid for its people, so its people are not asked again.
    #
    # Everyone who arrives through a school code — the pupil, the teacher and
    # the office — gets the Pro board. The alternative was a lesson on a
    # classroom wall stopping to advertise a subscription to a room of
    # children, and a teacher being offered a personal upgrade for a tool the
    # school already bought. Neither is something to put in front of a class.
    #
    # Checked on `kind` rather than by looking up the school, because this is
    # called on nearly every request and a database query per call to answer
    # "which plan" would be paid for on every page.
    if (getattr(user, "kind", "") or "") in SCHOOL_KINDS:
        return "pro"
    p = (user.plan or "free").lower()
    if p not in PAID_PLANS:
        return "free"
    exp = user.plan_expires
    if exp is not None and exp.tzinfo is None:
        exp = exp.replace(tzinfo=dt.timezone.utc)
    if exp is not None and exp < now():
        return "free"
    return p


def _ai_used_today(db, user):
    """How many billable AI checks this user has run today (cache hits free)."""
    day = now().strftime("%Y%m%d")
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == f"aiq_{day}").first()
    try:
        return int(row.v) if row else 0
    except Exception:
        return 0


def _ai_used_total(db, user):
    """Lifetime billable AI checks — the free tier is a total, not a daily rate."""
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == "aiq_total").first()
    try:
        return int(row.v) if row else 0
    except Exception:
        return 0


def _ai_used_month(db, user):
    row = db.query(Note).filter(
        Note.user_id == user.id, Note.k == f"aiq_m{now().strftime('%Y%m')}").first()
    try:
        return int(row.v) if row else 0
    except Exception:
        return 0


def ai_quota(db, user):
    """What this user may still use, and on what plan. Cache hits are free and
    never counted, so re-running the same check costs nobody anything."""
    plan = plan_of(user)
    if plan == "pro":
        return {"plan": plan, "limit": None, "used": 0, "left": None}

    used = _ai_used_total(db, user)
    lim = PLANS["free"]["ai_total"]
    applied = db.query(Note).filter(Note.user_id == user.id,
                                    Note.k == "trial_apply_job").first()
    return {"plan": "free", "limit": lim, "used": used,
            "left": max(0, lim - used), "period": "total",
            # so the page can say "1 free upload left" up front, instead of
            # only finding out at the paywall
            "trial": {
                "resume_upload_left": max(
                    0, FREE_TRIAL["resume_upload"]
                    - _trial_used(db, user, "resume_upload")),
                "match_left": max(0, FREE_TRIAL["match"]
                                  - _trial_used(db, user, "match")),
                "extension_left": max(0, FREE_TRIAL["extension"]
                                      - _trial_used(db, user, "extension")),
                # Applying is paid outright now, so there is nothing left to
                # report. Kept in the payload so the page does not have to
                # branch on the key being absent.
                "apply_left": 0,
                "apply_job_id": int(applied.v) if applied
                and str(applied.v or "").isdigit() else None,
            }}


def require_paid(user, feature="This"):
    """Paid features. Browsing job listings stays free — that is what brings
    people here and what search engines index. Everything that acts on a
    resume is part of the paid product."""
    if getattr(user, "is_admin", False):
        return
    if plan_of(user) == "free":
        raise HTTPException(402, f"{feature} is part of a paid plan. "
                                 "Browsing every live job stays free.")


# A free account gets one go at this, once, ever — not per month. The point is
# to let someone see their own resume scored and go through one real
# application before deciding, without giving away the product. The free
# application is handled separately by apply_gate, which tracks a job rather
# than a count.
# Set to 0: the free tier no longer includes a trial of the paid tools. Free
# means the training courses and a limited, delayed view of the job board —
# resume matching, the tracker, apply kits and the extension are all paid.
# The mechanism is left in place because turning a trial back on is a matter
# of changing a number here, and it is covered by tests.
# sql_explain is the only entry with an allowance. Running queries on the SQL
# board is free forever because it costs us nothing — it is a SQLite file in
# memory, not a model call. Only the written explanation of your own mistake
# is paid, and three of those are enough to see whether it is worth paying for.
FREE_TRIAL = {"resume_upload": 0, "match": 0, "extension": 0,
              # Running queries on the SQL board is free forever because it
              # costs us nothing — it is a SQLite file in memory, not a model
              # call. Only the written explanation is metered.
              "sql_explain": 3,
              # The scanner is the way in: three goes is enough to find out
              # whether it reads your handwriting and whether the answer is
              # any good, and not enough to be the product.
              "scan": 3,
              # The course generator gets none. It is the deep explanation —
              # the largest single generation on the site and the thing worth
              # paying for — so it sits with the smart board on the paid side
              # rather than being given away once. It had one free go, which
              # also meant a free account could reach the 3D scenes a course
              # carries; those are Pro, and now they are Pro by every route.
              # One whole paper free. Solving sixty questions is many calls
              # and it is the thing a school is buying, so it cannot be
              # unlimited — but a teacher has to be able to run one real
              # paper through it before believing any of it, and a
              # description of what it does is not that.
              "solve_paper": 1,
              "course": 0}

# A whole chapter, not twelve pages of one.
#
# The cap was twelve because each page is a model call and a loop over
# forty of them, one after another, outlived any request deadline long
# before the bill became the problem. Reading them a few at a time fixes
# the deadline, so the cap can be what a chapter actually is. It is still a
# number rather than "unlimited": a request has to end, and a textbook
# uploaded whole is a bill nobody agreed to. Both are settable per
# deployment, so a school that photographs long chapters can raise it
# without a code change.
TEACH_MAX_PAGES = int(env("TEACH_MAX_PAGES", "40") or 40)
TEACH_READ_AT_ONCE = max(1, int(env("TEACH_READ_AT_ONCE", "5") or 5))


def _trial_used(db, user, key):
    row = db.query(Note).filter(Note.user_id == user.id,
                                Note.k == f"trial_{key}").first()
    try:
        return int(row.v) if row else 0
    except Exception:
        return 0


def require_paid_or_trial(db, user, key, feature, spent="free go"):
    """Like require_paid, but lets a free account through a fixed number of
    times. Does NOT consume the allowance — call _trial_consume after the
    work actually succeeded, so a failed upload doesn't burn someone's turn."""
    if getattr(user, "is_admin", False):
        return
    if plan_of(user) != "free":
        return
    limit = FREE_TRIAL.get(key, 0)
    if limit <= 0:
        # No allowance at all, so nothing was ever spent. Telling somebody
        # "you've used your one free course" when they never had one reads as
        # a billing bug, which is the worst thing a paywall can look like —
        # and it is what this said the moment the course allowance went to 0.
        return require_paid(user, feature)
    if _trial_used(db, user, key) >= limit:
        raise HTTPException(402, f"You've used your {spent}. {feature} is part "
                                 "of Pro — browsing every live job stays free.")


def _trial_consume(db, user, key):
    """Count one use against the free allowance. Paid accounts are untouched,
    so nothing has to be reset when someone subscribes."""
    if getattr(user, "is_admin", False) or plan_of(user) != "free":
        return
    k = f"trial_{key}"
    row = db.query(Note).filter(Note.user_id == user.id, Note.k == k).first()
    if row is None:
        row = Note(user_id=user.id, k=k, v="0")
        db.add(row)
    try:
        row.v = str(int(row.v or 0) + 1)
    except Exception:
        row.v = "1"
    db.commit()


def apply_gate(db, user, job_id):
    """Applying to a job. Paid — there is no longer a free application.

    Kept as its own function rather than folded into require_paid because the
    apply kit and marking a job applied are two calls for the same action, and
    a future allowance has to cover both or it strands people mid-application.
    """
    if getattr(user, "is_admin", False):
        return
    if plan_of(user) != "free":
        return
    raise HTTPException(402, "Applying to jobs is part of Pro. The training "
                             "courses stay free.")


def _ai_enforce_limit(db, user):
    if getattr(user, "is_admin", False):
        return
    # Deliberately no email-verification gate here either. Blocking a paying
    # customer behind a confirmation link is only safe if the mail reliably
    # arrives, and it does not yet.
    q = ai_quota(db, user)
    if q["limit"] is None:
        return
    if q["used"] >= q["limit"]:
        if q["plan"] == "free":
            raise HTTPException(
                402, f"You've used your {q['limit']} free AI requests. "
                     "Upgrade to keep generating apply kits and job matches — "
                     "browsing jobs and resume matching stay free.")
        raise HTTPException(
            402, f"You've used this month's {q['limit']} AI requests on Basic. "
                 "Upgrade to Pro for unlimited, or wait for next month.")
    # Also keep a per-day ceiling as an abuse brake, even on Pro.
    if _ai_used_today(db, user) >= AI_DAILY_LIMIT * 4:
        raise HTTPException(429, "That's a lot of requests in one day. "
                                 "Try again tomorrow.")


def papers_today(db, user):
    """How many whole papers this person has had read for them today."""
    row = db.query(Note).filter(
        Note.user_id == user.id,
        Note.k == f"paper_{now().strftime('%Y%m%d')}").first()
    try:
        return int(row.v) if row else 0
    except (TypeError, ValueError):
        return 0


def _papers_enforce(db, user):
    """The day's ceiling on whole papers, before any of the work starts."""
    if getattr(user, "is_admin", False):
        return
    used = papers_today(db, user)
    if used >= PAPERS_PER_DAY:
        raise HTTPException(
            429, f"That is {used} papers today, which is the daily limit. "
                 f"It resets tomorrow. Papers already read are still there "
                 f"and cost nothing to open again.")


def _papers_bump(db, user):
    """Count one paper against the day. Only ever called once it is read."""
    if getattr(user, "is_admin", False):
        return
    key = f"paper_{now().strftime('%Y%m%d')}"
    row = db.query(Note).filter(Note.user_id == user.id,
                                Note.k == key).first()
    if row:
        try:
            row.v = str(int(row.v) + 1)
        except (TypeError, ValueError):
            row.v = "1"
    else:
        db.add(Note(user_id=user.id, k=key, v="1"))


REVIEWS_PER_DAY = int(env("REVIEWS_PER_DAY", "60") or 60)


def _ai_may_spend(db, user) -> bool:
    """May this account have one more reading-back review today?

    The reviews are the reason this exists. They used to run INSIDE /api/ask
    and /api/board/lesson, so whatever gate the parent had covered them.
    Splitting them onto their own routes to get them off the answer's path
    took them outside those gates: two endpoints that call a model, take the
    payload from the caller, and had nothing between them and the bill.

    /api/ask is deliberately uncapped, and that is safe there for one reason
    only — the cache. The same question is paid for once and served forever,
    so an uncapped route is not an uncapped spend. **A review has no cache at
    all**: every call is a fresh model call whatever the body, which makes it
    exactly the call that needs a brake, however open its parent is.

    A budget of its own rather than the paid AI quota. That quota is a
    lifetime allowance on the free plan and reads zero, so charging reviews
    to it would have quietly switched the quality pass off for every free
    learner while leaving /api/ask free — a real change to the product,
    smuggled in as a fix. This caps abuse and nothing else: a review only
    fires for an answer that was not cached, so sixty in a day is far past
    anybody teaching or learning, and nowhere near a loop.

    Soft, never fatal. These run behind a lesson that is already on the
    screen, so being over budget means quietly not reviewing — not an error
    in front of a class.
    """
    if getattr(user, "is_admin", False):
        return True
    key = f"rvw_{now().strftime('%Y%m%d')}"
    try:
        row = db.query(Note).filter(Note.user_id == user.id,
                                    Note.k == key).first()
        used = int(row.v) if row and (row.v or "").isdigit() else 0
        if used >= REVIEWS_PER_DAY:
            return False
        if row:
            row.v = str(used + 1)
        else:
            db.add(Note(user_id=user.id, k=key, v="1"))
        db.commit()
    except Exception as e:                       # a broken meter must not
        db.rollback()                            # block a lesson from being
        print(f"Review budget check failed: {type(e).__name__}: {e}")
        return True                              # checked
    return True


def _ai_bump(db, user):
    """Count one billable AI call against the day, the month and the lifetime
    total. Three counters because the free tier is a lifetime allowance, Basic
    is monthly, and the daily one is only an abuse brake."""
    if getattr(user, "is_admin", False):
        return
    for key in (f"aiq_{now().strftime('%Y%m%d')}",
                f"aiq_m{now().strftime('%Y%m')}",
                "aiq_total"):
        row = db.query(Note).filter(Note.user_id == user.id, Note.k == key).first()
        if row:
            try:
                row.v = str(int(row.v) + 1)
            except Exception:
                row.v = "1"
        else:
            db.add(Note(user_id=user.id, k=key, v="1"))
    db.commit()


def _ai_cache_key(prefix, *parts, scope=None):
    """A cache key, inside one pool.

    `scope` is keyword-only and defaults to the private side of the fence.
    A caller that forgets it gets an institution-shaped key that simply
    misses the public pool — which costs a model call. Defaulting the other
    way would have cost a learner's resume text landing in a row another
    institution can read, and those two mistakes are not the same size."""
    import hashlib
    h = hashlib.sha256("||".join(p or "" for p in parts).encode("utf-8", "ignore")).hexdigest()
    return _cl.key(scope or _cl.PUBLIC, prefix, h)[:500]


def _ai_cache_get(db, qkey):
    """Return a cached AI result (and count the hit), or None."""
    row = db.query(AskCache).filter(AskCache.qkey == qkey).first()
    if not row:
        return None
    row.hits = (row.hits or 0) + 1
    db.commit()
    try:
        return json.loads(row.lesson)
    except Exception:
        return None


def _ai_cache_put(db, qkey, result):
    try:
        if db.query(AskCache).filter(AskCache.qkey == qkey).first():
            return
        db.add(AskCache(qkey=qkey[:500], subject="resume", level="",
                        question="", lesson=json.dumps(result), hits=0))
        db.commit()
    except Exception:
        db.rollback()


class AIProvidersFailed(Exception):
    """Every provider was tried and every one failed, with the reasons.

    Carrying them all is the point. One provider's message describes one
    provider, and reporting only the last one told people about a service
    they had not configured while staying silent about the one they had.
    """

    def __init__(self, fails):
        self.fails = fails or []
        super().__init__("; ".join(f"{p}: {e}" for p, e in self.fails)[:400])


def _transient(e):
    """Is this the provider being busy, rather than anything being wrong?

    Capacity, not configuration. A model that is overloaded this second
    answers perfectly well two seconds later, and that is the only class of
    failure where asking the same provider again is the right move — a bad
    key, a wrong model name or a refusal give the same answer however many
    times they are asked.
    """
    m = (type(e).__name__ + " " + str(e)).lower()
    if "insufficient_quota" in m or "credit balance" in m:
        return False
    return ("overload" in m or "unavailable" in m or "http 503" in m
            or "http 502" in m or "http 500" in m)


def _one_provider_reason(prov, e):
    """What went wrong at one provider, in that provider's own dialect."""
    # The class name as well as the message. Every httpx timeout stringifies
    # to "" — so reading only str(e) found nothing to match and fell through
    # to "could not be reached", which describes a network fault at the
    # provider rather than a deadline set on this side.
    m = (type(e).__name__ + " " + str(e)).lower()
    # Google first, because its rate-limit message is "You exceeded your
    # current quota, please check your plan and billing details" — which
    # contains both "quota" and "billing" while meaning neither. Gemini has no
    # out-of-credit state that presents this way; enabling billing there buys
    # a higher limit, it does not unblock a different error. So for Gemini,
    # 429 is always a rate limit.
    if prov == "gemini" and ("quota" in m or "429" in m
                             or "rate limit" in m
                             or "resource_exhausted" in m):
        return ("rate", "Gemini is over its request limit for now — the free "
                        "tier allows only a few calls a minute and a capped "
                        "number per day, and it resets")
    # Only these two are unambiguous. "billing" on its own is not.
    if "insufficient_quota" in m or "credit balance" in m:
        return ("credit", f"{prov} has no credit left — this will not clear "
                          f"by waiting")
    if "no longer available" in m:
        return ("model", f"the {prov} model in the settings has been retired "
                         f"by the provider — it is listed but it no longer "
                         f"answers, and the site needs a newer one named")
    if (("not found" in m and "model" in m) or "is not supported" in m
            or "http 404" in m):
        return ("model", f"{prov} does not have the model it was asked for")
    if "api key" in m or "unauthor" in m or "401" in m or "403" in m:
        return ("key", f"the {prov} key was refused")
    if "quota" in m or "429" in m or "rate limit" in m or "resource_exhausted" in m:
        if prov == "gemini":
            return ("rate", "Gemini is over its request limit for now — the "
                            "free tier allows only a few per minute and a "
                            "capped number per day, and it resets")
        return ("rate", f"{prov} is rate-limiting requests for now")
    # The model answered, produced no text, and said why. That reason is
    # worth more than everything else in this function put together, and it
    # was landing in "could not be reached" — which describes a network
    # fault and sends whoever reads it to look in the wrong place entirely.
    if "stopped:" in m:
        tail = str(e).split("stopped:")[-1].strip().strip(".;")[:60]
        if "max_tokens" in tail.lower():
            return ("long", f"{prov} ran out of room before it finished "
                            f"writing — this is a length fault on our side, "
                            f"not a fault at the provider")
        if "safety" in tail.lower() or "block" in tail.lower():
            return ("refused", f"{prov} declined to answer this one")
        if "recitation" in tail.lower():
            return ("refused", f"{prov} stopped itself, because the answer "
                               f"was reproducing text it recognised")
        return ("empty", f"{prov} stopped early: {tail}")
    if "timeout" in m or "timed out" in m or "readtimeout" in m:
        return ("slow", f"{prov} did not answer within the time allowed — a "
                        f"long lesson can genuinely take a while")
    # Google's own capacity, which is neither our fault nor the key's. The
    # popular models are the ones that run out of it: switching from
    # flash-lite to 2.5-flash traded a quiet model for a busy one, and a
    # 503 UNAVAILABLE matched nothing here, so it was reported as a network
    # fault — sending whoever read it to check their internet.
    if ("overload" in m or "unavailable" in m
            or "http 503" in m or "http 500" in m or "http 502" in m):
        return ("busy", f"{prov} is busy right now — the model is in demand, "
                        f"not broken, and this clears on its own")
    if "connecterror" in m or "connect" in m and "error" in m:
        return ("net", f"{prov} could not be reached from the server")
    if "no text" in m:
        return ("empty", f"{prov} returned nothing usable")
    return ("other", f"{prov} could not be reached")


def _ai_error_message(e):
    """Turn a raw upstream error into words that are true for the reader.

    This used to answer every rate limit with "the free AI limit has been
    reached". For somebody on Pro that is simply false — it is the model
    provider that is out, not their allowance — and it reads as a billing
    fault on their own account, which is the worst thing to be wrong about.

    Two upstream conditions arrive looking similar and need opposite advice.
    Being told to wait when the credit has run out means waiting forever.
    """
    if isinstance(e, AIProvidersFailed) and e.fails:
        reasons = [_one_provider_reason(p, x) for p, x in e.fails]
        body = ". ".join(r[1][0].upper() + r[1][1:] for r in reasons) + "."
        kinds = {r[0] for r in reasons}
        if "credit" in kinds or "key" in kinds or "model" in kinds:
            body += (" Nothing is wrong with your account — this is the "
                     "site's own AI configuration.")
        elif kinds <= {"rate", "slow", "empty", "other", "net"}:
            body += " Nothing has been used up on your account; try again "\
                    "shortly."
        return body

    s = str(e).lower()
    # No bare "402": any number containing it — a token count, a request id —
    # would match and tell somebody their credit had run out when it had not.
    # And no bare "exceeded your current quota": that is OpenAI's phrase for
    # billing and Google's for an ordinary rate limit, so on its own it means
    # nothing.
    dead = ("insufficient_quota", "credit balance", "payment required")
    if any(k in s for k in dead):
        return ("The AI provider's credit has run out, so this will not fix "
                "itself by waiting. Nothing is wrong with your account. If "
                "this is your site, top up the provider or set a second API "
                "key — Craxle falls back automatically to whichever one still "
                "works.")
    if ("not found" in s and "model" in s) or "is not supported" in s             or "unknown model" in s:
        return ("The AI model name in the settings does not exist for this "
                "API key. Nothing is wrong with your account. If this is your "
                "site, check /api/ai/models to see what the key can actually "
                "use and set GEMINI_MODEL or OPENAI_MODEL to one of them.")
    if "429" in s or "rate limit" in s or "tokens per minute" in s:
        return ("The AI provider is rate-limiting requests at the moment. "
                "This clears on its own, usually within a minute. Nothing has "
                "been used up on your account.")
    if "tokens per day" in s or "quota" in s:
        return ("The AI provider's daily allowance is spent and resets "
                "tomorrow. Nothing has been used up on your account.")
    return "The AI could not respond just now. Please try again in a moment."


def _why(e, user=None):
    """The technical reason, for the one person who can act on it.

    Every message above is written for a student, and it has to be: nobody
    revising for boards needs a stack trace. But the price of translating
    every fault into the same sentence is that the person running the site
    gets the same sentence too — "the AI could not respond" was all a whole
    paper of physics coming back unsolved ever said, and a screenshot of it
    carries no more information than the words do.

    So an admin, and only an admin, gets the raw class and message on the
    end. A timeout, a refusal, a truncated reply and an unparseable one look
    identical until this line exists.
    """
    try:
        if not (user is not None and getattr(user, "is_admin", False)):
            return ""
    except Exception:
        return ""
    return f" [admin: {type(e).__name__}: {e}]"[:400]


def _providers_in_order():
    """Providers to try, in order: the configured one first, then any others
    that also have a key — so if one is rate-limited we fall back to the next."""
    order = [AI_PROVIDER] + [p for p in _PREFERRED if p != AI_PROVIDER]
    return [p for p in order if _KEYS.get(p)]


GEMINI_SAFE_MODEL = "gemini-flash-lite-latest"

# Only these two families never had thinking. Everything else — 2.5, 3, and
# every rolling alias, now and later — gets it switched off.
#
# This was a positive match on version digits, which is exactly wrong for a
# setting that is usually an alias: "gemini-flash-lite-latest" has no digits
# after "gemini-", so it fell through, thinking stayed on, and it quietly ate
# the output budget of the largest prompt in the product.
# Models that will not take thinkingConfig.
#
# The old ones because they predate it, and the "-latest" aliases because the
# probe matrix settled it directly: gemini-flash-lite-latest returns 400
# INVALID_ARGUMENT with thinkingConfig and 200 without it, every time. Google
# never says which argument is invalid, so that was worth measuring rather
# than reasoning about.
#
# The retry below still catches anything this misses. Listing the aliases here
# only saves a wasted 400 on the first call after each restart — small, but it
# was the difference between the configured provider working and the whole
# site quietly running on the fallback.
# Both branches are anchored: this is used with .match(), so an unanchored
# "-latest$" would never fire — it has to match from the start of the name.
#
# Narrowed to the alias that was actually measured. "every -latest" swept in
# gemini-flash-latest, which is the default now, and a thinking budget is
# most of why a solved paper reasons before it answers — throwing that away
# on an untested guess costs more than the one wasted 400 the retry below
# already handles.
_NO_THINKING = _re.compile(r"^gemini-(?:1\.|2\.0)|^gemini-flash-lite-latest$")


def _override_model(best=False):
    """The Gemini model a call is actually going to."""
    return (GEMINI_MODEL_BEST if best else GEMINI_MODEL) or ""


def _gen_config(model, tokens, temperature, json_mode=False, no_think=False,
                think=0):
    """The generationConfig for one Gemini call.

    `think` is a thinking budget in tokens, and it is 0 everywhere except
    where somebody has decided the reasoning is worth buying. 2.5 Flash
    reasons before it answers when given a budget, and that is most of why
    it is better than Lite at a step-by-step paper — but thinking tokens are
    billed, and turning it on for every lesson and every scan on a school's
    account is not a decision to make by default.
    """
    gen = {"maxOutputTokens": tokens, "temperature": temperature}
    if json_mode:
        gen["responseMimeType"] = "application/json"
    want = max(0, int(think or 0))
    m = model or ""
    if no_think or m in _thinking_off or _NO_THINKING.match(m):
        return gen
    if want > 0:
        gen["thinkingConfig"] = {"thinkingBudget": want}
    elif not _NO_ZERO_THINK.search(m):
        # Budget zero, which is what makes the everyday model cheap: without
        # it a Flash model thinks by default and every caption is billed for
        # reasoning nobody asked for.
        gen["thinkingConfig"] = {"thinkingBudget": 0}
    # ...and for a Pro model, nothing at all. See below.
    return gen


# A Pro model cannot be told not to think, and telling it to is a 400 on
# EVERY call.
#
# This is why setting both variables to gemini-pro-latest produced a site
# that answered nothing. Twenty-one of the twenty-six call sites here ask
# for a budget of zero — correctly, because that is what keeps a caption
# from being billed as reasoning — and zero is not a value a Pro model
# accepts. Every one of those requests came back 400 INVALID_ARGUMENT, and
# Google does not say which argument.
#
# The recovery made it worse rather than better: the first 400 set a global
# flag that dropped thinkingConfig from every subsequent request, for the
# life of the process, for every model. So the site came back to life
# answering with no reasoning at all — including on the question papers that
# had just been given a budget of 8192 to reason with. A switch meant to
# save one provider was quietly cancelling the thing being paid for.
#
# So: no budget is sent to a Pro model when the answer wanted is "do not
# think". It thinks anyway, which is the whole reason somebody chose Pro.
_NO_ZERO_THINK = _re.compile(r"pro", _re.I)

# And when a model does refuse the parameter, it is remembered per MODEL
# rather than for the whole provider — one model's refusal is not a reason
# to stop paying for reasoning on a different one.
_thinking_off = set()


def _rejects_thinking(e):
    """Did the model refuse the thinking parameter?

    Google does not say which argument was invalid — the whole message is
    "Request contains an invalid argument." So any 400 is treated as this,
    because thinkingConfig is the only optional field in the payload and
    losing the provider over it is far worse than one wasted retry.
    """
    m = str(e).lower()
    if "thinking" in m and ("not supported" in m or "invalid" in m
                            or "unknown" in m or "unexpected" in m):
        return True
    return "invalid_argument" in m or "invalid argument" in m or "400" in m


def _is_missing_model(e):
    """Did this fail because the model id is wrong, rather than transiently?

    "Wrong" now includes "was right until Google retired it". A model that
    has been withdrawn answers 404 with a sentence about being "no longer
    available to new users" and a recommendation to migrate — which contains
    neither "not found" nor "unknown model", so none of the phrases below
    matched it and the automatic fall back to the safe model never fired.
    The site had a working key, a working fallback, and reported that Gemini
    could not be reached, for a whole afternoon.

    So: any 404 from a model endpoint is a model that is not there. There is
    nothing else a 404 on that URL can mean.
    """
    m = str(e).lower()
    return (("not found" in m and "model" in m)
            or "is not supported" in m or "unknown model" in m
            or "does not exist" in m
            or "no longer available" in m
            or "http 404" in m or "'code': 404" in m)


_gemini_fallback_warned = False


def _gemini_model(best=False):
    """The model to ask for, and the one to fall back to if it is not there."""
    want = GEMINI_MODEL_BEST if best else GEMINI_MODEL
    return want, (GEMINI_SAFE_MODEL if want != GEMINI_SAFE_MODEL else None)


def _gemini_ladder(best=False):
    """The models to try, strongest first, when the strongest is busy.

    A Pro model is in demand — that is what makes it the good one — and
    Google answers 503 when it has no capacity this second. Falling through
    to the NEXT PROVIDER is the wrong move there: with one key configured
    there is no next provider, so a busy model means a blank screen, and
    "Gemini is busy right now" is a true sentence that solves nothing for a
    teacher standing in front of a class.

    An answer from the second-best model beats no answer, and it is not a
    quiet substitution: the paper is worked twice, so a weaker answer that
    is wrong is what the checking pass exists to catch.

    Order matters. Falling from Pro straight to flash-LITE would drop two
    steps at once, and lite is the model that produced a solution
    contradicting its own working. Full Flash sits between them.
    """
    seen, out = set(), []
    for m in ((GEMINI_MODEL_BEST if best else GEMINI_MODEL),
              GEMINI_MODEL, GEMINI_SAFE_MODEL):
        if m and m not in seen:
            seen.add(m)
            out.append(m)
    return out


def _gemini_said(data):
    """The text Gemini returned, or why there is none.

    An empty reply is not a reason, and this is where the reason was being
    thrown away. A 200 with no text has a cause and Google names it in the
    candidate: MAX_TOKENS when the answer ran out of room — thinking tokens
    are spent from the same allowance as the writing — SAFETY when it
    refused, RECITATION when it stopped itself. Without this, a whole paper
    of physics coming back unsolved reported only "the AI could not
    respond", which is true of every fault there has ever been and points at
    none of them.
    """
    out = "".join(p.get("text", "") for c in (data.get("candidates") or [])
                  for p in (c.get("content") or {}).get("parts", [])).strip()
    if out:
        return out
    cand = (data.get("candidates") or [{}])[0]
    why = (cand.get("finishReason")
           or (data.get("promptFeedback") or {}).get("blockReason")
           or "empty reply")
    raise RuntimeError(f"gemini stopped: {why}")


async def _provider_generate(client, provider, prompt, max_tokens, json_mode=False,
                             best=False, _override=None, _no_think=False,
                             _think=0):
    """One raw generation call to a single provider. Raises on HTTP error."""
    if provider == "gemini":
        model = _override or (GEMINI_MODEL_BEST if best else GEMINI_MODEL)
        # 0.15, not 0.4. A lesson is a reference, not creative writing: at
        # 0.4 the same question produces a different derivation each time and
        # one of those variations is the one that invents a step. Lower is
        # duller, and gives more nearly the same answer twice.
        gen = _gen_config(model, max_tokens, 0.15, json_mode, _no_think,
                          think=_think)
        r = await client.post(
            f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",
            headers={"x-goog-api-key": GEMINI_API_KEY, "content-type": "application/json"},
            json={"contents": [{"parts": [{"text": prompt}]}], "generationConfig": gen})
        _upstream_ok(r, "gemini")
        return _gemini_said(r.json())
    if provider == "groq":
        # 0.15, not 0.4. A lesson is not creative writing: at 0.4 the
        # same question gives a different derivation each time, and one
        # of those variations is the one that invents a step. Lower is
        # duller and more nearly the same answer twice, which is what a
        # reference is for.
        body = {"model": GROQ_MODEL, "max_tokens": max_tokens, "temperature": 0.15,
                "messages": [{"role": "user", "content": prompt}]}
        if json_mode:
            body["response_format"] = {"type": "json_object"}
        r = await client.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={"Authorization": f"Bearer {GROQ_API_KEY}", "content-type": "application/json"},
            json=body)
        _upstream_ok(r, "groq")
        return r.json().get("choices", [{}])[0].get("message", {}).get("content", "").strip()
    if provider == "openai":
        # Same wire format as Groq — both speak the OpenAI chat API — but kept
        # as its own branch because the model names, the key and the failure
        # messages are all different, and merging them would mean a Groq
        # rate-limit error reported as an OpenAI one.
        body = {"model": OPENAI_MODEL, "max_tokens": max_tokens,
                "temperature": 0.15,
                "messages": [{"role": "user", "content": prompt}]}
        if json_mode:
            body["response_format"] = {"type": "json_object"}
        r = await client.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}",
                     "content-type": "application/json"},
            json=body)
        _upstream_ok(r, "openai")
        return r.json().get("choices", [{}])[0].get("message", {}).get("content", "").strip()
    # claude / anthropic
    r = await client.post(
        "https://api.anthropic.com/v1/messages",
        headers={"x-api-key": ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01",
                 "content-type": "application/json"},
        json={"model": ANTHROPIC_MODEL, "max_tokens": max_tokens,
              "messages": [{"role": "user", "content": prompt}]})
    _upstream_ok(r, "claude")
    return "".join(b.get("text", "") for b in r.json().get("content", [])
                   if b.get("type") == "text").strip()


async def _provider_vision(client, provider, prompt, raw, mime, max_tokens,
                           _override=None, best=False, _think=0):
    """One generation call that also carries an image.

    Kept apart from _provider_generate because the three wire formats disagree
    about images in a way they do not disagree about text, and folding them
    together would mean a branch per provider inside every other branch.

    Groq is absent on purpose: the configured Groq model is text-only, and a
    fallback that silently drops the image would answer a question nobody
    asked. Better to skip it and try the next provider that can actually see.
    """
    b64 = base64.b64encode(raw).decode()
    if provider == "gemini":
        # A photograph of a problem is a problem to be solved, and this was
        # the one path where that could not be paid for: no model choice and
        # no thinking budget existed here at all, so every scan went to the
        # cheap model with reasoning explicitly switched OFF. A hard JEE
        # series question does not fall to that, and it did not.
        model = _override or (GEMINI_MODEL_BEST if best else GEMINI_MODEL)
        gen = _gen_config(model, max_tokens, 0.15, True, think=_think)
        r = await client.post(
            f"https://generativelanguage.googleapis.com/v1beta/models/"
            f"{model}:generateContent",
            headers={"x-goog-api-key": GEMINI_API_KEY,
                     "content-type": "application/json"},
            json={"contents": [{"parts": [
                {"text": prompt},
                {"inline_data": {"mime_type": mime, "data": b64}}]}],
                "generationConfig": gen})
        _upstream_ok(r, "gemini")
        return _gemini_said(r.json())
    if provider == "openai":
        r = await client.post(
            "https://api.openai.com/v1/chat/completions",
            headers={"Authorization": f"Bearer {OPENAI_API_KEY}",
                     "content-type": "application/json"},
            json={"model": OPENAI_MODEL, "max_tokens": max_tokens,
                  "temperature": 0.15,
                  "response_format": {"type": "json_object"},
                  "messages": [{"role": "user", "content": [
                      {"type": "text", "text": prompt},
                      {"type": "image_url", "image_url": {
                          "url": f"data:{mime};base64,{b64}"}}]}]})
        _upstream_ok(r, "openai")
        return r.json().get("choices", [{}])[0].get(
            "message", {}).get("content", "").strip()
    if provider == "claude":
        r = await client.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": ANTHROPIC_API_KEY,
                     "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={"model": ANTHROPIC_MODEL, "max_tokens": max_tokens,
                  "messages": [{"role": "user", "content": [
                      {"type": "image", "source": {
                          "type": "base64", "media_type": mime, "data": b64}},
                      {"type": "text", "text": prompt}]}]})
        _upstream_ok(r, "claude")
        return "".join(b.get("text", "") for b in r.json().get("content", [])
                       if b.get("type") == "text").strip()
    raise RuntimeError(f"{provider} cannot read images")


VISION_PROVIDERS = ("gemini", "openai", "claude")
# Gemini is the only one of the three that reads a PDF as a document rather
# than as an image it cannot decode. Its payload already carries whatever
# mime type it is handed, so a PDF needs no new client — only the sense not
# to offer one to a provider that will fail on it.
PDF_PROVIDERS = ("gemini",)
# Gemini takes a document inline up to about 20MB; past that it wants the
# files API, which is a second round trip and a handle to clean up.
PDF_INLINE_MAX = 18 * 1024 * 1024


async def _ai_pdf(prompt: str, raw: bytes, max_tokens: int = 2200) -> str:
    """Read a PDF as a document, without rasterising it first.

    A scanned paper used to make this round trip: the server refused it,
    the browser loaded pdf.js, rendered every page to a PNG, and posted them
    back — a megabyte a page over a school's connection, and pdf.js loaded
    on a phone to do it. Gemini reads the PDF itself, keeping the page
    order and the layout that rasterising throws away.

    Never raises for a reason the caller cannot act on: if this is not
    available, or the file is too big to send inline, it returns "" and the
    caller falls back to asking the browser for pages, which still works.
    """
    import httpx
    if not raw or len(raw) > PDF_INLINE_MAX:
        return ""
    order = [p for p in _providers_in_order() if p in PDF_PROVIDERS]
    if not order:
        return ""
    async with httpx.AsyncClient(timeout=90.0) as client:
        try:
            return await _provider_vision(client, order[0], prompt, raw,
                                          "application/pdf", max_tokens)
        except Exception as e:
            print(f"PDF read failed, falling back to pages: "
                  f"{type(e).__name__}: {e}")
            return ""


async def _ai_vision(prompt: str, raw: bytes, mime: str,
                     max_tokens: int = 2000, best: bool = False,
                     think: int = 0) -> str:
    """Read an image, trying each provider that can, in the usual order.

    `best` and `think` are for the calls where the picture contains a
    PROBLEM rather than a page to be copied out. Reading a scanned paper
    needs neither and should not pay for either; solving what is in the
    photograph needs both, and until now there was no way to ask for them.
    """
    import httpx
    order = [p for p in _providers_in_order() if p in VISION_PROVIDERS]
    if not order:
        raise RuntimeError("No AI provider that can read images is configured")
    last, fails = None, []
    import time as _t
    # A photo has to be uploaded before anything starts reading it, so the
    # floor is higher here than for text. The client allows 120 seconds for
    # an upload, so the chain stays under that.
    #
    # And thinking is counted, because it is spent BEFORE a single word of
    # the answer is written. The scanner was given a reasoning budget and
    # not the time to use it: 57 seconds, against a Pro model working
    # through a JEE question. The request was abandoned server-side every
    # time, the chain moved on to a provider with no credit, and the screen
    # showed nothing at all — which is exactly what a photographed problem
    # did after it was finally allowed to think.
    per_try = max(40.0, min(95.0, 30.0 + max_tokens / 90.0
                            + max(0, int(think or 0)) / 110.0))
    _deadline = _t.monotonic() + 105
    async with httpx.AsyncClient(timeout=per_try) as client:
        for prov in order:
            if _t.monotonic() > _deadline:
                print(f"AI vision: out of time before trying {prov}")
                break
            try:
                try:
                    txt = await _provider_vision(client, prov, prompt, raw,
                                                 mime, max_tokens, best=best,
                                                 _think=think)
                except Exception as inner:
                    _vm = _override_model(best)
                    if prov == "gemini" and _rejects_thinking(inner) \
                            and _vm not in _thinking_off:
                        _thinking_off.add(_vm)
                        print(f"AI: {_vm} refused thinkingBudget on a vision "
                              f"call; sending without it to that model.")
                        txt = await _provider_vision(client, prov, prompt, raw,
                                                     mime, max_tokens,
                                                     best=best)
                        if txt:
                            return txt
                    # A busy model, or a missing one: down the ladder
                    # rather than out the door. A photographed problem that
                    # comes back blank because Pro had no capacity this
                    # second is a teacher standing in front of a class with
                    # nothing on the screen.
                    if prov == "gemini" and (_is_missing_model(inner)
                                             or _transient(inner)):
                        txt = ""
                        for alt in _gemini_ladder(best)[1:]:
                            if _t.monotonic() + 3 > _deadline:
                                break
                            try:
                                print(f"AI vision: {alt} instead, the first "
                                      f"choice is unavailable")
                                txt = await _provider_vision(
                                    client, prov, prompt, raw, mime,
                                    max_tokens, _override=alt, _think=think)
                                if txt:
                                    break
                            except Exception as down:
                                inner = down
                        if not txt:
                            raise inner
                    else:
                        raise
                if txt:
                    return txt
                last = RuntimeError(f"{prov} returned no text")
                fails.append((prov, last))
            except Exception as e:
                print(f"Vision via {prov} failed: {type(e).__name__}: {e}")
                last = e
                fails.append((prov, e))
    if fails:
        raise AIProvidersFailed(fails)
    raise last or RuntimeError("No provider could read that image")


async def _ai_text(prompt: str, max_tokens: int = 1500, json_mode: bool = False,
                   best: bool = False, think: int = 0) -> str:
    """Generate text, trying each available provider in turn. If one is rate-
    limited or errors, automatically fall back to the next configured provider."""
    import httpx
    providers = _providers_in_order()
    if not providers:
        raise RuntimeError("No AI provider key is configured")
    last, fails = None, []
    retried = set()          # one extra attempt per provider, and no more
    # Sized to the request rather than flat. A flat 25 seconds is generous for
    # a 1,500-token reply and nowhere near enough for a board lesson, which
    # sends a 15,000-character prompt and wants 8,000 tokens of JSON back —
    # so the board timed out on every single attempt while plain Ask, asking
    # for a fraction as much, looked perfectly healthy.
    #
    # Still bounded, and still under the browser's own 75-second deadline:
    # the client must be the one that gives up last, or it reports a hang for
    # a request the server already abandoned.
    import time as _t
    # Thinking is part of the wait, and it is spent before any of the answer
    # exists. A paper batch asks for 8192 tokens of reasoning on top of the
    # writing, and 55 seconds was decided when nothing here reasoned at all.
    #
    # The long window is only for the calls that are BUYING reasoning, and
    # that is not a detail: an ordinary call's client gives up at 75 seconds,
    # so a server that keeps working for 100 is reporting a failure on a
    # request it would have finished. The one caller that waits longer waits
    # 130, and it is the only one that spends a thinking budget.
    _think = max(0, int(think or 0))
    _cap, _wait = (100.0, 110) if _think else (60.0, 70)
    per_try = max(25.0, min(_cap, 18.0 + max_tokens / 110.0 + _think / 110.0))
    _deadline = _t.monotonic() + _wait
    async with httpx.AsyncClient(timeout=per_try) as client:
        for prov in providers:
            if _t.monotonic() > _deadline:
                print(f"AI: out of time before trying {prov}")
                break
            try:
                try:
                    txt = await _provider_generate(client, prov, prompt,
                                                   max_tokens, json_mode, best,
                                                   _think=think)
                except Exception as inner:
                    # A model that does not take thinkingConfig at all: send
                    # the same call again without it rather than losing the
                    # provider over one optional field.
                    if prov == "gemini" and _rejects_thinking(inner):
                        txt = await _provider_generate(
                            client, prov, prompt, max_tokens, json_mode, best,
                            _no_think=True)
                        if txt:
                            _tm = _override_model(best)
                            if _tm not in _thinking_off:
                                _thinking_off.add(_tm)
                                print(f"AI: {_tm} will not take "
                                      f"thinkingBudget; sending without it "
                                      f"to that model.")
                            return txt
                        raise
                    want, safe = _gemini_model(best)
                    if not (prov == "gemini" and safe
                            and _is_missing_model(inner)):
                        raise
                    global _gemini_fallback_warned
                    if not _gemini_fallback_warned:
                        _gemini_fallback_warned = True
                        print(f"AI CONFIG: GEMINI_MODEL is set to '{want}', "
                              f"which this key cannot use. Falling back to "
                              f"'{safe}' for every request. Fix the variable "
                              f"or check /api/ai/models.")
                    txt = await _provider_generate(client, prov, prompt,
                                                   max_tokens, json_mode, best,
                                                   _override=safe,
                                                   _think=think)
                if txt:
                    return txt
                last = RuntimeError(f"{prov} returned no text")
                fails.append((prov, last))
            except Exception as e:
                # One more go at the SAME provider when it was merely busy.
                #
                # A 503 from Google means the model is in demand this second,
                # and the popular models are the ones that run out of
                # capacity: moving from flash-lite to 2.5-flash traded a
                # quiet model for a sought-after one. Falling straight
                # through to the next provider is the wrong response to
                # that — with one key configured there is no next provider,
                # so a two-second wait was the difference between an answer
                # and "Gemini could not be reached".
                if (_transient(e) and prov not in retried
                        and _t.monotonic() + 4 < _deadline):
                    retried.add(prov)
                    print(f"AI provider '{prov}' was busy; one more try")
                    try:
                        await asyncio.sleep(1.5)
                        txt = await _provider_generate(
                            client, prov, prompt, max_tokens, json_mode, best,
                            _think=think)
                        if txt:
                            return txt
                    except Exception as again:
                        e = again
                    # Still busy: down the ladder rather than out the door.
                    # With one key configured there is no next provider, so
                    # a busy model otherwise means a blank screen.
                    if prov == "gemini" and _transient(e):
                        for alt in _gemini_ladder(best)[1:]:
                            if _t.monotonic() + 3 > _deadline:
                                break
                            try:
                                print(f"AI: {alt} instead, the first choice "
                                      f"is out of capacity")
                                txt = await _provider_generate(
                                    client, prov, prompt, max_tokens,
                                    json_mode, best, _override=alt,
                                    _think=think)
                                if txt:
                                    return txt
                            except Exception as down:
                                e = down
                last = e
                fails.append((prov, e))
                print(f"AI provider '{prov}' failed, trying next: {type(e).__name__}: {e}")
                continue
    if fails:
        raise AIProvidersFailed(fails)
    raise last if last else RuntimeError("AI generation failed")


async def _call_model(question: str, subject: str, level: str) -> dict:
    """Build an Ask-Axle lesson, with automatic provider fallback."""
    prompt = _ask_prompt(question, subject, level)
    text = await _ai_text(prompt, 1500, json_mode=True)
    if not text:
        raise RuntimeError("AI returned no text")
    return _parse_lesson(text, question)


def _spoken(text: str) -> str:
    """A reply fit to be read aloud.

    Belt and braces: the prompt says no markdown, but a stray asterisk or
    hash read out as "asterisk" is the kind of thing that makes a voice
    sound broken, and it only takes one.
    """
    text = _re.sub(r"[*#`_]+", "", text or "")
    return _re.sub(r"\s{2,}", " ", text).strip()[:1200]


def _record_skills(db, user, skills):
    """Store what the learner just finished, and hand it back to the page.

    Idempotent on (user, label): a learner who works through the same idea
    twice has one skill, not two, and the count of how often it came up is
    worth more than a second row saying the same thing.

    Never raises. A skill that fails to store is a missing line on a resume;
    a skill that fails to store and takes the answer down with it is a tutor
    that stopped talking. The commit is guarded for exactly that reason.
    """
    out = []
    for sk in skills or []:
        label, tokens = sk["label"], ",".join(sk["tokens"])
        row = (db.query(SkillUnlock)
                 .filter(SkillUnlock.user_id == user.id,
                         SkillUnlock.label == label).first())
        if row:
            row.times = (row.times or 0) + 1
            row.last_at = now()
            # A later lesson may know words the earlier one did not.
            if tokens and not row.tokens:
                row.tokens = tokens
        else:
            db.add(SkillUnlock(user_id=user.id, label=label, tokens=tokens,
                               times=1))
        out.append({"skill": label, "tokens": list(sk["tokens"])})
    if out:
        try:
            db.commit()
        except Exception as e:
            db.rollback()
            print(f"Skill unlock not stored: {type(e).__name__}: {e}")
    return out


class DobIn(BaseModel):
    dob: str = Field(default="", max_length=10)   # YYYY-MM-DD, or "" to clear


@app.post("/api/craxlearn/dob")
def craxlearn_set_dob(body: DobIn, user: User = Depends(current_user),
                      db: Session = Depends(get_db)):
    """Record a date of birth, which is what opens the job side.

    Not verification, and not described as it. This is a stated date, the
    same as every other site asks for, and it exists so that the default is
    closed rather than open — a learner who has not said is not shown to
    employers. A school that needs real proof of age has processes for that
    which no web form replaces.
    """
    raw = (body.dob or "").strip()
    if not raw:
        user.dob = None
        db.commit()
        return {"ok": True, "dob": "", "adult": False}
    try:
        got = dt.date.fromisoformat(raw)
    except ValueError:
        raise HTTPException(400, "Give the date as YYYY-MM-DD")
    today = dt.date.today()
    if got > today:
        raise HTTPException(400, "That date is in the future")
    if _cl.age_on(got, today) > 120:
        raise HTTPException(400, "Check that date — it is over 120 years ago")
    user.dob = got
    db.commit()
    return {"ok": True, "dob": got.isoformat(),
            "age": _cl.age_on(got, today), "adult": _cl.adult(got, today)}


@app.get("/api/craxlearn/me")
def craxlearn_me(user: User = Depends(current_user),
                 db: Session = Depends(get_db)):
    """Everything the institution app needs to paint itself once.

    A separate boot call from /api/auth/me on purpose. That one answers "who
    is signed in" for the whole of Craxle; this answers "what does this
    institution's app show", which is a different question with a different
    audience — and merging them would put a school's product entitlement
    into the payload every job seeker fetches on every page load.
    """
    scope = _scope_of(db, user)
    sid = _cl.school_id_of(scope)
    sc = db.get(School, sid) if sid else None
    ta = (db.query(TeacherAccess)
            .filter(TeacherAccess.user_id == user.id).first())
    gate = _learning_only(db, user)

    # Three ways to be attached to a classroom, and all three have to be here.
    # A learner is IN one. A head teacher CREATED some. A subject teacher
    # CLAIMED a subject in some — and that third one was missing, so a subject
    # teacher signed in and saw no classes at all, which meant no register, no
    # way to set work, and no way to file a lesson she had just taught.
    seen, classes = set(), []
    def _add(rows):
        for k in rows:
            if k.id not in seen:
                seen.add(k.id)
                classes.append(k)

    _add(db.query(Klass)
           .join(ClassMember, ClassMember.class_id == Klass.id)
           .filter(ClassMember.user_id == user.id).all())
    if ta:
        _add(db.query(Klass).filter(Klass.teacher_id == user.id).all())
        slot_ids = {sl.class_id for sl in db.query(SubjectSlot)
                    .filter(SubjectSlot.teacher_id == user.id).all()}
        if slot_ids:
            _add(db.query(Klass).filter(Klass.id.in_(list(slot_ids))).all())

    # What each class is actually made of: its subjects, and who teaches each.
    # A student has one class and several subjects with a different teacher in
    # front of each; without this the page can only say the room's name.
    slots = (db.query(SubjectSlot)
               .filter(SubjectSlot.class_id.in_(list(seen))).all()
             if seen else [])
    tids = {sl.teacher_id for sl in slots if sl.teacher_id}
    tnames = {u.id: u.name for u in
              db.query(User).filter(User.id.in_(list(tids))).all()} if tids else {}
    by_class: dict = {}
    for sl in sorted(slots, key=lambda x: (x.subject or "").lower()):
        by_class.setdefault(sl.class_id, []).append({
            "name": sl.subject,
            "teacher": tnames.get(sl.teacher_id, ""),
            "mine": sl.teacher_id == user.id,
        })

    dob = getattr(user, "dob", None)
    return {
        "product": _cl.NAME,
        "user": {"id": user.id, "name": user.name, "email": user.email},
        "role": ("admin" if user.is_admin
                 else (ta.role if ta else "student")),
        "institution": ({"id": sc.id, "name": sc.name, "city": sc.city or "",
                         "country": sc.country or "",
                         "product": sc.product or "craxlearn"} if sc else None),
        "scope": scope,
        # What this app will and will not show, and why — so the page can
        # say the reason rather than silently missing a menu item.
        "learning_only": gate["only"], "why": gate["why"],
        "message": gate["message"],
        "deployment_only": CRAXLEARN_ONLY,
        "adult": _cl.adult(dob, dt.date.today()),
        "dob": dob.isoformat() if dob else "",
        "classes": [{
            "id": k.id, "name": k.name, "school": k.school or "",
            # "mine" means I teach here — as the head who made the class, or
            # as the teacher of a subject in it. Both put the same blocks on
            # the board, and only one of them used to.
            "mine": (k.teacher_id == user.id
                     or any(x["mine"] for x in by_class.get(k.id, []))),
            "head": k.teacher_id == user.id,
            "subjects": by_class.get(k.id, []),
            "my_subjects": [x["name"] for x in by_class.get(k.id, [])
                            if x["mine"]] or (
                # A head teacher runs the school and may file under any of
                # the class's subjects.
                [x["name"] for x in by_class.get(k.id, [])]
                if k.teacher_id == user.id else []),
        } for k in classes],
        # Minus anything this particular closure keeps open, so the
        # sidebar and the home page hide exactly what the middleware
        # refuses and nothing more.
        "hidden_pages": ([p for p in _cl.JOB_PAGES
                          if p not in (gate.get("keep") or [])]
                         if gate["only"] else []),
    }


# --------------------------------------------------------------------------
# The school office: notices, attendance, fees
# --------------------------------------------------------------------------
# Written by the office. Read by everybody. A teacher cannot touch any of it
# and neither can a head teacher — see school_admin_user for why.

NOTICE_AUDIENCES = ("all", "teachers", "students", "class", "people")


class NoticeIn(BaseModel):
    title: str = Field(min_length=2, max_length=240)
    body: str = Field(default="", max_length=8000)
    urgent: bool = False
    starts_on: str = Field(default="", max_length=20)
    ends_on: str = Field(default="", max_length=20)
    # Who it reaches. Defaults to everybody, which is what every notice
    # written before this existed meant.
    audience: str = Field(default="all", max_length=16)
    audience_ids: str = Field(default="", max_length=4000)
    class_id: int = 0


def _audience_of(body, user=None, db=None):
    """Validate the target, refusing one that would silently reach nobody.

    A subject teacher may address their own class or named people, and that is
    all. "Everyone", "all teachers" and "all students" are school-wide
    announcements — closures, fee dates, exam timetables — and a school cannot
    have thirty people able to send those. A teacher who needs one asks the
    school admin, which is a slower path on purpose.
    """
    aud = (body.audience or "all").strip().lower()
    if user is not None and db is not None and not is_school_admin(user, db):
        if aud not in ("class", "people"):
            raise HTTPException(
                403, "A teacher posts to their own class or to chosen "
                     "students. For an update to the whole school, ask your "
                     "school admin.")
    if aud not in NOTICE_AUDIENCES:
        raise HTTPException(400, "Send it to everybody, the teachers, the "
                                 "students, one class, or named people.")
    ids = ""
    if aud == "people":
        ids = ",".join(str(int(x)) for x in
                       re.findall(r"\d+", body.audience_ids or ""))
        if not ids:
            # Silently reaching nobody is the worst outcome here: it looks
            # sent and nothing arrives.
            raise HTTPException(400, "Choose at least one person.")
    cid = int(body.class_id or 0)
    if aud == "class" and not cid:
        raise HTTPException(400, "Choose which class.")
    return aud, ids, cid


def _notice_reaches(n, user, db):
    """Is this notice addressed to this person?"""
    aud = (n.audience or "all")
    if aud in ("", "all"):
        return True
    if aud == "people":
        return str(user.id) in (n.audience_ids or "").split(",")
    staff = teacher_row(user, db) is not None
    if aud == "teachers":
        return staff
    if aud == "students":
        return not staff
    if aud == "class":
        return bool(db.query(ClassMember).filter(
            ClassMember.class_id == n.class_id,
            ClassMember.user_id == user.id).first())
    return True


def _notice_json(n):
    return {"id": n.id, "title": n.title, "body": n.body or "",
            "urgent": bool(n.urgent), "starts_on": n.starts_on or "",
            "ends_on": n.ends_on or "",
            "file_name": n.file_name or "", "mime": n.mime or "",
            "size": n.size or 0, "has_file": bool(n.file_data),
            "audience": n.audience or "all",
            "audience_ids": n.audience_ids or "",
            "class_id": n.class_id or 0,
            "at": n.created_at.isoformat() if n.created_at else ""}


class StaffIn(BaseModel):
    name: str = Field(min_length=2, max_length=120)
    # EmailStr, the same validator sign-in uses, and that is the whole point.
    #
    # This was a plain str with a minimum length. So a head could type
    # "latha@bhashyam.100" — a real-looking address whose top-level domain does
    # not exist — and this route accepted it, created the account, printed a
    # one-time password and told the head "they can sign in now". They could
    # not. LoginIn.email is EmailStr, so every attempt was rejected before it
    # reached the password check, and the account was unusable from the moment
    # it was made. The teacher, the head and I all assumed the password or the
    # code was wrong; nothing was wrong with either.
    #
    # Two forms validating the same field differently is how an account gets
    # created that can never be used. They match now, so the head is told at
    # the moment of typing rather than a day later by a teacher who cannot
    # get in.
    # Required, and validated exactly as the sign-in form validates it.
    #
    # It was optional while a subject code was the way in — there was nothing
    # for an address to do. A subject code is a board code now and signs
    # nobody in, so a teacher's address and password ARE their identity, and
    # an account made without one is an account nobody can ever use.
    #
    # EmailStr rather than a string with a minimum length, which is the rule
    # that stopped a whole class of dead account: latha@bhashyam.100 was
    # accepted at creation and refused at sign-in, so the head, the teacher
    # and everyone helping them assumed the password was wrong.
    email: EmailStr
    role: str = Field(default="teacher", max_length=16)


@app.post("/api/head/staff")
def head_create_staff(body: StaffIn, user: User = Depends(head_user),
                      db: Session = Depends(get_db)):
    """The head teacher makes a profile for a member of staff.

    Returns a one-time password the head reads out or writes down. Not
    emailed: a school hiring in August has staff whose school address does
    not exist yet, and an invitation nobody receives is a member of staff
    who cannot work on their first morning.

    A head can create a school-office profile — attendance, fees, notices —
    but that does not give the head those powers. Somebody has to be able to
    appoint the office, and it is the head who knows who works there; what
    the head must not have is the ability to appoint themselves to it, so
    this refuses to grant a role to the account making the request.
    """
    role = body.role.strip().lower()
    if role not in SCHOOL_ROLES:
        raise HTTPException(400, f"Role must be one of: "
                                 f"{', '.join(SCHOOL_ROLES)}")
    t = teacher_row(user, db)
    school, sid = (t.school if t else ""), (t.school_id if t else 0)
    if not user.is_admin and not sid:
        raise HTTPException(403, "Your account is not attached to a school")

    email = (str(body.email).lower().strip() if body.email else "")
    existing = (db.query(User).filter(User.email == email).first()
                if email else None)
    if existing:
        if existing.id == user.id:
            raise HTTPException(
                400, "You cannot change your own role. Ask the platform "
                     "administrator.")
        _grant_teacher(db, existing, school, sid, role)
        # _grant_teacher never downgrades a head; a head setting somebody to
        # the office must actually move them, so it is set here explicitly.
        ta = (db.query(TeacherAccess)
                .filter(TeacherAccess.user_id == existing.id).first())
        if ta and role != "teacher":
            ta.role = role
            db.commit()
        return {"ok": True, "created": False, "user_id": existing.id,
                "name": existing.name, "role": role,
                "note": "That email already had an account, so it was given "
                        "this role at your school. Their existing password "
                        "still works."}

    temp = secrets.token_urlsafe(9)
    u = User(name=body.name.strip()[:120], email=email,
             password_hash=hash_pw(temp), kind="schoolstaff",
             is_active=True, email_verified=False)
    db.add(u)
    db.commit()
    db.refresh(u)
    _grant_teacher(db, u, school, sid, role)
    ta = db.query(TeacherAccess).filter(TeacherAccess.user_id == u.id).first()
    if ta:
        ta.role = role
        db.commit()
    # The password comes back, once, for the office to hand over.
    #
    # It stopped coming back when a subject code became the way in, and that
    # has been undone: a subject code is read off a classroom board by thirty
    # children, so it opens a board and nothing else. A teacher signs in with
    # their own address and their own password, and the office needs
    # something to give them on their first morning.
    #
    # Not emailed. A school hiring in August has staff whose school address
    # does not exist yet, and an invitation nobody receives is a member of
    # staff who cannot work on Monday.
    return {"ok": True, "created": True, "user_id": u.id, "name": u.name,
            "email": u.email, "role": role, "temporary_password": temp,
            "note": "Write this password down or read it out — it is shown "
                    "once and is not emailed. They sign in with it and their "
                    "address. Then put them on a subject: the code that "
                    "subject gets is what opens it on a classroom board."}


@app.get("/api/head/staff")
def head_list_staff(user: User = Depends(head_user),
                    db: Session = Depends(get_db)):
    """Who works here, and in what capacity."""
    t = teacher_row(user, db)
    sid = (t.school_id if t else 0)
    q = db.query(TeacherAccess, User).join(User, User.id == TeacherAccess.user_id)
    if not user.is_admin:
        q = q.filter(TeacherAccess.school_id == sid)
    return {"staff": [{"user_id": u.id, "name": u.name, "email": u.email,
                       "role": ta.role or "teacher",
                       "since": ta.created_at.isoformat() if ta.created_at else ""}
                      for ta, u in q.order_by(TeacherAccess.role).limit(500).all()],
            "roles": list(SCHOOL_ROLES)}


class StaffEditIn(BaseModel):
    name: str = Field(default="", max_length=120)
    email: Optional[EmailStr] = None
    new_password: bool = False


@app.patch("/api/head/staff/{uid}")
def head_edit_staff(uid: int, body: StaffEditIn,
                    user: User = Depends(head_user),
                    db: Session = Depends(get_db)):
    """Correct a member of staff's name or email, or give them a new password.

    There was no way to do either, and both are ordinary. A head who typed
    a colleague's address wrongly had made an account nobody could ever sign
    in to: the address was rejected at the login form, removing their access
    did not free the address because the User row kept it, and adding them
    again with the right one left the dead account behind holding a name.

    The password half exists for the same reason. The one-time password is
    shown once and stored only as a hash, which is right — but "shown once"
    and "no way to issue another" together mean a teacher who closed the tab
    is finished. A head can hand out a new one.

    The account is never replaced, only corrected: the same row keeps its id,
    so the classes it teaches, the work it set and the marks it gave all stay
    attached to it.
    """
    target = db.get(User, uid)
    if not target:
        raise HTTPException(404, "No such account")

    t = teacher_row(user, db)
    sid = (t.school_id if t else 0)
    ta = db.query(TeacherAccess).filter(TeacherAccess.user_id == uid).first()
    if not user.is_admin and (not ta or ta.school_id != sid):
        raise HTTPException(403, "They are not at your school")

    out = {"ok": True, "user_id": uid, "changed": []}

    if body.name.strip():
        target.name = body.name.strip()[:120]
        out["changed"].append("name")

    if body.email:
        new = str(body.email).lower().strip()
        if new != (target.email or "").lower():
            clash = (db.query(User).filter(User.email == new,
                                           User.id != uid).first())
            if clash:
                raise HTTPException(
                    409, "Another account already uses that email address.")
            target.email = new
            out["changed"].append("email")
            out["email"] = new

    if body.new_password:
        # A class-code account has no password anybody holds and no address
        # that receives; handing one a password would make a second way in to
        # a child's account, which is not a thing a head should be able to do.
        if (target.kind or "") == "classcode":
            raise HTTPException(
                400, "That is a pupil's class-code account, not a member of "
                     "staff. It has no password by design.")
        temp = secrets.token_urlsafe(9)
        target.password_hash = hash_pw(temp)
        # Every device holding a session for this account is signed out, which
        # is the point of issuing a new password.
        target.session_token = ""
        out["temporary_password"] = temp
        out["changed"].append("password")

    if not out["changed"]:
        raise HTTPException(400, "Nothing to change.")
    db.commit()
    return out


@app.delete("/api/head/staff/{uid}")
def head_remove_staff(uid: int, user: User = Depends(head_user),
                      db: Session = Depends(get_db)):
    """Take away a member of staff's access. The account itself is kept."""
    if uid == user.id:
        raise HTTPException(400, "You cannot remove your own access")
    ta = db.query(TeacherAccess).filter(TeacherAccess.user_id == uid).first()
    if not ta:
        raise HTTPException(404, "Not found")
    t = teacher_row(user, db)
    if not user.is_admin and ta.school_id != (t.school_id if t else -1):
        raise HTTPException(403, "They are not at your school")
    db.delete(ta)
    db.commit()
    return {"ok": True}


@app.post("/api/office/notice")
def add_notice(body: NoticeIn, user: User = Depends(notice_author_user),
               db: Session = Depends(get_db)):
    aud, ids, cid = _audience_of(body, user, db)
    n = SchoolNotice(school_id=_school_of(user, db), author_id=user.id,
                     title=body.title.strip()[:240],
                     body=body.body.strip()[:8000], urgent=bool(body.urgent),
                     starts_on=body.starts_on.strip()[:20],
                     ends_on=body.ends_on.strip()[:20],
                     audience=aud, audience_ids=ids, class_id=cid)
    db.add(n)
    db.commit()
    db.refresh(n)
    return {"ok": True, "notice": _notice_json(n)}


MAX_NOTICE_MB = 8


def _my_notice(db, nid, user):
    """One notice this person may change.

    Letting teachers post updates quietly let them edit and delete anybody's,
    including the school-wide closure the admin put up an hour earlier. The
    permission to write one is not the permission to unwrite somebody else's.

    So: the school admin may change any notice at their own school, because
    taking down something wrong is part of running it. A teacher may change
    only what they wrote.
    """
    n = db.get(SchoolNotice, nid)
    if not n:
        raise HTTPException(404, "Not found")
    if not user.is_admin and n.school_id != _school_of_anyone(user, db):
        raise HTTPException(403, "That notice belongs to another school")
    if not (user.is_admin or is_school_admin(user, db))             and n.author_id != user.id:
        raise HTTPException(403, "That update was posted by somebody else. "
                                 "Ask your school admin to change it.")
    return n


def _school_of_anyone(user: User, db: Session) -> int:
    """Which school this person belongs to, staff or child.

    _school_of answers for staff and returns 0 for everybody else, which is
    right where it is used and wrong wherever a learner has to be recognised
    as belonging somewhere — a child fetching the timetable attached to their
    own school's notice was refused it.
    """
    sid = _school_of(user, db)
    if sid:
        return sid
    t = teacher_row(user, db)
    if t and t.school_id:
        return t.school_id
    row = (db.query(Klass.school_id)
             .join(ClassMember, ClassMember.class_id == Klass.id)
             .filter(ClassMember.user_id == user.id).first())
    return (row[0] if row and row[0] else 0)


@app.get("/api/my/notices")
def notices_for_me(user: User = Depends(current_user),
                   db: Session = Depends(get_db)):
    """What the school has said to me.

    Staff had nowhere to read a notice at all: the only feed was the
    learner's standing panel, so anything addressed to teachers was written
    and never seen. Dates are honoured here as they are there — a notice with
    dates on it is only a notice between them.
    """
    sid = _school_of_anyone(user, db)
    if not sid:
        return {"notices": []}
    today = dt.date.today().isoformat()
    out = []
    for n in (db.query(SchoolNotice)
                .filter(SchoolNotice.school_id == sid)
                .order_by(SchoolNotice.urgent.desc(),
                          SchoolNotice.created_at.desc()).limit(60).all()):
        if n.starts_on and n.starts_on > today:
            continue
        if n.ends_on and n.ends_on < today:
            continue
        if not _notice_reaches(n, user, db):
            continue
        out.append(_notice_json(n))
    return {"notices": out}


@app.get("/api/office/notices")
def list_notices(user: User = Depends(notice_author_user),
                 db: Session = Depends(get_db)):
    """Everything this school has put up, live or not.

    Deliberately unfiltered by date, unlike the learner's view. Somebody
    deciding what to say next needs to see what has already been said —
    including the notice that expired yesterday and the one that starts on
    Monday, which are exactly the two a date filter hides.
    """
    sid = _school_of(user, db)
    q = db.query(SchoolNotice)
    if not user.is_admin:
        q = q.filter(SchoolNotice.school_id == sid)
    rows = q.order_by(SchoolNotice.created_at.desc()).limit(200).all()
    return {"notices": [_notice_json(n) for n in rows]}


@app.patch("/api/office/notice/{nid}")
def edit_notice(nid: int, body: NoticeIn,
                user: User = Depends(notice_author_user),
                db: Session = Depends(get_db)):
    """Correct one, rather than deleting and rewriting it.

    A wrong time used to be fixed by removing the notice and posting a new
    one, and in between the school was told nothing at all.
    """
    n = _my_notice(db, nid, user)
    n.title = body.title.strip()[:240]
    n.body = body.body.strip()[:8000]
    n.urgent = bool(body.urgent)
    n.starts_on = body.starts_on.strip()[:20]
    n.ends_on = body.ends_on.strip()[:20]
    n.audience, n.audience_ids, n.class_id = _audience_of(body, user, db)
    db.commit()
    db.refresh(n)
    return {"ok": True, "notice": _notice_json(n)}


@app.post("/api/office/notice/{nid}/file")
async def attach_to_notice(nid: int, file: UploadFile = File(...),
                           user: User = Depends(notice_author_user),
                           db: Session = Depends(get_db)):
    """A picture or a PDF, on a notice that already exists."""
    n = _my_notice(db, nid, user)
    raw = await file.read()
    if not raw:
        raise HTTPException(400, "That file was empty.")
    if len(raw) > MAX_NOTICE_MB * 1024 * 1024:
        raise HTTPException(400, f"Keep it under {MAX_NOTICE_MB}MB.")
    mime = (file.content_type or "").lower()
    # A notice is read by every child in the school, so what can be put on
    # one is a short list rather than whatever the browser reported.
    if not (mime.startswith("image/") or mime == "application/pdf"):
        raise HTTPException(400, "Attach a picture or a PDF.")
    n.file_data = base64.b64encode(raw).decode()
    n.file_name = (file.filename or "attachment")[:160]
    n.mime = mime[:80]
    n.size = len(raw)
    db.commit()
    db.refresh(n)
    return {"ok": True, "notice": _notice_json(n)}


@app.delete("/api/office/notice/{nid}/file")
def unattach_notice(nid: int, user: User = Depends(notice_author_user),
                    db: Session = Depends(get_db)):
    n = _my_notice(db, nid, user)
    n.file_data = ""
    n.file_name = ""
    n.mime = ""
    n.size = 0
    db.commit()
    return {"ok": True}


@app.get("/api/office/notice/{nid}/file")
def notice_file(nid: int, user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """The attachment, for anybody the notice was addressed to.

    Read by the whole school, so this checks membership of the school rather
    than of a class — which is the point of a notice.
    """
    n = db.get(SchoolNotice, nid)
    if not n or not n.file_data:
        raise HTTPException(404, "Not found")
    if not user.is_admin and n.school_id             and n.school_id != _school_of_anyone(user, db):
        raise HTTPException(403, "That notice belongs to another school")
    # And only if it was addressed to them. An attachment is the notice.
    if not user.is_admin and not _notice_reaches(n, user, db):
        raise HTTPException(403, "That notice was not addressed to you")
    try:
        raw = base64.b64decode(n.file_data)
    except Exception:
        raise HTTPException(500, "That file is stored damaged")
    return Response(
        content=raw, media_type=n.mime or "application/octet-stream",
        headers=_disposition((n.file_name or "notice")[:80], "inline"))


class AssignIn(BaseModel):
    class_id: int
    subject: str = Field(min_length=1, max_length=80)
    user_id: int = 0          # 0 detaches whoever holds it


@app.post("/api/head/assign")
def head_assign_subject(body: AssignIn, user: User = Depends(head_user),
                        db: Session = Depends(get_db)):
    """Put a named teacher on a subject, without the code round trip.

    A subject slot has always carried a code the teacher redeems, which is
    right when the school is handing codes to people it has not enrolled yet.
    It is wrong once the admin has already created the staff account: they
    know exactly who teaches Physics in 8-A, and reading a code down the
    corridor to somebody sitting in the staffroom is a step that exists only
    because the software could not do the obvious thing.

    No restriction on how many. A teacher may hold several subjects in one
    class and teach across as many classes as the timetable says, which is
    what a real timetable looks like — both were already allowed and are
    asserted so they stay that way.
    """
    k = _own_class(db, body.class_id, user)
    subject = body.subject.strip()[:80]
    slot = (db.query(SubjectSlot)
              .filter(SubjectSlot.class_id == k.id,
                      func.lower(SubjectSlot.subject) == subject.lower())
              .first())
    if not slot:
        slot = SubjectSlot(class_id=k.id, subject=subject,
                           code=_gen_slot_code(db), teacher_id=0,
                           status="open")
        db.add(slot)

    if not body.user_id:
        # Detach. The slot and its code survive, so the subject still exists
        # on the timetable while the school works out who is covering it.
        slot.teacher_id = 0
        slot.status = "open"
        db.commit()
        return {"ok": True, "subject": slot.subject, "teacher": "",
                "code": slot.code}

    target = db.get(User, body.user_id)
    if not target:
        raise HTTPException(404, "No such member of staff")
    t = teacher_row(target, db)
    # Somebody who is not staff anywhere is a new hire, and assigning them a
    # subject is exactly how they become staff here — refusing them was the
    # bug: the guard rejected precisely the person you would be assigning.
    # What must still be refused is somebody who already works at ANOTHER
    # school, which would quietly move them between schools.
    if (t is not None and not user.is_admin
            and t.school_id != _school_of(user, db)):
        raise HTTPException(403, "That is not your member of staff")
    if t is None:
        # Assigning somebody a subject is what makes them a teacher here.
        _grant_teacher(db, target, k.school or "", k.school_id or 0, "teacher")

    slot.teacher_id = target.id
    slot.status = "claimed"
    db.commit()
    return {"ok": True, "subject": slot.subject,
            "teacher": target.name or target.email, "code": slot.code}


@app.get("/api/head/people")
def head_find_people(q: str = "", kind: str = "",
                     user: User = Depends(notice_author_user),
                     db: Session = Depends(get_db)):
    """Find somebody to address a notice to, by name or by id.

    A school with four hundred children cannot be a dropdown. Typing part of
    a name is how anybody actually looks for a person; typing the id is how
    you confirm you have the right one of two children called Ravi.

    Returns staff and learners in this school only, with the id the notice
    needs. Never anybody else's school: this is a list of children's names.
    """
    sid = _school_of_anyone(user, db)
    if not sid and not user.is_admin:
        return {"people": []}
    term = (q or "").strip().lower()[:80]
    want = (kind or "").strip().lower()
    out = []

    # A subject teacher sees the children they teach and nobody else.
    #
    # They can address an update to named students, so they need to find
    # them — but a register is a list of children's names, and "can post to
    # my class" must not become "can read every name in the school". The
    # school admin sees all of it, because running the school is the job
    # that needs it.
    mine = None
    if not is_school_admin(user, db):
        mine = {r[0] for r in db.query(SubjectSlot.class_id)
                                .filter(SubjectSlot.teacher_id == user.id).all()}
        mine |= {r[0] for r in db.query(Klass.id)
                                .filter(Klass.teacher_id == user.id).all()}
        if not mine:
            return {"people": [], "count": 0}

    # Staff are listed for the school admin only. A teacher's updates go to
    # their students; addressing colleagues is what the admin's school-wide
    # notice is for.
    if mine is None and want in ("", "teacher", "teachers"):
        rows = (db.query(TeacherAccess, User)
                  .join(User, User.id == TeacherAccess.user_id))
        if not user.is_admin:
            rows = rows.filter(TeacherAccess.school_id == sid)
        for ta, u in rows.limit(500).all():
            out.append({"id": u.id, "name": u.name or u.email,
                        "kind": "teacher", "role": ta.role or "teacher",
                        "where": ""})

    if want in ("", "student", "students"):
        rows = (db.query(RosterName, Klass)
                  .join(Klass, Klass.id == RosterName.class_id)
                  .filter(RosterName.claimed_by != 0))
        if not user.is_admin:
            rows = rows.filter(Klass.school_id == sid)
        if mine is not None:
            rows = rows.filter(Klass.id.in_(mine))
        for r, k in rows.limit(2000).all():
            out.append({"id": r.claimed_by, "name": r.name,
                        "kind": "student", "role": "student",
                        "where": k.name})

    if term:
        # By name, or by the id typed straight in.
        out = [p for p in out
               if term in p["name"].lower() or term == str(p["id"])]
    out.sort(key=lambda p: (p["kind"], p["name"].lower()))
    return {"people": out[:200], "count": len(out)}


@app.get("/api/head/students")
def head_list_students(user: User = Depends(head_user),
                       db: Session = Depends(get_db)):
    """Every child on every register in this school, and who has signed in.

    A head could see the staff and could type one class register at a time,
    but there was nowhere to see the learners together — so "how many have
    actually signed in" was answered by opening every class in turn.
    """
    t = teacher_row(user, db)
    sid = (t.school_id if t else 0)
    q = db.query(Klass)
    if not user.is_admin:
        q = q.filter(Klass.school_id == sid)
    classes = q.order_by(Klass.name.asc()).all()
    out, signed, total = [], 0, 0
    for k in classes:
        rows = (db.query(RosterName)
                  .filter(RosterName.class_id == k.id)
                  .order_by(RosterName.name.asc()).all())
        total += len(rows)
        signed += sum(1 for r in rows if r.claimed_by)
        out.append({"class_id": k.id, "class_name": k.name,
                    "join_code": k.join_code,
                    "students": [{"id": r.id, "name": r.name,
                                  "signed_in": bool(r.claimed_by)}
                                 for r in rows]})
    return {"classes": out, "total": total, "signed_in": signed}


@app.delete("/api/office/notice/{nid}")
def drop_notice(nid: int, user: User = Depends(notice_author_user),
                db: Session = Depends(get_db)):
    """Take one down. Yours always; anybody's if you run the school.

    This had its own copy of the ownership check, written when only the
    office could post and so needing only to compare schools. Letting
    teachers post left that copy behind, and a subject teacher could delete
    the school-wide closure the admin put up an hour earlier — the permission
    to write one is not the permission to unwrite somebody else's.
    """
    n = _my_notice(db, nid, user)
    db.delete(n)
    db.commit()
    return {"ok": True}


class AttendanceIn(BaseModel):
    class_id: int
    day: str = Field(min_length=8, max_length=20)     # ISO date
    # {user_id: present}. The whole class in one request, because a register
    # is taken in one go and thirty requests is thirty chances to half-finish.
    present: dict = {}
    notes: dict = {}


@app.post("/api/office/attendance")
def mark_attendance(body: AttendanceIn,
                    user: User = Depends(school_admin_user),
                    db: Session = Depends(get_db)):
    """Take the register for one class on one day.

    Idempotent per (learner, day): running it again corrects the day rather
    than adding a second opinion of it. That is what makes "marked absent by
    mistake" a fixable thing, which is the single most common thing a parent
    rings a school about.
    """
    try:
        day = dt.date.fromisoformat(body.day.strip()).isoformat()
    except ValueError:
        raise HTTPException(400, "Give the day as YYYY-MM-DD")
    k = db.get(Klass, body.class_id)
    if not k:
        raise HTTPException(404, "No such class")
    sid = _school_of(user, db)
    if not user.is_admin and k.school_id != sid:
        raise HTTPException(403, "That class belongs to another school")

    members = {m.user_id for m in db.query(ClassMember)
               .filter(ClassMember.class_id == k.id).all()}
    done = 0
    for raw_uid, present in (body.present or {}).items():
        try:
            uid = int(raw_uid)
        except (TypeError, ValueError):
            continue
        # Only children who are actually in this class. A register that will
        # mark anybody whose id you send is a register that can be used to
        # write rows against a learner in another school.
        if uid not in members:
            continue
        row = (db.query(Attendance)
                 .filter(Attendance.user_id == uid, Attendance.day == day)
                 .first())
        if not row:
            row = Attendance(user_id=uid, day=day)
            db.add(row)
        row.school_id = k.school_id or 0
        row.class_id = k.id
        row.present = bool(present)
        row.note = str((body.notes or {}).get(raw_uid, ""))[:200]
        row.marked_by = user.id
        done += 1
    db.commit()
    return {"ok": True, "day": day, "marked": done, "in_class": len(members)}


@app.get("/api/office/attendance")
def read_attendance(class_id: int, day: str = "",
                    user: User = Depends(school_admin_user),
                    db: Session = Depends(get_db)):
    """The register for one class, on one day, with everybody's running total."""
    k = db.get(Klass, class_id)
    if not k:
        raise HTTPException(404, "No such class")
    if not user.is_admin and k.school_id != _school_of(user, db):
        raise HTTPException(403, "That class belongs to another school")
    day = (day or dt.date.today().isoformat()).strip()[:20]
    rows = (db.query(ClassMember, User)
              .join(User, User.id == ClassMember.user_id)
              .filter(ClassMember.class_id == class_id).all())
    today = {a.user_id: a for a in db.query(Attendance)
             .filter(Attendance.class_id == class_id,
                     Attendance.day == day).all()}
    out = []
    for _cm, u in rows:
        a = today.get(u.id)
        out.append({"user_id": u.id, "name": u.name,
                    "present": (None if a is None else bool(a.present)),
                    "note": (a.note if a else ""),
                    **_attendance_totals(db, u.id)})
    out.sort(key=lambda r: r["name"].lower())
    return {"class_id": class_id, "class_name": k.name, "day": day,
            "students": out}


def _attendance_totals(db, uid):
    """Days present, days recorded, and the percentage — computed, never stored.

    A stored percentage cannot be corrected, and correcting a wrongly marked
    day is the whole reason the rows exist.
    """
    total = (db.query(func.count(Attendance.id))
               .filter(Attendance.user_id == uid).scalar() or 0)
    present = (db.query(func.count(Attendance.id))
                 .filter(Attendance.user_id == uid,
                         Attendance.present == True).scalar() or 0)  # noqa: E712
    return {"days_present": present, "days_recorded": total,
            # None rather than 100 when nothing has been recorded. A learner
            # whose school has not started taking the register has not got
            # perfect attendance, and showing 100% is a number somebody will
            # quote back.
            "attendance_pct": (round(present * 100.0 / total, 1)
                               if total else None)}


class FeeIn(BaseModel):
    user_id: int
    title: str = Field(min_length=2, max_length=240)
    amount: int = 0                       # paise
    paid: int = 0                         # paise
    currency: str = Field(default="INR", max_length=8)
    due_on: str = Field(default="", max_length=20)
    note: str = Field(default="", max_length=2000)
    kind: str = Field(default="fee", max_length=12)     # fee | buy


def _fee_json(f):
    return {"id": f.id, "title": f.title, "note": f.note or "",
            "amount": f.amount or 0, "paid": f.paid or 0,
            "outstanding": max((f.amount or 0) - (f.paid or 0), 0),
            "currency": f.currency or "INR", "due_on": f.due_on or "",
            "kind": f.kind or "fee",
            "settled": (f.paid or 0) >= (f.amount or 0),
            "at": f.created_at.isoformat() if f.created_at else "",
            "paid_at": f.paid_at.isoformat() if f.paid_at else ""}


@app.post("/api/office/fee")
def set_fee(body: FeeIn, user: User = Depends(school_admin_user),
            db: Session = Depends(get_db)):
    """Record something a learner owes, or that they have paid.

    This takes no money and is not a payment page. It records what the
    office already knows, so a learner can see their balance without ringing
    up — and so nobody has to be told a number over the phone that neither
    of them can check afterwards.
    """
    target = db.get(User, body.user_id)
    if not target:
        raise HTTPException(404, "No such learner")
    sid = _school_of(user, db)
    if not user.is_admin:
        _same_school_or_403(db, target, sid)
    if body.amount < 0 or body.paid < 0:
        raise HTTPException(400, "Amounts cannot be negative")
    f = FeeItem(school_id=sid, user_id=target.id,
                title=body.title.strip()[:240], note=body.note.strip()[:2000],
                amount=int(body.amount), paid=int(body.paid),
                currency=(body.currency or "INR").upper()[:8],
                due_on=body.due_on.strip()[:20],
                kind="buy" if body.kind == "buy" else "fee",
                marked_by=user.id,
                paid_at=now() if body.paid >= body.amount > 0 else None)
    db.add(f)
    db.commit()
    db.refresh(f)
    return {"ok": True, "item": _fee_json(f)}


class FeePayIn(BaseModel):
    paid: int = 0                          # paise, the new total received


class FeePlanIn(BaseModel):
    class_id: int = 0            # 0 = every learner in the school
    title: str = Field(min_length=2, max_length=240)
    note: str = Field(default="", max_length=2000)
    amount: int = 0              # paise
    due_on: str = Field(default="", max_length=20)
    kind: str = Field(default="fee", max_length=12)


@app.post("/api/office/fee/plan")
def office_fee_plan(body: FeePlanIn, user: User = Depends(school_admin_user),
                    db: Session = Depends(get_db)):
    """One fee, put on every learner in a class or in the school.

    Term fees are the same number for everybody, and setting them one child at
    a time is how a class of forty gets thirty-nine of them and nobody notices
    until a parent asks why they were not told.

    Skips a learner who already has this exact title outstanding, so running
    it twice does not bill anybody twice — which is the mistake that costs a
    school its parents' trust rather than an afternoon.
    """
    sid = _school_of(user, db)
    q = (db.query(ClassMember.user_id).join(Klass, Klass.id == ClassMember.class_id))
    if body.class_id:
        _own_class(db, body.class_id, user)
        q = q.filter(ClassMember.class_id == body.class_id)
    elif sid:
        q = q.filter(Klass.school_id == sid)
    elif not user.is_admin:
        raise HTTPException(403, "No school on this account")
    uids = sorted({r[0] for r in q.all()})
    if not uids:
        raise HTTPException(400, "Nobody is enrolled there yet.")

    title = body.title.strip()[:240]
    already = {f.user_id for f in db.query(FeeItem)
               .filter(FeeItem.user_id.in_(uids), FeeItem.title == title,
                       FeeItem.paid < FeeItem.amount).all()}
    made = 0
    for uid in uids:
        if uid in already:
            continue
        db.add(FeeItem(school_id=sid, user_id=uid, title=title,
                       note=body.note.strip()[:2000],
                       amount=max(int(body.amount or 0), 0),
                       due_on=body.due_on.strip()[:20],
                       kind=(body.kind or "fee").strip()[:12],
                       marked_by=user.id))
        made += 1
    db.commit()
    return {"ok": True, "billed": made, "skipped": len(already),
            "learners": len(uids)}


@app.get("/api/office/fees")
def office_fee_book(user: User = Depends(school_admin_user),
                    db: Session = Depends(get_db)):
    """What has come in and what is still to come, for the whole school.

    The office could set a fee on a learner and see that learner. It could not
    see the school: how much is outstanding, who is overdue today, what falls
    due next. That is the question an admin actually has — and answering it by
    opening four hundred learners one at a time is the reason schools keep
    this in a spreadsheet instead.
    """
    sid = _school_of(user, db)
    q = db.query(FeeItem)
    if not user.is_admin:
        q = q.filter(FeeItem.school_id == sid)
    rows = q.order_by(FeeItem.created_at.desc()).limit(2000).all()
    names = {u.id: (u.name or u.email)
             for u in db.query(User).filter(
                 User.id.in_([f.user_id for f in rows] or [0])).all()}
    today = dt.date.today().isoformat()

    def one(f):
        out = max((f.amount or 0) - (f.paid or 0), 0)
        return {"id": f.id, "who": names.get(f.user_id, ""),
                "user_id": f.user_id, "title": f.title,
                "amount": f.amount or 0, "paid": f.paid or 0,
                "outstanding": out, "due_on": f.due_on or "",
                "kind": f.kind or "fee",
                "overdue": bool(out and f.due_on and f.due_on < today),
                "at": f.created_at.isoformat() if f.created_at else "",
                "paid_at": f.paid_at.isoformat() if f.paid_at else ""}

    items = [one(f) for f in rows]
    return {
        "recent": [i for i in items if i["paid"]][:100],
        "upcoming": sorted([i for i in items if i["outstanding"]],
                           key=lambda i: (i["due_on"] or "9999")),
        "totals": {
            "billed": sum(i["amount"] for i in items),
            "collected": sum(i["paid"] for i in items),
            "outstanding": sum(i["outstanding"] for i in items),
            "overdue": sum(i["outstanding"] for i in items if i["overdue"]),
            "learners": len({i["user_id"] for i in items}),
        },
    }


@app.post("/api/office/fee/{fid}/paid")
def mark_fee_paid(fid: int, body: FeePayIn,
                  user: User = Depends(school_admin_user),
                  db: Session = Depends(get_db)):
    f = db.get(FeeItem, fid)
    if not f:
        raise HTTPException(404, "Not found")
    if not user.is_admin and f.school_id != _school_of(user, db):
        raise HTTPException(403, "That belongs to another school")
    if body.paid < 0:
        raise HTTPException(400, "Amounts cannot be negative")
    f.paid = int(body.paid)
    f.marked_by = user.id
    f.paid_at = now() if f.paid >= (f.amount or 0) else None
    db.commit()
    return {"ok": True, "item": _fee_json(f)}


@app.delete("/api/office/fee/{fid}")
def drop_fee(fid: int, user: User = Depends(school_admin_user),
             db: Session = Depends(get_db)):
    f = db.get(FeeItem, fid)
    if not f:
        raise HTTPException(404, "Not found")
    if not user.is_admin and f.school_id != _school_of(user, db):
        raise HTTPException(403, "That belongs to another school")
    db.delete(f)
    db.commit()
    return {"ok": True}


def _same_school_or_403(db, target: User, school_id: int):
    """Is this learner one of ours? Membership through a class is the only link."""
    if not school_id:
        raise HTTPException(403, "Your account is not attached to a school")
    row = (db.query(Klass.school_id)
             .join(ClassMember, ClassMember.class_id == Klass.id)
             .filter(ClassMember.user_id == target.id,
                     Klass.school_id == school_id).first())
    if row is None:
        raise HTTPException(403, "That learner is not at your school")


@app.get("/api/office/learners")
def office_learners(user: User = Depends(school_admin_user),
                    db: Session = Depends(get_db)):
    """Everybody at this school, with their attendance and what they owe."""
    sid = _school_of(user, db)
    q = (db.query(User, Klass)
           .join(ClassMember, ClassMember.user_id == User.id)
           .join(Klass, Klass.id == ClassMember.class_id))
    if not user.is_admin:
        q = q.filter(Klass.school_id == sid)
    out = []
    for u, k in q.limit(2000).all():
        fees = db.query(FeeItem).filter(FeeItem.user_id == u.id).all()
        out.append({"user_id": u.id, "name": u.name,
                    "class_id": k.id, "class_name": k.name,
                    "owed": sum(max((f.amount or 0) - (f.paid or 0), 0)
                                for f in fees),
                    **_attendance_totals(db, u.id)})
    out.sort(key=lambda r: (r["class_name"].lower(), r["name"].lower()))
    return {"learners": out, "school_id": sid}


@app.get("/api/craxlearn/standing")
def my_standing(user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """What a learner needs to know about themselves that is not schoolwork.

    Attendance, what is owed, what still has to be bought, and whatever the
    office has put up. One call, because it is one glance — a student
    checking four screens to find out whether they are in trouble checks
    none of them.

    Read-only for everybody. Nothing here can be changed from a learner's
    session, and the teacher's session cannot change it either.
    """
    sid = 0
    row = (db.query(Klass.school_id)
             .join(ClassMember, ClassMember.class_id == Klass.id)
             .filter(ClassMember.user_id == user.id).first())
    if row is not None:
        sid = row[0] or 0
    if not sid:
        t = teacher_row(user, db)
        sid = (t.school_id if t else 0) or 0

    fees = (db.query(FeeItem).filter(FeeItem.user_id == user.id)
              .order_by(FeeItem.created_at.desc()).limit(100).all())
    today = dt.date.today().isoformat()
    notices = []
    if sid:
        for n in (db.query(SchoolNotice)
                    .filter(SchoolNotice.school_id == sid)
                    .order_by(SchoolNotice.urgent.desc(),
                              SchoolNotice.created_at.desc()).limit(40).all()):
            # A notice with dates on it is only a notice between them. An
            # exam timetable from last term on a child's home screen is how
            # the whole panel stops being read.
            if n.starts_on and n.starts_on > today:
                continue
            if n.ends_on and n.ends_on < today:
                continue
            # Addressed to this person, or to everybody. A staff meeting
            # reaching four hundred children is how the panel stops being
            # read at all.
            if not _notice_reaches(n, user, db):
                continue
            notices.append(_notice_json(n))

    return {
        **_attendance_totals(db, user.id),
        "fees": [_fee_json(f) for f in fees if (f.kind or "fee") == "fee"],
        "to_buy": [_fee_json(f) for f in fees if (f.kind or "fee") == "buy"],
        "owed": sum(max((f.amount or 0) - (f.paid or 0), 0) for f in fees),
        "currency": (fees[0].currency if fees else "INR"),
        "notices": notices,
        "school_id": sid,
    }


# --------------------------------------------------------------------------
# The register, and signing in with nothing but a class code
# --------------------------------------------------------------------------
class RosterIn(BaseModel):
    # One name per line, as a teacher would paste them off a register.
    names: str = Field(default="", max_length=8000)


@app.post("/api/teacher/class/{cid}/roster")
def set_roster(cid: int, body: RosterIn, user: User = Depends(head_user),
               db: Session = Depends(get_db)):
    """Type the register once, so nobody has to invent a password.

    Adds names; never removes one that a learner has already claimed. A
    teacher retyping the list with a typo fixed must not delete the account
    a child has work in — so a claimed name is left exactly as it is and
    only genuinely new names are added.
    """
    _own_class(db, cid, user)
    # Every row, including ones taken off the register: a name that is
    # already here must never get a SECOND row. Two rows with one name is
    # two accounts for one child, and the one holding their work is
    # whichever they happened to tap first.
    have = {r.name.strip().lower(): r for r in db.query(RosterName)
            .filter(RosterName.class_id == cid).all()}
    back = 0
    added = 0
    for line in (body.names or "").splitlines():
        # "Asha Rao, 8A-014" — the name, then the school's own id for them.
        # Comma-separated because that is how a register pastes out of a
        # spreadsheet, which is where every one of these lists comes from.
        parts = [p.strip() for p in line.split(",", 1)]
        name = " ".join(parts[0].split())[:80]
        code = (parts[1] if len(parts) > 1 else "")[:40]
        if len(name) < 2:
            continue
        was = have.get(name.lower())
        if was is not None:
            # Retyping the register is how a teacher puts back somebody who
            # came off it — the row they already have, not a new one.
            if getattr(was, "removed_at", None):
                was.removed_at = None
                back += 1
            continue
        db.add(RosterName(class_id=cid, name=name, student_code=code))
        have[name.lower()] = True
        added += 1
    db.commit()
    return {"ok": True, "added": added, "restored": back,
            **_roster_json(db, cid)}


def _roster_json(db, cid):
    rows = (db.query(RosterName).filter(RosterName.class_id == cid)
              .order_by(RosterName.name.asc()).all())
    return {"roster": [{"id": r.id, "name": r.name,
                        "student_code": r.student_code or "",
                        "user_id": r.claimed_by or 0,
                        "claimed": bool(r.claimed_by),
                        "removed": bool(r.removed_at)} for r in rows],
            "free": sum(1 for r in rows
                        if not r.claimed_by and not r.removed_at),
            "removed": sum(1 for r in rows if r.removed_at),
            "total": sum(1 for r in rows if not r.removed_at)}


@app.get("/api/teacher/class/{cid}/roster")
def get_roster(cid: int, user: User = Depends(teacher_user),
               db: Session = Depends(get_db)):
    _own_class(db, cid, user)
    return _roster_json(db, cid)


class RenameIn(BaseModel):
    name: str = Field(min_length=2, max_length=120)
    # The school's own roll number. Optional, because a school that does not
    # use one should not be made to invent one — but where it exists it is
    # how staff actually refer to a child, and searching the register by it
    # is faster than scrolling four hundred names.
    student_code: str = Field(default="", max_length=40)


@app.patch("/api/teacher/roster/{rid}")
def rename_roster_name(rid: int, body: RenameIn,
                       user: User = Depends(teacher_user),
                       db: Session = Depends(get_db)):
    """Correct a name, including one already claimed.

    Deleting was the only way to fix a spelling, and deleting a claimed name
    is refused precisely because there is an account behind it — so a child
    whose name was typed wrong was stuck with it for the year.

    Renaming is safe where deleting is not: the row keeps its id and its
    claim, so the account, its class and its work are all untouched. Only
    what it is called changes, which is the whole point.
    """
    r = db.get(RosterName, rid)
    if not r:
        raise HTTPException(404, "Not found")
    _own_class(db, r.class_id, user)
    new = body.name.strip()[:120]
    if not new:
        raise HTTPException(400, "A name cannot be blank.")
    clash = (db.query(RosterName)
               .filter(RosterName.class_id == r.class_id,
                       func.lower(RosterName.name) == new.lower(),
                       RosterName.id != r.id).first())
    if clash:
        raise HTTPException(409, "Another child in this class is already "
                                 "called that.")
    r.name = new
    code = (body.student_code or "").strip()[:40]
    if code:
        clash_code = (db.query(RosterName)
                        .filter(RosterName.class_id == r.class_id,
                                func.lower(RosterName.student_code)
                                == code.lower(),
                                RosterName.id != r.id).first())
        if clash_code:
            raise HTTPException(409, "Another child in this class already has "
                                     "that roll number.")
    r.student_code = code
    # The account keeps its own display name in step, or a child sees one
    # name on the register and another at the top of the screen.
    if r.claimed_by:
        u = db.get(User, r.claimed_by)
        if u:
            u.name = new
    db.commit()
    return {"ok": True, "id": r.id, "name": r.name,
            "student_code": r.student_code or "",
            "signed_in": bool(r.claimed_by)}


@app.delete("/api/teacher/roster/{rid}")
def drop_roster_name(rid: int, user: User = Depends(head_user),
                     db: Session = Depends(get_db)):
    """Remove a name nobody has claimed. A claimed one is an account."""
    r = db.get(RosterName, rid)
    if not r:
        raise HTTPException(404, "Not found")
    _own_class(db, r.class_id, user)
    if r.claimed_by:
        raise HTTPException(
            400, "That name has been claimed and now has work behind it. "
                 "Take them off the register instead — it keeps the account "
                 "and can be undone.")
    db.delete(r)
    db.commit()
    return {"ok": True}


@app.post("/api/teacher/roster/{rid}/remove")
def remove_from_register(rid: int, on: bool = True,
                         user: User = Depends(teacher_user),
                         db: Session = Depends(get_db)):
    """Take a child off the sign-in list without taking their account away.

    A child who leaves in October has to stop appearing on the register, and
    the only way to do that used to be deleting the row — which is the one
    thing that must not happen, because for a class-code account the row is
    the credential and their work is behind it.

    So the row stays and is marked. It stops being offered at sign-in, the
    account and everything in it survives, and the school keeps its record.
    Clearing the mark puts them back, which matters because "left the
    school" and "was off for a term" are told apart by a human, afterwards.
    """
    r = db.get(RosterName, rid)
    if not r:
        raise HTTPException(404, "Not found")
    _own_class(db, r.class_id, user)
    r.removed_at = now() if on else None
    db.commit()
    return {"ok": True, "removed": bool(r.removed_at), "name": r.name,
            **_roster_json(db, r.class_id)}


# --------------------------------------------------------------------------
# Which learners a member of staff may look at
# --------------------------------------------------------------------------
# One function answers it, and everything that shows a learner's detail goes
# through it. Written once on purpose: this is the rule that keeps a teacher
# out of another teacher's pupils' records, and two copies of it would drift
# until one of them let somebody through.
#
# The rule is the classroom, not the school. A teacher may teach in several
# classrooms and sees the learners in those; a head sees their whole school
# because they are responsible for it; the office sees their whole school
# because attendance and fees are theirs to keep. Nobody sees outside it.

def _my_class_ids(db, user) -> set:
    """Every classroom this member of staff may look into."""
    if user.is_admin:
        return None                     # None means "no restriction"
    t = teacher_row(user, db)
    if not t:
        return set()
    if t.role in ("head", "schooladmin"):
        return {k.id for k in db.query(Klass)
                .filter(Klass.school_id == t.school_id).all()} or {
                    k.id for k in db.query(Klass)
                    .filter(Klass.teacher_id == user.id).all()}
    # A subject teacher: the classrooms where they hold a subject, plus any
    # they were made the owning teacher of.
    ids = {s.class_id for s in db.query(SubjectSlot)
           .filter(SubjectSlot.teacher_id == user.id).all()}
    ids |= {k.id for k in db.query(Klass)
            .filter(Klass.teacher_id == user.id).all()}
    return ids


def _may_see_learner(db, user, learner_id) -> bool:
    """Is this learner in one of my classrooms?"""
    mine = _my_class_ids(db, user)
    if mine is None:
        return True
    if not mine:
        return False
    return db.query(ClassMember).filter(
        ClassMember.user_id == learner_id,
        ClassMember.class_id.in_(list(mine))).first() is not None


@app.get("/api/teacher/roll")
def teacher_roll(user: User = Depends(teacher_user),
                 db: Session = Depends(get_db)):
    """My classrooms and who is in them. Nothing outside them.

    A teacher's own first screen: the classes the head put them in, and the
    learners the head enrolled. Not a search over the school — a list of
    exactly what is theirs, which is both the useful thing and the safe one.
    """
    mine = _my_class_ids(db, user)
    q = db.query(Klass)
    if mine is not None:
        if not mine:
            return {"classes": [], "note": "You have not been given a class yet."}
        q = q.filter(Klass.id.in_(list(mine)))
    out = []
    for k in q.order_by(Klass.name.asc()).limit(100).all():
        codes = {r.claimed_by: r.student_code for r in db.query(RosterName)
                 .filter(RosterName.class_id == k.id).all() if r.claimed_by}
        learners = (db.query(User)
                      .join(ClassMember, ClassMember.user_id == User.id)
                      .filter(ClassMember.class_id == k.id)
                      .order_by(User.name.asc()).all())
        subs = sorted({s.subject for s in db.query(SubjectSlot)
                       .filter(SubjectSlot.class_id == k.id,
                               SubjectSlot.teacher_id == user.id).all()})
        out.append({
            "id": k.id, "name": k.name, "school": k.school or "",
            "join_code": k.join_code, "my_subjects": subs,
            "students": [{"user_id": u.id, "name": u.name,
                          "student_code": codes.get(u.id, ""),
                          **_attendance_totals(db, u.id)} for u in learners],
        })
    return {"classes": out}


@app.get("/api/teacher/student/{uid}")
def teacher_student(uid: int, user: User = Depends(teacher_user),
                    db: Session = Depends(get_db)):
    """One learner's progress — but only one of mine.

    What they have finished, what they searched for, what they scored, what
    they have handed in. A teacher asking after a child they teach is the
    ordinary case; the same request for a child in another teacher's class,
    or another school, is refused rather than filtered, so there is no
    version of this that returns a partial record and looks like an answer.
    """
    if not _may_see_learner(db, user, uid):
        raise HTTPException(
            403, "That learner is not in any of your classes.")
    u = db.get(User, uid)
    if not u:
        raise HTTPException(404, "Not found")

    mine = _my_class_ids(db, user)
    classes = (db.query(Klass)
                 .join(ClassMember, ClassMember.class_id == Klass.id)
                 .filter(ClassMember.user_id == uid).all())
    if mine is not None:
        classes = [k for k in classes if k.id in mine]

    code = (db.query(RosterName.student_code)
              .filter(RosterName.claimed_by == uid).first())

    # What they searched and asked. Only their own records, and only from
    # inside this school's scope — the same rows the aggregate view counts,
    # named here because a teacher asking about one child they teach is a
    # different question from browsing the school.
    asked = (db.query(LearnRecord)
               .filter(LearnRecord.user_id == uid)
               .order_by(LearnRecord.created_at.desc()).limit(60).all())

    quizzes = (db.query(QuizResult).filter(QuizResult.user_id == uid)
                 .order_by(QuizResult.created_at.desc()).limit(60).all())

    done = (db.query(func.count(Progress.id))
              .filter(Progress.user_id == uid,
                      Progress.completed == True).scalar() or 0)  # noqa: E712

    subs = (db.query(Submission, Assignment)
              .join(Assignment, Assignment.id == Submission.assignment_id)
              .filter(Submission.user_id == uid)
              .order_by(Submission.updated_at.desc()).limit(60).all())
    if mine is not None:
        subs = [(s, a) for s, a in subs if a.class_id in mine]

    skills = (db.query(SkillUnlock).filter(SkillUnlock.user_id == uid)
                .order_by(SkillUnlock.last_at.desc()).limit(60).all())

    return {
        "student": {"user_id": u.id, "name": u.name,
                    "student_code": (code[0] if code else "") or "",
                    "class_login": (u.kind or "") == "classcode"},
        "classes": [{"id": k.id, "name": k.name} for k in classes],
        **_attendance_totals(db, uid),
        "lessons_completed": done,
        "learnt": [{"skill": s.label, "times": s.times or 1} for s in skills],
        "searched": [{"text": r.text, "kind": r.kind,
                      "subject": r.subject or "",
                      "at": r.created_at.isoformat() if r.created_at else ""}
                     for r in asked],
        "exams": [{"track": q.track_slug, "score": q.score, "total": q.total,
                   "passed": bool(q.passed),
                   "at": q.created_at.isoformat() if q.created_at else ""}
                  for q in quizzes],
        "handed_in": [{"assignment_id": a.id, "title": a.title,
                       "subject": a.subject or "",
                       "reviewed": bool(s.reviewed_at),
                       "feedback": s.feedback or "",
                       "at": s.updated_at.isoformat() if s.updated_at else ""}
                      for s, a in subs],
    }


@app.get("/api/teacher/student-by-code")
def teacher_student_by_code(code: str, user: User = Depends(teacher_user),
                            db: Session = Depends(get_db)):
    """Look a learner up by the school's own id for them.

    Searched only inside the classrooms this member of staff teaches. A code
    that exists elsewhere in the school comes back as "not found" and not as
    "not allowed" — telling a teacher that a code is real but off limits is
    still telling them something about a child they have no business with.
    """
    code = (code or "").strip()
    if len(code) < 1:
        raise HTTPException(400, "Type a student id")
    mine = _my_class_ids(db, user)
    q = db.query(RosterName).filter(
        func.upper(RosterName.student_code) == code.upper(),
        RosterName.claimed_by != 0)
    if mine is not None:
        if not mine:
            raise HTTPException(404, "No learner of yours has that id")
        q = q.filter(RosterName.class_id.in_(list(mine)))
    r = q.first()
    if not r:
        raise HTTPException(404, "No learner of yours has that id")
    return teacher_student(r.claimed_by, user, db)


class CodeIn(BaseModel):
    code: str = Field(min_length=3, max_length=16)


BOARD_TOKEN_HOURS = 12


def _board_token(slot, k):
    """What a subject code is worth at a board, and no more.

    A teacher joins the classroom with their code — that is the rule the
    school was given, and typing an email and a password on a television in
    front of thirty children is not a thing anybody does twice.

    The obvious implementation is to mint a normal session for the teacher who
    holds the slot. That hands out an account. The code is written on a board,
    read aloud, passed down a row; whoever types it would get the register,
    the marks, every subject's discussion and the school's fees.

    So the code buys one capability instead of an identity: put a lesson taught
    at this board into THIS class under THIS subject. Nothing else. A token
    that names a class and a subject and can be used for exactly one route.

    It expires in half a day, because a board is a shared device and a
    classroom is empty by evening — and it is rotatable already, since a
    subject code can be reissued whenever it travels.

    A pupil who types the code can therefore save a lesson into their own
    subject's material, which is untidy and which a teacher can delete. They
    cannot read anything about anybody.
    """
    payload = {
        "kind": "board",
        "slot": slot.id,
        "cls": k.id,
        "subject": slot.subject or "",
        "teacher": slot.teacher_id or 0,
        "exp": now() + dt.timedelta(hours=BOARD_TOKEN_HOURS),
        "iat": now(),
    }
    return jwt.encode(payload, JWT_SECRET, algorithm="HS256")


def _board_grant(db, token):
    """Read a board token back, or None. Never raises into a request."""
    if not token:
        return None
    try:
        p = jwt.decode(token, JWT_SECRET, algorithms=["HS256"])
    except jwt.PyJWTError:
        return None
    if p.get("kind") != "board":
        return None
    slot = db.get(SubjectSlot, int(p.get("slot") or 0))
    if not slot or slot.class_id != int(p.get("cls") or 0):
        return None
    # The code may have been rotated since this token was minted, which is how
    # a school takes a leaked one out of circulation. A token outliving the
    # code it came from would make rotation do nothing.
    if (slot.subject or "") != (p.get("subject") or ""):
        return None
    return {"class_id": slot.class_id, "subject": slot.subject or "",
            "teacher_id": slot.teacher_id or 0, "slot_id": slot.id}


@app.post("/api/craxlearn/room")
def craxlearn_room(body: CodeIn, request: Request,
                   db: Session = Depends(get_db)):
    """Which classroom a code names. Opens a room; signs nobody in.

    The board at the front of a room needs to know where it is standing —
    which class, and which subject — so that a lesson taught on it is filed
    where the class will look for it. Two codes name that:

        VP-XXXXXX   a class     ->  the room, and the subjects taught in it
        T-XXXX      a subject   ->  the room AND the subject

    **It deliberately does not sign anybody in.** A subject code redeemed at
    /api/class/join grants teacher access, and doing the same here was the
    obvious build: the teacher types their code on the board and is in. On a
    shared screen at the front of a classroom that is a session handed to
    whoever reads the code off the board — which is every child in the room.
    A code is fine for saying WHICH lesson this is. It is not enough to say
    WHO is teaching it, on a device thirty people are looking at.

    So this answers "where am I", the board remembers it, and the identity
    still comes from a real sign-in. If you would rather the code signed a
    teacher in, that is a decision to take deliberately and not a line to
    slip into a helper.

    Rate-limited like every other code lookup: this returns a class's name
    and its subjects, so guessing at it must cost the same as guessing at the
    register.
    """
    _code_guard(request)
    raw = body.code.strip()
    code = raw.upper()

    slot = (db.query(SubjectSlot)
              .filter(func.upper(SubjectSlot.code) == code).first())
    if slot:
        k = db.get(Klass, slot.class_id)
        if not k:
            _code_missed(request)
            raise HTTPException(404, "That subject's class no longer exists")
        who = db.get(User, slot.teacher_id) if slot.teacher_id else None
        return {"kind": "subject", "class_id": k.id, "class_name": k.name,
                "school": k.school or "", "subject": slot.subject or "",
                "teacher": (who.name if who else ""),
                "archived": bool(k.archived_at),
                # The board's whole entitlement, in one short-lived token.
                "board_token": _board_token(slot, k)}

    k = db.query(Klass).filter(func.upper(Klass.join_code) == code).first()
    if not k:
        _code_missed(request)
        raise HTTPException(404, "No class or subject has that code")
    # The class code is held by every child in the class, so this answers with
    # the room and nothing about the staff who teach in it. The first version
    # returned the subject list and each subject's teacher — which is a
    # timetable and a staff list handed to anybody holding a code that is, by
    # design, passed around a classroom. A board needs to know which room it
    # is in; it does not need to be told who works there.
    return {"kind": "class", "class_id": k.id, "class_name": k.name,
            "school": k.school or "", "archived": bool(k.archived_at)}


@app.post("/api/craxlearn/code")
def craxlearn_code(body: CodeIn, request: Request,
                   db: Session = Depends(get_db)):
    """Step one of signing in with nothing: which class is this, and who is free?

    Unauthenticated, because the whole point is that there is no account yet.
    It returns names and no other detail — no email, no school address, no
    count of anybody's work — so a guessed code leaks a class's first names
    and nothing else. That is the cost of a login a nine-year-old can do,
    and it is why the code is per-class and rotatable.

    **Every name on the register, not only the unclaimed ones.** This used to
    return `claimed_by == 0` and nothing else, which meant a child who signed
    out could never sign back in: their name had gone from the list, the
    account behind it has a synthetic email nobody can receive and a random
    password nobody knows, and so signing out DESTROYED the account. The class
    told them "everybody on this register has already signed in" — which was
    true, and useless.

    The register is who is in the class. Whether somebody has signed in before
    is not a reason to hide them from a list of who they are.
    """
    _code_guard(request)
    code = body.code.strip().upper()
    k = db.query(Klass).filter(func.upper(Klass.join_code) == code).first()
    if not k:
        _code_missed(request)
        raise HTTPException(404, "No class has that code")
    names = (db.query(RosterName)
               .filter(RosterName.class_id == k.id,
                       RosterName.removed_at.is_(None))
               .order_by(RosterName.name.asc()).all())
    # An archived class still lets its own children back in to their work —
    # it only stops taking new ones. A year ending is not a reason to lock
    # somebody out of what they wrote.
    if k.archived_at:
        names = [r for r in names if r.claimed_by]
    return {"class_id": k.id, "class_name": k.name, "school": k.school or "",
            "archived": bool(k.archived_at),
            "names": [{"id": r.id, "name": r.name,
                       # "You have been here before", so the page can say
                       # "welcome back" rather than looking like a fresh claim.
                       "taken": bool(r.claimed_by)} for r in names],
            "roster_ready": bool(names)}


@app.post("/api/auth/code")
def sign_in_with_code(body: CodeIn, response: Response, request: Request,
                      db: Session = Depends(get_db)):
    """Signing in with a code. Two kinds of code arrive here.

    **Ten digits** — the school administrator's. One code, one person, handed
    over once, carrying the name the platform admin issued it in, and never
    written on anything a room can read.

    **T-XXXX** — a subject's. It signs in the teacher the school put on that
    subject, and it is the SAME code that opens that subject on a classroom
    board. One code, both jobs, which is what a teacher can actually hold.

    The second one is a real trade and it is made deliberately. The code is
    chalked up and read by a room, so whoever has it can become that teacher.
    Set against that: a teacher who is given only a code, refused here, and
    told to use an email and password nobody has issued her has no way in at
    all, and goes round that loop instead of teaching. The mitigation is that
    the code rotates — "New code" on the subject's row — and that email and
    password remain available and remain stronger.

    Rate-limited on the same counters as the register, because guessing at
    this is guessing at a way into a school.
    """
    _code_guard(request)
    code = body.code.strip().upper()

    # A school admin's code: ten digits, and it carries its own identity.
    hc = (db.query(TeacherCode)
            .filter(func.lower(TeacherCode.code) == code.lower(),
                    TeacherCode.is_head == True,               # noqa: E712
                    TeacherCode.active == True).first())       # noqa: E712
    if hc:
        u = db.get(User, hc.claimed_by) if hc.claimed_by else None
        if u is not None and u.is_active:
            # Back to the same administrator. A code that made a second
            # account every time it was used would leave a school with a
            # drawer full of half-used identities and no idea which held
            # what — the register taught this lesson once already.
            _grant_teacher(db, u, hc.school, hc.school_id, "head")
            set_session(response, u, db)
            return {"ok": True, "kind": "school admin", "name": u.name,
                    "school": hc.school or "", "returning": True}

        if not (hc.label or "").strip():
            # No name on the code and no account behind it: there is nothing
            # to call the administrator this would create. Refused rather
            # than inventing somebody, and the platform admin can reissue the
            # code with a name against it.
            raise HTTPException(
                409, "That code has no name on it yet. Ask for a code issued "
                     "in your name — an account has to be called something.")

        u = User(
            name=hc.label.strip()[:120],
            # Synthetic and unroutable, exactly as a pupil's class-code
            # account is: nothing is ever sent here and it cannot collide
            # with a real address. The code is the credential.
            email=f"head{hc.id}.{secrets.token_hex(4)}@schoolcode.invalid",
            password_hash=hash_pw(secrets.token_urlsafe(24)),
            kind="schoolcode", is_active=True, email_verified=False)
        db.add(u)
        db.commit()
        db.refresh(u)
        hc.claimed_by = u.id
        db.commit()
        _grant_teacher(db, u, hc.school, hc.school_id, "head")
        set_session(response, u, db)
        return {"ok": True, "kind": "school admin", "name": u.name,
                "school": hc.school or "", "returning": False}

    slot = (db.query(SubjectSlot)
              .filter(func.upper(SubjectSlot.code) == code).first())
    if not slot:
        _code_missed(request)
        raise HTTPException(
            404, "No subject or school has that code. A pupil's class code "
                 "goes in the class sign-in, not here.")

    # A SUBJECT code signs its teacher in. One code, both jobs.
    #
    # This was refused for a while and the reasoning still stands on its own
    # terms: the code is read off a classroom board, chalked up, passed down
    # a row — by design, because a board has to be told which room it is in.
    # Whoever holds it can become that teacher, and the session is not scoped
    # to the classroom; it is the account, with every class and register on it.
    #
    # It is restored because the alternative was worse in practice, which is
    # the test that counts. A teacher held one code. She typed it here, was
    # refused and told to sign in with an email and password she had never
    # been given, and the only way out was for somebody else to open the
    # school screen and issue one. She went round that loop instead of
    # teaching. A safe door nobody can open is not a safe door; it is a wall
    # with a sign on it.
    #
    # Two things keep the risk answerable rather than theoretical:
    #
    #   * the code rotates. "New code" on the subject's row issues a fresh
    #     one and the old one stops working, which is the move when a code
    #     has been up on a board all term.
    #   * email and password still exist and are still stronger. A school
    #     that wants them uses Fix sign-in and stops handing the code out.
    #
    # An UNCLAIMED subject is refused rather than inventing somebody. There
    # is no name to create an account under, and a code that made a new
    # half-identity every time it was typed is the mistake the register
    # already taught once.
    holder = db.get(User, slot.teacher_id) if slot.teacher_id else None
    if holder is not None and holder.is_active:
        k = db.get(Klass, slot.class_id)
        set_session(response, holder, db)
        return {"ok": True, "kind": "teacher", "name": holder.name,
                "subject": slot.subject or "",
                "class": (k.name if k else ""),
                "school": (k.school if k and k.school else ""),
                "returning": True}

    raise HTTPException(
        409, "No teacher is on that subject yet. Ask your school office to "
             "put you on it — then this code signs you in, and it opens the "
             "same subject on a classroom board.")


class ClaimIn(BaseModel):
    code: str = Field(min_length=3, max_length=16)
    roster_id: int


@app.post("/api/craxlearn/claim")
def craxlearn_claim(claim: ClaimIn, response: Response, request: Request,
                    db: Session = Depends(get_db)):
    """Step two: take that name, and be signed in.

    Creates a real User row so that everything downstream — submissions,
    the review queue, the activity record — works exactly as it does for
    anybody else. What it does not create is a way in from anywhere except
    this class code: the email is synthetic and unroutable, and the password
    hash is random and known to nobody, so there is no credential to phish,
    reuse or leak.

    kind="classcode" is what closes the job half permanently for this
    account. There is no adult behind it who agreed to anything, and no
    date of birth that could ever open it.

    **Tapping a name that has been taken signs you back into it.** It used to
    answer 409 "somebody has already taken that name", and for the person
    whose name it was that was a locked door with no other way round: the
    account has an unroutable email and a password hash of random bytes, so
    there is no reset, no recovery and no second route. Signing out was
    permanent.

    What this costs, stated plainly: the class code is the class's
    credential, and anybody holding it can now sign in as anybody on that
    register — not only as a name nobody has taken yet. That was already
    three-quarters true (any unclaimed name was open to any code holder); it
    is now true of the whole list. The lever against it is the code itself,
    which is per-class and can be rotated the moment it travels.
    """
    _code_guard(request)
    code = claim.code.strip().upper()
    k = db.query(Klass).filter(func.upper(Klass.join_code) == code).first()
    if not k:
        _code_missed(request)
        raise HTTPException(404, "No class has that code")
    r = db.get(RosterName, claim.roster_id)
    if not r or r.class_id != k.id:
        raise HTTPException(404, "That name is not on this class register")
    if r.removed_at:
        raise HTTPException(404, "That name is no longer on this register. "
                                 "Ask your teacher.")
    # A class that has been put away takes nobody new. The children already
    # on it keep coming back — that is the branch below.
    if k.archived_at and not r.claimed_by:
        raise HTTPException(409, "This class has finished for the year. Ask "
                                 "your teacher for your new class code.")

    if r.claimed_by:
        back = db.get(User, r.claimed_by)
        # A row pointing at a user who is gone is a name that is free again,
        # not a dead end. Fall through and make a fresh account for it.
        if back is not None and back.is_active:
            # Membership is re-checked rather than assumed: a class rebuilt
            # around an existing roster row would otherwise sign somebody in
            # with no class attached to them.
            if not (db.query(ClassMember)
                      .filter(ClassMember.class_id == k.id,
                              ClassMember.user_id == back.id).first()):
                db.add(ClassMember(class_id=k.id, user_id=back.id))
                db.commit()
            set_session(response, back, db)
            return {"ok": True, "name": back.name, "class_name": k.name,
                    "school": k.school or "", "returning": True}
        r.claimed_by = 0

    u = User(name=r.name[:120],
             # Synthetic and unroutable by design: nothing is ever sent
             # here, and it cannot collide with a real address.
             email=f"roster{r.id}.{secrets.token_hex(4)}@classcode.invalid",
             password_hash=hash_pw(secrets.token_urlsafe(24)),
             kind="classcode", is_active=True, email_verified=False)
    db.add(u)
    db.commit()
    db.refresh(u)

    r.claimed_by = u.id
    r.claimed_at = now()
    db.add(ClassMember(class_id=k.id, user_id=u.id))
    db.commit()

    set_session(response, u, db)
    return {"ok": True, "name": u.name, "class_name": k.name,
            "school": k.school or "", "returning": False}


# --------------------------------------------------------------------------
# Reference material a class can read
# --------------------------------------------------------------------------
MATERIAL_MAX = 12_000_000          # 12 MB, which is a slide deck, not a film
MATERIAL_MIMES = {
    "application/pdf": "pdf",
    "application/vnd.openxmlformats-officedocument.presentationml.presentation": "pptx",
    "application/vnd.ms-powerpoint": "ppt",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
    "application/msword": "doc",
    "text/plain": "txt",
    "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp",
}


def _folder_of(name, fallback=""):
    """A folder name, or the subject's top level.

    Trimmed, capped, and stripped of the slashes and dots that make a name
    look like a path — this is a label on a drawer, not a filesystem, and a
    teacher typing "Term 2/Week 3" should get one drawer called that rather
    than something that reads as a directory somebody can climb out of.
    """
    n = " ".join(str(name or "").split())
    n = n.replace("/", " ").replace("\\", " ").replace("..", ".")
    n = " ".join(n.split())[:80].strip(" .")
    return n or fallback


def _material_json(m, with_url=True, by=""):
    """One piece of material, as a class sees it.

    `by` is passed in rather than looked up here: a list of two hundred
    would otherwise be two hundred queries for a name, and the caller
    already has to touch the user table once to get them all.
    """
    kind = "lesson" if (m.body or "") else ("link" if m.url else "file")
    figs = []
    if kind == "lesson" and (m.figures or ""):
        try:
            figs = json.loads(m.figures)
            if not isinstance(figs, list):
                figs = []
        except Exception:
            # A row we cannot read is a lesson without its pictures, not a
            # broken page. The words are the part that must always arrive.
            figs = []
    d = {"id": m.id, "title": m.title, "note": m.note or "",
         "subject": m.subject or "", "kind": kind,
         # Which drawer it is in. Empty means the subject's top level.
         "folder": getattr(m, "folder", "") or "",
         "body": (m.body or "") if kind == "lesson" else "",
         "figures": figs,
         "file_name": m.file_name or "", "size": m.size or 0,
         "mime": m.mime or "",
         # Who put it there. A class given a reading list by nobody in
         # particular does not know which teacher to ask about it.
         "by": by or "",
         "at": m.created_at.isoformat() if m.created_at else ""}
    if with_url and m.url:
        d["url"] = m.url
    return d


class LinkIn(BaseModel):
    title: str = Field(min_length=2, max_length=240)
    url: str = Field(min_length=4, max_length=2000)
    note: str = Field(default="", max_length=2000)
    subject: str = Field(default="", max_length=80)
    folder: str = Field(default="", max_length=80)


@app.post("/api/teacher/class/{cid}/material/link")
def add_material_link(cid: int, body: LinkIn,
                      user: User = Depends(teaching_user),
                      db: Session = Depends(get_db)):
    """Put a reference link in front of a class."""
    _own_class(db, cid, user)
    # Which subject, checked rather than typed. Filing a lesson through the
    # board has always gone through this; material did not, so the Chemistry
    # teacher could put a chapter on the Physics page — same class, somebody
    # else's subject, and a role check alone will never catch it.
    subject = _board_subject(db, cid, user, body.subject)
    url = body.url.strip()
    if not url.lower().startswith(("http://", "https://")):
        # A link that is not a link opens nothing and is reported by the
        # student as "it does not work", which costs a lesson to diagnose.
        raise HTTPException(400, "The link must start with http:// or https://")
    m = Material(class_id=cid, teacher_id=user.id,
                 subject=subject, folder=_folder_of(body.folder),
                 title=body.title.strip()[:240], url=url[:2000],
                 note=body.note.strip()[:2000])
    db.add(m)
    db.commit()
    db.refresh(m)
    return {"ok": True, "material": _material_json(m, by=user.name)}


@app.post("/api/teacher/class/{cid}/material/file")
async def add_material_file(cid: int, file: UploadFile = File(...),
                            title: str = Form(default=""),
                            note: str = Form(default=""),
                            folder: str = Form(default=""),
                            subject: str = Form(default=""),
                            user: User = Depends(teaching_user),
                            db: Session = Depends(get_db)):
    """Upload a PDF, a slide deck or a document for one class.

    Stored in the row rather than on disk: the container's filesystem does
    not survive a deploy, and a study pack that vanishes every time the site
    ships is worse than no study pack.
    """
    _own_class(db, cid, user)
    subject_name = _board_subject(db, cid, user, subject or "")
    raw = await file.read()
    if not raw:
        raise HTTPException(400, "That file is empty")
    if len(raw) > MATERIAL_MAX:
        raise HTTPException(
            400, f"That file is {len(raw) // 1_000_000} MB. The limit is "
                 f"{MATERIAL_MAX // 1_000_000} MB — split it, or link to it "
                 f"instead.")
    mime = (file.content_type or "").lower().split(";")[0].strip()
    if mime not in MATERIAL_MIMES:
        raise HTTPException(
            400, "Upload a PDF, a PowerPoint, a Word document, a text file "
                 "or an image.")
    m = Material(class_id=cid, teacher_id=user.id,
                 subject=subject_name, folder=_folder_of(folder),
                 title=((title or "").strip()
                        or (file.filename or "Material"))[:240],
                 note=(note or "").strip()[:2000],
                 file_data=base64.b64encode(raw).decode(),
                 file_name=(file.filename or "material")[:160],
                 mime=mime, size=len(raw))
    db.add(m)
    db.commit()
    db.refresh(m)
    return {"ok": True, "material": _material_json(m, by=user.name)}


class PostIn(BaseModel):
    body: str = Field(min_length=1, max_length=4000)
    subject: str = Field(default="", max_length=80)
    parent_id: int = 0


@app.get("/api/class/{cid}/discussion")
def class_discussion(cid: int, subject: str = "",
                     user: User = Depends(current_user),
                     db: Session = Depends(get_db)):
    """Questions asked in this class, newest first, each with its replies.

    Open to everybody in the class, students included — a discussion only one
    side can start is a noticeboard.
    """
    _in_class_or_teaching(db, cid, user)
    q = db.query(ClassPost).filter(ClassPost.class_id == cid)

    # A teacher reads their own subjects and no others. Applied to the query
    # rather than to the page, so a thread another teacher's class is having
    # is not sent to the browser and then hidden by a screen.
    scope = _discussion_scope(db, cid, user)
    if scope is not None:
        want_one = subject.strip().lower()
        if want_one and want_one not in scope:
            raise HTTPException(
                403, "You do not teach that subject in this class. Its "
                     "discussion belongs to the teacher who does.")
        # A message with no subject is the class talking to itself rather than
        # a lesson happening, so it stays readable by everyone who teaches
        # here. Without this a teacher lost sight of their own class-level
        # thread the moment they were given a subject — which is how a rule
        # meant to separate two subjects ended up hiding the class.
        keep = func.lower(func.coalesce(ClassPost.subject, "")) == ""
        if scope:
            keep = or_(keep,
                       func.lower(func.coalesce(ClassPost.subject, ""))
                       .in_(list(scope)))
        q = q.filter(keep)

    if subject.strip():
        # Filtered here rather than in the page. The subject screen was
        # fetching every thread in the class and dropping most of them, which
        # works until a class has a term of questions in it — and it also
        # meant the Physics page briefly held Maths questions in memory.
        want = subject.strip().lower()
        q = q.filter(func.lower(func.coalesce(ClassPost.subject, "")) == want)
    rows = q.order_by(ClassPost.created_at.desc()).limit(400).all()
    who = {u.id: (u.name or "Someone") for u in db.query(User).filter(
        User.id.in_([r.user_id for r in rows] or [0])).all()}

    def one(r):
        return {"id": r.id, "body": r.body, "subject": r.subject or "",
                "who": who.get(r.user_id, "Someone"), "user_id": r.user_id,
                "from_staff": bool(r.from_staff), "mine": r.user_id == user.id,
                "at": r.created_at.isoformat() if r.created_at else "",
                "replies": []}

    threads, by_id = [], {}
    for r in rows:
        if not r.parent_id:
            d = one(r)
            by_id[r.id] = d
            threads.append(d)
    for r in rows:
        if r.parent_id and r.parent_id in by_id:
            by_id[r.parent_id]["replies"].append(one(r))
    # Replies read oldest first: a thread is a conversation, and a
    # conversation read backwards is not one.
    for t in threads:
        t["replies"].sort(key=lambda x: x["at"])
    return {"threads": threads, "can_post": True}


@app.post("/api/class/{cid}/discussion")
def class_discussion_post(cid: int, body: PostIn,
                          user: User = Depends(current_user),
                          db: Session = Depends(get_db)):
    """Ask something, or answer somebody."""
    _in_class_or_teaching(db, cid, user)
    parent = 0
    if body.parent_id:
        p = db.get(ClassPost, body.parent_id)
        if not p or p.class_id != cid:
            raise HTTPException(404, "That question is not in this class")
        # One level deep. A reply to a reply is a forum, and a forum needs
        # somebody to moderate it.
        parent = p.parent_id or p.id
        # A reply belongs to the same subject as the question it answers.
        # Without this an answer typed on the Physics page carried no subject
        # and vanished from it — the thread split in half, with the question
        # under Physics and the answer nowhere.
        root = db.get(ClassPost, parent)
        if root is not None and not (body.subject or "").strip():
            body.subject = root.subject or ""
    # Answering is the same rule as reading. Checked after the parent has been
    # resolved, because a reply inherits its question's subject — so the check
    # has to run against the subject the message will actually be filed under,
    # not the one the form happened to send.
    scope = _discussion_scope(db, cid, user)
    if scope is not None:
        want = (body.subject or "").strip().lower()
        # Only a message filed UNDER a subject is restricted. One with no
        # subject is addressed to the class, and refusing those stopped
        # teachers posting to their own classes at all — the check fired on
        # an empty string that was never in anybody's subject list.
        if want and want not in scope:
            raise HTTPException(
                403, "You do not teach that subject in this class, so this "
                     "thread is not yours to answer.")

    staff = _my_subjects(db, cid, user)
    row = ClassPost(class_id=cid, user_id=user.id, parent_id=parent,
                    subject=body.subject.strip()[:80],
                    body=body.body.strip()[:4000],
                    from_staff=(staff is None or bool(staff)))
    db.add(row)
    db.commit()
    db.refresh(row)
    return {"ok": True, "id": row.id}


@app.delete("/api/class/{cid}/discussion/{pid}")
def class_discussion_delete(cid: int, pid: int,
                            user: User = Depends(current_user),
                            db: Session = Depends(get_db)):
    """Your own, or anybody's if you teach this class.

    A teacher needs to be able to take something down without waiting for the
    child who wrote it, and a child needs to be able to unsay their own thing.
    """
    _in_class_or_teaching(db, cid, user)
    row = db.get(ClassPost, pid)
    if not row or row.class_id != cid:
        raise HTTPException(404, "Not found")
    # Your own always. Somebody else's only if you teach it.
    #
    # NOT _discussion_scope: that answers "what may you read", and for a
    # child in the class the answer is "everything their class is taught".
    # Using it here handed every pupil the power to delete their classmates'
    # messages — a rule about which teacher owns a thread, turned into a
    # moderation right for thirty children, by reusing one helper for two
    # different questions.
    #
    # _my_subjects answers the other question: None for the head and the
    # office, the subjects held for a teacher, and an empty set for a pupil.
    # Taking down somebody else's message belongs to the teacher of that
    # subject, and to nobody else.
    #
    # _my_subjects answers None for the head and the office, meaning "reads
    # everything" — and that was being spent here as "may delete anything".
    # Reading a class's discussion is oversight, which a head is owed;
    # removing a child's message from a lesson they do not teach is not the
    # same act and was never asked for. A head who genuinely teaches the
    # subject still holds it as a teacher, through the slot, and that is the
    # right that applies.
    #
    # Platform admins keep it: that is the operator of the service, needed
    # for a takedown nobody at the school will action.
    held = _my_subjects(db, cid, user)
    if row.user_id != user.id:
        here = (row.subject or "").strip().lower()
        mine = {str(s).strip().lower() for s in (held or [])}
        may = user.is_admin or (bool(mine) and (not here or here in mine))
        if not may:
            raise HTTPException(
                403, "That is somebody else's message. The teacher of that "
                     "subject can take it down, and so can whoever wrote it.")
    # A question takes its replies with it, or the class is left answering
    # something nobody can see.
    db.query(ClassPost).filter(ClassPost.class_id == cid,
                               ClassPost.parent_id == row.id).delete(
                                   synchronize_session=False)
    db.delete(row)
    db.commit()
    return {"ok": True}


@app.get("/api/class/{cid}/subjects")
def class_subjects(cid: int, user: User = Depends(current_user),
                   db: Session = Depends(get_db)):
    """The subjects in this class, each with the teacher who takes it.

    A learner's class screen listed assignments across every subject in one
    stream, which is not how anybody thinks about school. They think "what did
    we do in Physics" — and the teacher's name matters, because that is who
    they will ask on Monday.

    A subject with no teacher yet is still listed. Leaving it out would hide
    from a class that the subject exists and nobody has been put on it, which
    is a thing their parents would rather know than not.
    """
    _in_class_or_teaching(db, cid, user)
    k = db.get(Klass, cid)
    slots = (db.query(SubjectSlot).filter(SubjectSlot.class_id == cid)
               .order_by(SubjectSlot.subject.asc()).all())
    who = {u.id: (u.name or "") for u in db.query(User).filter(
        User.id.in_([s.teacher_id for s in slots if s.teacher_id] or [0])).all()}

    mats = db.query(Material).filter(Material.class_id == cid).all()
    asgs = db.query(Assignment).filter(Assignment.class_id == cid).all()
    posts = db.query(ClassPost).filter(ClassPost.class_id == cid,
                                       ClassPost.parent_id == 0).all()

    def count_for(rows, subject):
        low = (subject or "").strip().lower()
        return sum(1 for r in rows
                   if (getattr(r, "subject", "") or "").strip().lower() == low)

    out = []
    for sl in slots:
        out.append({
            "subject": sl.subject or "",
            "teacher": who.get(sl.teacher_id, ""),
            "teacher_id": sl.teacher_id or 0,
            "materials": count_for(mats, sl.subject),
            "assignments": count_for(asgs, sl.subject),
            "questions": count_for(posts, sl.subject),
        })

    # Anything filed under a subject with no slot — usually because the class
    # was taught something before the timetable caught up. Showing it under a
    # heading nobody owns is better than not showing it at all.
    named = {(sl.subject or "").strip().lower() for sl in slots}
    extra = {}
    for row in list(mats) + list(asgs):
        sub = (getattr(row, "subject", "") or "").strip()
        if sub and sub.lower() not in named:
            extra.setdefault(sub, 0)
            extra[sub] += 1
    for sub in sorted(extra):
        out.append({"subject": sub, "teacher": "", "teacher_id": 0,
                    "materials": count_for(mats, sub),
                    "assignments": count_for(asgs, sub),
                    "questions": count_for(posts, sub)})

    return {"class_id": cid, "class_name": (k.name if k else ""),
            "subjects": out}


@app.get("/api/class/{cid}/materials")
def class_materials(cid: int, user: User = Depends(current_user),
                    db: Session = Depends(get_db)):
    """Everything the class has been given to read.

    Open to the class and to its teachers, and to nobody else — the same
    membership test the assignments use, because material is exactly as
    private as the work that references it.
    """
    _in_class_or_teaching(db, cid, user)
    rows = (db.query(Material).filter(Material.class_id == cid)
              .order_by(Material.created_at.desc()).limit(200).all())
    # One query for every teacher named, rather than one per row.
    ids = {m.teacher_id for m in rows if m.teacher_id}
    names = {u.id: u.name for u in db.query(User).filter(User.id.in_(ids)).all()} \
        if ids else {}
    return {"materials": [_material_json(m, by=names.get(m.teacher_id, ""))
                          for m in rows]}


@app.get("/api/material/{mid}/file")
def material_file(request: Request, mid: int,
                  user: User = Depends(_reader_or_board),
                  db: Session = Depends(get_db)):
    """Download one file, if you are in the class it belongs to.

    Or if you are the BOARD standing in that class. This wanted a session, so
    a teacher who opened a saved worksheet from the board — the tool whose
    whole job is putting saved things back on the screen — got turned away
    by the one route the ⧉ link points at. The list of files worked; opening
    one did not.

    A board is held to the class its token names, which is stricter than a
    signed-in teacher rather than looser: it can reach that class's material
    and nothing else, whatever id is typed into the URL.
    """
    m = db.get(Material, mid)
    if not m or not m.file_data:
        raise HTTPException(404, "Not found")
    if user is None:
        grant = _board_grant(db, request.headers.get("X-Board-Token", ""))
        if not grant or int(grant.get("class_id") or 0) != int(m.class_id or 0):
            raise HTTPException(403, "That is not this class's material.")
    else:
        _in_class_or_teaching(db, m.class_id, user)
    try:
        raw = base64.b64decode(m.file_data)
    except Exception:
        raise HTTPException(500, "That file is stored damaged")
    return Response(
        content=raw, media_type=m.mime or "application/octet-stream",
        headers=_disposition((m.file_name or "material")[:80], "inline"))


@app.delete("/api/teacher/material/{mid}")
def drop_material(mid: int, user: User = Depends(teacher_user),
                  db: Session = Depends(get_db)):
    m = db.get(Material, mid)
    if not m:
        raise HTTPException(404, "Not found")
    _own_class(db, m.class_id, user)
    db.delete(m)
    db.commit()
    return {"ok": True}


# --------------------------------------------------------------------------
# A private line to the teacher, and only to the teacher.
#
# The group thread — the classroom discussion, one per subject — already
# exists and is where a class talks in front of its teacher. What did not
# exist is the quiet question: a child who will not put their hand up, and
# will not type it under their own name in front of thirty classmates.
#
# The rule is deliberately not symmetric, and that is why this is a feature
# rather than a messaging system:
#
#   a child   may write to the teacher of a subject their class is taught,
#             and to nobody else. Not to another child.
#   a teacher may write to any child on the register of a class and subject
#             they hold.
#
# A school that hands thirty children a private channel to each other has
# taken on moderating it, in the evenings, in a product with no moderators.
# The thing children actually cannot do today is ask their teacher something
# without an audience, and that is what this is.

class DMIn(BaseModel):
    class_id: int
    subject: str = Field(default="", max_length=80)
    to_id: int = 0            # a teacher naming which child; ignored for a child
    body: str = Field(min_length=1, max_length=4000)


def _dm_pair(db, cid, subject, user, to_id=0):
    """Resolve one conversation, or refuse.

    Returns (student_id, teacher_id, subject, i_am_teacher). Every refusal in
    the rule above happens here, and nothing downstream re-checks — so nothing
    downstream can disagree with it.
    """
    k = db.get(Klass, cid)
    if not k:
        raise HTTPException(404, "Class not found")
    want = (subject or "").strip()[:80]
    slots = db.query(SubjectSlot).filter(SubjectSlot.class_id == cid).all()
    match = [x for x in slots if (x.subject or "").lower() == want.lower()]
    if not match:
        raise HTTPException(404, "That class has no such subject")
    slot = match[0]

    mine = db.query(SubjectSlot).filter(
        SubjectSlot.class_id == cid,
        SubjectSlot.teacher_id == user.id).all()
    teaching_here = any((x.subject or "").lower() == want.lower() for x in mine)

    if teaching_here or user.is_admin:
        # A teacher writing to one child. The child has to be ON the register
        # of this class: an id typed into a URL must not reach somebody
        # else's pupil.
        if not to_id:
            raise HTTPException(400, "Say which student.")
        member = (db.query(ClassMember)
                    .filter(ClassMember.class_id == cid,
                            ClassMember.user_id == to_id).first())
        if not member:
            raise HTTPException(404, "No student of this class has that id")
        return to_id, (slot.teacher_id or user.id), slot.subject or want, True

    member = (db.query(ClassMember)
                .filter(ClassMember.class_id == cid,
                        ClassMember.user_id == user.id).first())
    if not member:
        raise HTTPException(403, "You are not in this class")
    if not slot.teacher_id:
        raise HTTPException(
            409, "No teacher is on that subject yet, so there is nobody to "
                 "write to. Ask the school office.")
    # A child does not choose who they are writing to. Whatever to_id says is
    # thrown away here: the recipient is the teacher of the subject, and that
    # is the only person a child can reach.
    return user.id, slot.teacher_id, slot.subject or want, False


@app.get("/api/messages")
def my_messages(user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """Every private conversation this account is part of, newest first.

    The home screen's inbox. A teacher sees one row per child who has written
    to them; a child sees one row per subject.
    """
    rows = (db.query(DirectMessage)
              .filter(or_(DirectMessage.student_id == user.id,
                          DirectMessage.teacher_id == user.id))
              .order_by(DirectMessage.created_at.desc()).limit(400).all())

    threads, order = {}, []
    for m in rows:
        key = (m.class_id, (m.subject or "").lower(),
               m.student_id, m.teacher_id)
        if key not in threads:
            threads[key] = {"class_id": m.class_id, "subject": m.subject or "",
                            "student_id": m.student_id,
                            "teacher_id": m.teacher_id,
                            "last": (m.body or "")[:160], "unread": 0,
                            "at": m.created_at.isoformat() if m.created_at else ""}
            order.append(key)
        mine = bool(m.from_teacher) == (m.teacher_id == user.id)
        if not mine and m.read_at is None:
            threads[key]["unread"] += 1

    ids, cids = set(), set()
    for t in threads.values():
        ids.add(t["student_id"])
        ids.add(t["teacher_id"])
        cids.add(t["class_id"])
    names = {u.id: u.name for u in
             db.query(User).filter(User.id.in_(ids)).all()} if ids else {}
    classes = {k.id: k.name for k in
               db.query(Klass).filter(Klass.id.in_(cids)).all()} if cids else {}

    out = []
    for key in order:
        t = threads[key]
        other = t["teacher_id"] if t["student_id"] == user.id else t["student_id"]
        t["with_id"] = other
        # The name, always. A message from an id is a message from nobody.
        t["with"] = names.get(other, "")
        t["class_name"] = classes.get(t["class_id"], "")
        t["i_am_teacher"] = t["teacher_id"] == user.id
        out.append(t)
    return {"threads": out, "unread": sum(t["unread"] for t in out)}


@app.get("/api/messages/thread")
def message_thread(class_id: int, subject: str = "", with_id: int = 0,
                   user: User = Depends(current_user),
                   db: Session = Depends(get_db)):
    """One conversation. Reading it marks the other side's messages read."""
    sid, tid, subj, am_teacher = _dm_pair(db, class_id, subject, user, with_id)
    rows = (db.query(DirectMessage)
              .filter(DirectMessage.class_id == class_id,
                      func.lower(func.coalesce(DirectMessage.subject, ""))
                      == (subj or "").lower(),
                      DirectMessage.student_id == sid,
                      DirectMessage.teacher_id == tid)
              .order_by(DirectMessage.created_at.asc()).limit(500).all())
    names = {u.id: u.name for u in
             db.query(User).filter(User.id.in_({sid, tid})).all()}
    changed = False
    for m in rows:
        if bool(m.from_teacher) != am_teacher and m.read_at is None:
            m.read_at = now()
            changed = True
    if changed:
        db.commit()
    return {"class_id": class_id, "subject": subj,
            "student": names.get(sid, ""), "teacher": names.get(tid, ""),
            "i_am_teacher": am_teacher, "with_id": sid if am_teacher else tid,
            "messages": [{"id": m.id, "body": m.body or "",
                          "from_teacher": bool(m.from_teacher),
                          "from": names.get(tid if m.from_teacher else sid, ""),
                          "mine": bool(m.from_teacher) == am_teacher,
                          "at": m.created_at.isoformat() if m.created_at else ""}
                         for m in rows]}


@app.post("/api/messages")
def send_message(body: DMIn, user: User = Depends(current_user),
                 db: Session = Depends(get_db)):
    """Write to your teacher, or to one of your students."""
    sid, tid, subj, am_teacher = _dm_pair(db, body.class_id, body.subject,
                                          user, body.to_id)
    m = DirectMessage(class_id=body.class_id, subject=subj,
                      student_id=sid, teacher_id=tid,
                      from_teacher=am_teacher,
                      body=body.body.strip()[:4000])
    db.add(m)
    db.commit()
    db.refresh(m)
    return {"ok": True, "id": m.id,
            "at": m.created_at.isoformat() if m.created_at else ""}


def _discussion_scope(db, cid, user):
    """Which subjects this person may read and answer in. None means all.

    A subject thread is the one place in a class where children talk to each
    other in front of a teacher, and it was open to every teacher of the
    class: the maths teacher could read the science thread. That is not a
    staffroom noticeboard, it is thirty children asking questions, and the
    rule the school was given is that the teacher of THAT subject answers it.

    Three answers, and the order matters:

      * a child in the class sees every subject their class is taught,
        because those are their own lessons;
      * staff see the subjects they hold here, and only those;
      * the office is staff who hold nothing, so the office sees nothing.

    That last line was the opposite until now: the head and the office read
    every thread in the school, on the reasoning that they cannot supervise
    what they cannot read. The school's own answer is that the two jobs are
    separate — an administrator runs the school, its subjects, who teaches
    what and what is announced; a subject's discussion is between a class
    and the teacher of that subject. A child asking a question in a lesson
    is not writing to the administration, and thirty children being read by
    somebody they have never been taught by is not oversight.

    A platform admin keeps it, because that is the operator of the service
    rather than anybody at the school.

    Membership is checked before the subject slots rather than after, because
    a teacher who is also enrolled somewhere must not have their own class's
    threads narrowed to the subjects they teach in it.
    """
    if user.is_admin:
        return None
    if (db.query(ClassMember)
          .filter(ClassMember.class_id == cid,
                  ClassMember.user_id == user.id).first()):
        return None
    return {(s.subject or "").strip().lower()
            for s in db.query(SubjectSlot).filter(
                SubjectSlot.class_id == cid,
                SubjectSlot.teacher_id == user.id).all()}


def _in_class_or_teaching(db, cid, user):
    """The one membership test both materials endpoints use.

    Written once because two copies of an access check drift, and the half
    that drifts is the one that lets the wrong person in.
    """
    if user.is_admin:
        return
    member = (db.query(ClassMember)
                .filter(ClassMember.class_id == cid,
                        ClassMember.user_id == user.id).first())
    if member:
        return
    k = db.get(Klass, cid)
    if k and k.teacher_id == user.id:
        return
    if db.query(SubjectSlot).filter(SubjectSlot.class_id == cid,
                                    SubjectSlot.teacher_id == user.id).first():
        return
    t = teacher_row(user, db)
    if t and t.role == "head" and k and t.school_id == k.school_id:
        return
    raise HTTPException(403, "Not in this class")


class BoardAssignIn(BaseModel):
    class_id: int
    topic: str = Field(min_length=2, max_length=200)
    title: str = Field(default="", max_length=240)
    subject: str = Field(default="", max_length=80)
    due_date: str = Field(default="", max_length=20)
    # The lesson as the board built it, so the assignment carries the
    # teaching and not only the instruction. Sent back rather than rebuilt
    # here: the teacher is looking at a specific lesson on the screen and
    # that is the one the class must get, not whatever the board would
    # produce if asked the same question again tomorrow.
    lesson: dict = {}
    task: str = Field(default="", max_length=4000)


def _lesson_to_body(lesson, task):
    """A board lesson as the text of an assignment.

    Flattened to text rather than stored as JSON because that is what
    `Assignment.body` is, what the existing student view renders, and what a
    teacher can edit afterwards. A structured copy would need a renderer on
    both sides and would stop the teacher fixing a line before setting it.
    """
    out = []
    if task:
        out.append(task.strip())
        out.append("")
    for i, st in enumerate(lesson.get("steps") or [], 1):
        text = st.get("t", "") if isinstance(st, dict) else str(st)
        if not text:
            continue
        out.append(f"{i}. {text.strip()}")
        if isinstance(st, dict) and st.get("code"):
            where = st.get("where") or ""
            out.append(f"   [{where}]" if where else "")
            out.append("   " + "\n   ".join(
                str(st["code"]).splitlines()[:20]))
        out.append("")
    if lesson.get("takeaway"):
        out.append(f"Remember: {lesson['takeaway']}")
    return "\n".join(out).strip()[:20000]


# A picture kept beside a lesson: how many, how big, and what a src may be.
# Only base64 image data. An <img src> is the one attribute on a stored page
# that a browser will go and fetch or execute for, so "it came from our own
# extractor" is not a reason to skip checking it — the lesson has been round
# a browser by the time it arrives here.
PIC_KEEP = 6
PIC_SRC_MAX = 700_000
_PIC_SRC = re.compile(r"^data:image/(?:png|jpeg|jpg|gif|webp);base64,"
                      r"[A-Za-z0-9+/=\s]+$")


def _lesson_figures(lesson):
    """The drawings and the 3D out of a lesson, as JSON to keep beside it.

    Put through the same cleaners the board's own reply goes through rather
    than stored as sent. What arrives here has been round a browser, and a
    scene is mounted by a renderer that trusts its input; the cleaners are
    the only reason that is safe, so nothing skips them on the way to a page
    thirty children will open.
    """
    out = []
    for i, st in enumerate((lesson.get("steps") or [])[:14]):
        if not isinstance(st, dict):
            continue
        for key, cleaner in (("draw", _draw.clean), ("sketch", _sketch.clean),
                             ("scene", _scene.clean)):
            spec = cleaner(st.get(key))
            if spec:
                out.append({"how": key, "step": i, "spec": spec})

    # And the document's OWN pictures, when the lesson came from a PDF.
    #
    # Without this a chapter written up on the teacher's screen arrived at
    # the class board as words with the diagrams missing — which for a
    # chapter about a ray diagram or a labelled cell is not a shorter lesson,
    # it is the wrong one. They travel with the words rather than being
    # fetched again, because the PDF they came from is on somebody's laptop.
    #
    # Data URLs, checked rather than trusted: this is stored and then handed
    # to every child in the class, and "src" is the one field on the page a
    # browser will go and execute something for. Only base64 image data gets
    # through — no http, no svg, no javascript:.
    for k, pic in enumerate((lesson.get("pictures") or [])[:PIC_KEEP]):
        if not isinstance(pic, dict):
            continue
        src = str(pic.get("src") or "")
        if not _PIC_SRC.match(src) or len(src) > PIC_SRC_MAX:
            continue
        out.append({"how": "pic", "step": int(pic.get("step") or 0),
                    "spec": {"src": src, "page": int(pic.get("page") or 0)}})

    # And the PHOTOGRAPHS, which were being dropped entirely.
    #
    # A board lesson gets a lead photograph and one against each step it can
    # find one for — that is what _illustrate is — and none of them survived
    # being kept. So a teacher wrote up DNA with a picture of DNA on the
    # screen, pressed save, and the class opened a page of prose. The words
    # were kept and the reason the lesson was worth keeping was not.
    #
    # Only an https address on a host the picture search itself named, and
    # the credit travels with it: these are other people's photographs under
    # licences that require the author be named, and a saved copy that drops
    # the attribution is a licence breach sitting on a school's page.
    def _photo(p, step):
        if not isinstance(p, dict):
            return None
        url = str(p.get("url") or "")
        if not url.startswith("https://"):
            return None
        host = url.split("/")[2].lower() if len(url.split("/")) > 2 else ""
        if not any(host == h or host.endswith("." + h)
                   for h in _images._HOSTS):
            return None
        return {"how": "photo", "step": step,
                "spec": {"url": url[:600],
                         "caption": str(p.get("caption") or "")[:200],
                         "author": str(p.get("author") or "")[:160],
                         "license": str(p.get("license") or "")[:80],
                         "page": str(p.get("page") or "")[:600]}}

    lead = _photo(lesson.get("photo"), -1)
    if lead:
        out.append(lead)
    for i, st in enumerate((lesson.get("steps") or [])[:14]):
        if isinstance(st, dict):
            got = _photo(st.get("photo"), i)
            if got:
                out.append(got)

    if not out:
        return ""
    text = json.dumps(out)
    # A lesson with a protein in it is large, and one carrying a chapter's
    # diagrams is larger. Past this it is not worth a row in every class's
    # material list, and the words still save.
    return text if len(text) <= 1_400_000 else ""


def _board_subject(db, cid, user, asked):
    """Which subject a lesson is filed under, checked rather than typed.

    A class has subjects and each subject has a teacher: that is what a
    SubjectSlot is, and it is the connection the whole classroom hangs off.
    A free-text box beside it lets the same subject be filed as "Biology",
    "biology" and "Bio" in one term, and lets a maths teacher file a lesson
    under somebody else's science — neither of which anybody notices until
    a class cannot find last week's work.

    A head teacher runs the school and may file under any subject the class
    actually has. A subject teacher may file under theirs. Nobody may invent
    one here — subjects are created with the class, by the head teacher.
    """
    want = (asked or "").strip()[:80]
    have = sorted({s.subject for s in db.query(SubjectSlot)
                   .filter(SubjectSlot.class_id == cid).all()})
    mine = _my_subjects(db, cid, user)          # None = head, all of them

    # A school that has not set its subjects up yet is not a school doing
    # something wrong, it is a school on its first afternoon. The rule gets
    # stricter the moment there is something to be strict about, rather than
    # locking a head teacher out of her own board on day one.
    if not have:
        if mine is None:
            return want
        raise HTTPException(403,
            "You have no subject in this class yet. A head teacher creates "
            "the subjects for a class and gives each one its code; claim "
            "yours with that code and it will be here.")

    allowed = have if mine is None else sorted(set(have) & set(mine))
    if not allowed:
        raise HTTPException(403,
            "You do not teach any of this class's subjects ("
            + ", ".join(have) + "). Claim yours with the code your head "
            "teacher gave you.")
    if not want:
        # One subject and no ambiguity: do not make somebody choose from a
        # list of one every time they save a lesson.
        if len(allowed) == 1:
            return allowed[0]
        raise HTTPException(400,
            "Say which subject this belongs to: " + ", ".join(allowed) + ".")
    for s in allowed:                            # case-insensitive, exact set
        if s.lower() == want.lower():
            return s
    raise HTTPException(403,
        f"You do not teach {want} in this class. You teach: "
        + ", ".join(allowed) + ".")


class BoardSaveIn(BaseModel):
    class_id: int = 0
    folder: str = Field(default="", max_length=80)
    topic: str = Field(min_length=2, max_length=200)
    title: str = Field(default="", max_length=240)
    subject: str = Field(default="", max_length=80)
    note: str = Field(default="", max_length=2000)
    lesson: dict = {}


def _board_teacher_id(request, db):
    """Whoever the school put on the subject this board is holding, or 0.

    A board is not a person, but everything charged or counted still needs a
    name against it. The token names the subject; the subject names its
    teacher.
    """
    try:
        grant = _board_grant(db, request.headers.get("X-Board-Token", ""))
    except Exception:
        return 0
    return int((grant or {}).get("teacher_id") or 0)


def board_or_reader(request: Request, db: Session = Depends(get_db)):
    """A signed-in person, or a board holding a subject code.

    For the read-only catalogues — the published course list, the simulation
    index. There is no per-person content in either, so requiring a session
    was not protecting anything; it just meant a classroom board could not
    read them. The board asked, got a 401, and showed "Not signed in" on the
    simulations and an eternal "Loading the courses…" on the course list,
    because the throw landed where nothing caught it.

    Returns the User when there is one and None for a board, so a caller that
    wants to personalise can, and one that does not need never look.
    """
    if _board_grant(db, request.headers.get("X-Board-Token", "")) is not None:
        return None
    try:
        return current_user(request, db)
    except HTTPException:
        raise HTTPException(
            401, "Sign in, or open this classroom with your subject code "
                 "first.")


def board_or_teacher(request: Request, db: Session = Depends(get_db)):
    """Either a signed-in teacher, or a board holding a subject code's token.

    A DEPENDENCY, and the token comes from a header rather than the body, for
    a reason worth writing down: FastAPI resolves dependencies before it
    validates the body. With the check inside the handler, an anonymous
    caller with a malformed body got a 422 describing the schema instead of
    being turned away — the refusal has to come first, and it can only come
    first if it does not need to read the body.

    A credential belongs in a header in any case. It is not part of what is
    being saved.

    Returns (user, grant): exactly one of them is set.
    """
    grant = _board_grant(db, request.headers.get("X-Board-Token", ""))
    if grant is not None:
        return None, grant
    try:
        user = current_user(request, db)
    except HTTPException:
        raise HTTPException(
            401, "Sign in, or open this classroom with your subject code "
                 "first.")
    return teaching_user(user, db), None


@app.post("/api/craxlearn/board/save")
def craxlearn_board_save(body: BoardSaveIn,
                         who=Depends(board_or_teacher),
                         db: Session = Depends(get_db)):
    """Keep what was just taught, on the class's subject page.

    Different from setting it as an assignment, and both are wanted. An
    assignment is work with a deadline that a particular class has to do; this
    is the explanation itself, filed under its subject, for the teacher to
    open again next year and for the class to read again the night before an
    exam. A lesson that only exists as an assignment disappears the moment it
    is marked.

    Saved as text rather than a file, so it opens on the subject page instead
    of downloading something a phone may not be able to read.

    Two ways in, and only two.

    A signed-in teacher, as before — the ordinary case, and the one that
    reaches this from a laptop.

    Or a board token, which is what a subject code buys at the board itself.
    It names one class and one subject and unlocks this route and no other:
    the teacher joins the classroom with their code, teaches, and what they
    taught lands under their subject. It cannot read a register, a mark, a
    discussion or a fee, because it is not an account — it is one capability
    with an expiry on it.

    The class_id and subject in the request are IGNORED when a board token is
    used. They are taken from the token, so a code for 6-a Science cannot be
    pointed at 6-b, and a browser cannot rename the subject it is filing
    under.
    """
    user, grant = who
    if grant is None:
        _own_class(db, body.class_id, user)
        class_id = body.class_id
        subject = _board_subject(db, body.class_id, user, body.subject)
        teacher_id = user.id
        by = user.name
    else:
        class_id = grant["class_id"]
        subject = grant["subject"]
        # Attributed to whoever the school put on that subject, which is who
        # the class will expect to see against it. If the slot is unfilled it
        # is attributed to nobody rather than to whoever was standing there.
        teacher_id = grant["teacher_id"]
        who = db.get(User, teacher_id) if teacher_id else None
        by = who.name if who else ""

    text = _lesson_to_body(body.lesson or {}, "")
    if not text:
        raise HTTPException(400, "There is nothing in that lesson to save.")
    title = (body.title or body.topic).strip()[:240]
    m = Material(class_id=class_id, teacher_id=teacher_id,
                 subject=subject,
                 # Anything kept off the board goes to Saved unless the
                 # teacher said otherwise, which is where she will look.
                 folder=_folder_of(body.folder, "Saved"),
                 title=title, note=(body.note or "").strip()[:2000],
                 body=text, figures=_lesson_figures(body.lesson or {}))
    db.add(m)
    db.commit()
    db.refresh(m)
    return {"ok": True, "material": _material_json(m, by=by)}


def _board_where(who, db, class_id=0, subject=""):
    """The one class and one subject a board request is allowed to touch.

    A board token names both, and they are read from the token rather than
    from the request: a code for 6-a Science cannot be pointed at 6-b, and a
    browser cannot rename the subject it is filing under. A signed-in teacher
    says which class, and is held to the subjects they actually teach.
    """
    user, grant = who
    if grant is not None:
        return grant["class_id"], grant["subject"], grant["teacher_id"]
    _own_class(db, class_id, user)
    return class_id, _board_subject(db, class_id, user, subject), user.id


# The pictures ship UNCOMPRESSED, and the corpus does not, for one reason:
# they are already JPEG. Gzip takes the 24.5 MB corpus to 10.2 and this file
# from 31 MB to 28 — eight per cent, in exchange for an unpack step at boot,
# a stamp to keep in step with it, and twice the disk while both copies
# exist. Not worth it. The file is read where it lands.
PICS_PATH = env("PICS_PATH") or str(BASE_DIR / "corpus-pics.db")


def _rag_index_only():
    """The corpus index if there is one, without building a fallback.

    `_rag_ready` builds an index out of the site's own lessons when there is
    no corpus, which is right for answering a question and wrong here: a
    coding lesson is not a chapter of a school book and must not be offered
    as one.
    """
    try:
        _unpack_corpus()
        return _rag.open_fts(CORPUS_PATH)
    except Exception:
        return None


def _book_pics_local(code):
    """One chapter's diagrams out of the shipped archive, or None.

    None means "this archive does not know about that chapter", which is
    different from "that chapter has no diagrams" — the first is a reason to
    go and fetch it, the second is an answer. An empty list is the answer.
    """
    import sqlite3
    if not os.path.exists(PICS_PATH):
        return None
    try:
        con = sqlite3.connect(f"file:{PICS_PATH}?mode=ro", uri=True)
    except Exception:
        return None
    try:
        seen = con.execute("SELECT 1 FROM done WHERE code = ?",
                           (code,)).fetchone()
        if not seen:
            return None
        rows = con.execute(
            "SELECT page, w, h, jpeg FROM pictures WHERE code = ? "
            "ORDER BY page", (code,)).fetchall()
    except Exception:
        return None
    finally:
        con.close()
    return [{"src": "data:image/jpeg;base64,"
                    + base64.b64encode(j).decode(),
             "page": p, "w": w, "h": h} for p, w, h, j in rows]


@app.get("/api/craxlearn/book-pictures")
def craxlearn_book_pictures(code: str = "",
                            user: User = Depends(board_or_reader),
                            db: Session = Depends(get_db)):
    """The diagrams from one NCERT chapter.

    The corpus holds the text of eighteen books and none of their pictures,
    and for most of what a class asks that is the right trade — the numbers
    are in the passage and the board draws its own diagram. It is the wrong
    trade for the chapters whose whole point IS the figure: a ray diagram, a
    labelled cell, a circuit, a balance sheet's layout.

    Fetched on demand rather than shipped. The pictures in these chapters are
    118 MB raw and 28 MB re-encoded, against 10 MB for the entire text of the
    same books — quadrupling the artefact to carry diagrams for hundreds of
    chapters nobody opens this term is the wrong way round. One download per
    chapter, once, for the chapters actually taught.

    Cached against the chapter code, so the second class to reach that
    chapter pays nothing, and so does the same class next year.
    """
    import corpus as _corpus
    code = re.sub(r"[^a-z0-9]", "", (code or "").lower())[:16]
    if not code:
        raise HTTPException(400, "Which chapter?")
    # It must be a chapter this corpus actually holds. Without this the route
    # is a way to make the server fetch arbitrary files from ncert.nic.in on
    # request, which is somebody else's bandwidth and our IP address.
    known = False
    try:
        for prefix, _k, _s, n in _corpus.BOOKS:
            for i in range(1, n + 1):
                if _corpus.code_for(prefix, i) == code:
                    known = True
                    break
            if known:
                break
    except Exception:
        known = False
    if not known:
        raise HTTPException(404, "That is not a chapter in the books here.")

    qkey = f"bookpics|{code}"[:500]
    row = db.query(AskCache).filter(AskCache.qkey == qkey).first()
    got = _cached_json(db, row, need=None)
    if got is not None:
        row.hits = (row.hits or 0) + 1
        db.commit()
        return {"pictures": got.get("pictures", []), "cached": True}

    # The shipped archive first.
    #
    # These were fetched on demand at first and the measurement killed it: a
    # chapter's first request took THIRTY-THREE SECONDS, because ncert.nic.in
    # throttles and the fetch retries through it. Fine in a script, unusable
    # standing in front of a class. So they travel with the books, and the
    # download below is only the fallback for a chapter the archive missed.
    pics = _book_pics_local(code)
    if pics is None:
        pics = _corpus.chapter_pictures(code)
    # An empty result is cached too, and deliberately. A chapter with no
    # diagrams in it will still have none next week, and re-downloading four
    # megabytes to find that out again is the mistake this cache exists to
    # stop.
    _ai_cache_put(db, qkey, {"pictures": pics})
    return {"pictures": pics, "cached": False}


@app.post("/api/craxlearn/handwriting")
async def craxlearn_handwriting(file: UploadFile = File(...),
                                who=Depends(board_or_teacher),
                                db: Session = Depends(get_db)):
    """Turn what was written by hand into typed text.

    ON DEMAND, and never on a timer. A teacher presses a button when they
    want it; nothing here runs because somebody drew a line. That is the
    whole reason this is a route and not a background job — reading a board
    costs a vision call, and a vision call per stroke would be the most
    expensive thing in the product by a wide margin.

    Cached on the bytes of the picture, exactly like the scanner, so pressing
    it twice on the same working is one call. A board that has not been
    written on since the last press pays nothing.

    It returns the text and nothing else. It does not rewrite, correct or
    answer what it read: a teacher who writes a wrong intermediate step on
    purpose, to ask a class where the mistake is, must get that step back
    unchanged. Tidying it up would quietly destroy the lesson.
    """
    raw = await file.read()
    if not raw:
        raise HTTPException(400, "There is nothing written to read")
    if len(raw) > 8 * 1024 * 1024:
        raise HTTPException(400, "That picture of the board is too large")
    mime = (file.content_type or "").lower().split(";")[0].strip()
    if mime not in ("image/png", "image/jpeg", "image/webp"):
        raise HTTPException(400, "Send a PNG, JPG or WEBP")
    if not ASK_ENABLED:
        raise HTTPException(503, "The AI tutor is not switched on")

    user, grant = who
    owner = db.get(User, grant["teacher_id"]) if grant else user
    if owner is None:
        raise HTTPException(403, "Nobody is on this subject to charge this to")

    digest = hashlib.sha256(raw).hexdigest()
    qkey = _cl.key(_scope_of(db, owner), "hand", digest)[:500]
    row = db.query(AskCache).filter(AskCache.qkey == qkey).first()
    out = _cached_json(db, row, need=None)
    if out:
        row.hits = (row.hits or 0) + 1
        db.commit()
        return {"text": out.get("text", ""), "cached": True}

    _ai_enforce_limit(db, owner)
    try:
        got = _ai_json(await _ai_vision(
            "Read the handwriting in this picture and return it as text.\n"
            "Return JSON only: {\"text\": \"...\"}\n"
            "Copy what is written EXACTLY. Do not correct spelling, do not "
            "fix arithmetic, do not finish an unfinished line and do not "
            "answer anything. A wrong step may have been written on purpose "
            "for a class to find.\n"
            "Keep line breaks. Write mathematics in plain text: x^2, "
            "sqrt(9), 3/4. If nothing is legible return {\"text\": \"\"}.",
            raw, mime, 1200))
    except Exception as e:
        print(f"Handwriting failed: {type(e).__name__}: {e}")
        raise HTTPException(503, _ai_error_message(e))

    text = str((got or {}).get("text") or "").strip()[:8000]
    if not text:
        # Nothing legible is a board to write on again, not an answer worth
        # storing — caching it would serve the blank straight back.
        return {"text": "", "cached": False}
    _ai_cache_put(db, qkey, {"text": text})
    return {"text": text, "cached": False}


@app.post("/api/craxlearn/board/file")
async def craxlearn_board_file(file: UploadFile = File(...),
                               title: str = Form(default=""),
                               note: str = Form(default=""),
                               folder: str = Form(default=""),
                               class_id: int = Form(default=0),
                               subject: str = Form(default=""),
                               who=Depends(board_or_teacher),
                               db: Session = Depends(get_db)):
    """Keep the document itself, exactly as it is.

    The other half of the board's upload. A chapter can be turned into a
    lesson, and often should be — but a worksheet, a past paper or a marked
    diagram is wanted on the screen unchanged, and turning it into prose
    would be destroying the thing the teacher meant to show.

    So both land in the same place, under the same class and subject, and the
    class sees one list. This one costs nothing and never fails on a scan,
    which is why it is offered first to a teacher whose PDF is a photograph
    of a page.
    """
    cid, subj, teacher_id = _board_where(who, db, class_id, subject)
    raw = await file.read()
    if not raw:
        raise HTTPException(400, "That file is empty")
    if len(raw) > MATERIAL_MAX:
        raise HTTPException(
            400, f"That file is {len(raw) // 1_000_000} MB. The limit is "
                 f"{MATERIAL_MAX // 1_000_000} MB — split it, or link to it "
                 f"instead.")
    mime = (file.content_type or "").lower().split(";")[0].strip()
    if mime not in MATERIAL_MIMES:
        raise HTTPException(
            400, "Upload a PDF, a PowerPoint, a Word document, a text file "
                 "or an image.")
    m = Material(class_id=cid, teacher_id=teacher_id, subject=subj,
                 # A picture kept off the board is a download unless the
                 # teacher named a drawer for it.
                 folder=_folder_of(folder, "Downloads"),
                 title=((title or "").strip()
                        or (file.filename or "Document"))[:240],
                 note=(note or "").strip()[:2000],
                 file_data=base64.b64encode(raw).decode(),
                 file_name=(file.filename or "document")[:160],
                 mime=mime, size=len(raw))
    db.add(m)
    db.commit()
    db.refresh(m)
    owner = db.get(User, teacher_id) if teacher_id else None
    return {"ok": True, "material": _material_json(
        m, by=(owner.name if owner else ""))}


@app.get("/api/craxlearn/board/materials")
def craxlearn_board_materials(class_id: int = 0, subject: str = "",
                              who=Depends(board_or_teacher),
                              db: Session = Depends(get_db)):
    """What has already been saved for this subject, ready to put back up.

    The point of saving a lesson is opening it again. Until now the only way
    back to one was the class page on somebody's laptop, which is not where
    the teacher is standing.

    Only this subject's material, because that is the whole of what the token
    names. It is not a way to read another teacher's shelf.
    """
    cid, subj, _ = _board_where(who, db, class_id, subject)
    rows = (db.query(Material)
              .filter(Material.class_id == cid,
                      func.lower(func.coalesce(Material.subject, ""))
                      == (subj or "").lower())
              .order_by(Material.created_at.desc()).limit(60).all())
    ids = {m.teacher_id for m in rows if m.teacher_id}
    names = {u.id: u.name
             for u in db.query(User).filter(User.id.in_(ids)).all()} \
        if ids else {}
    return {"class_id": cid, "subject": subj,
            "materials": [_material_json(m, by=names.get(m.teacher_id, ""))
                          for m in rows]}


@app.get("/api/craxlearn/board/material/{mid}/file")
def craxlearn_board_material_file(mid: int, class_id: int = 0,
                                  subject: str = "",
                                  who=Depends(board_or_teacher),
                                  db: Session = Depends(get_db)):
    """The document itself, for showing on the board.

    Checked against the room the token names, not against the id in the URL.
    Counting up from 1 must not walk out of this classroom.
    """
    cid, subj, _ = _board_where(who, db, class_id, subject)
    m = db.get(Material, mid)
    if not m or not m.file_data or m.class_id != cid \
            or (m.subject or "").lower() != (subj or "").lower():
        raise HTTPException(404, "Not found")
    try:
        raw = base64.b64decode(m.file_data)
    except Exception:
        raise HTTPException(500, "That file is stored damaged")
    return Response(
        content=raw, media_type=m.mime or "application/octet-stream",
        headers=_disposition((m.file_name or "document")[:80], "inline"))


# ---- the phone as a remote control ---------------------------------------
#
# A board on a classroom wall is a screen a teacher cannot reach without
# turning her back on the room. The phone in her pocket can reach it. So the
# board shows a code, the phone takes the code, and from then on the phone
# says what the board does — including saying a topic out loud into the
# phone's microphone, which is a far better microphone than a board's and is
# already six inches from her mouth.
#
# What the phone may do is a fixed list, checked here rather than trusted
# from the message. It is a remote control: it changes what is on a screen.
# It reads nothing and marks nothing.

REMOTE_TTL = dt.timedelta(hours=10)          # a school day, and then some
REMOTE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"   # no O/0, no I/1
REMOTE_CODE_LEN = 6
REMOTE_QUEUE_MAX = 40           # a board that is off must not bank commands

# What a phone is allowed to say. Anything else is dropped with a 400 rather
# than passed through for the page to puzzle over.
REMOTE_KINDS = {
    "go",        # open a tool in the live space   {page, arg}
    "teach",     # teach a topic                   {topic, level}
    "slide",     # move through a lesson           {to: "next"|"back"|number}
    "split",     # another space, or back to one
    "close",     # close the live space
    "home",      # back to the tools
    "pen",       # writing space: pick a colour    {i}
    "clear",     # writing space: rub it all out
    "undo",      # writing space: take one back
    "redo",
}

# Two different things, and conflating them breaks the remote.
#
# GUESSING a code is the only way in from outside, so it is held to a dozen
# tries a minute per address — at that rate a six-character code out of an
# alphabet of 32 takes longer to find than the ten hours it lives.
#
# USING a code you already hold is a teacher turning pages, changing pens
# and opening tools, and that is easily a tap a second in a busy minute. It
# is limited per code rather than per address, generously, and only to stop
# a stuck loop filling the table.
_REMOTE_TRIES: dict = {}
_REMOTE_JOIN_PER_MIN = 12
_REMOTE_CMD_PER_MIN = 150


# Guessing a class code returns the first names of the children in that class,
# so guessing has to be expensive. See _code_guard.
_CODE_TRIES: dict = {}
_CODE_FAILS: dict = {}
_CODE_PER_MIN = 10          # a classroom is never faster than this
_CODE_FAILS_PER_IP = 40     # per hour
_CODE_FAILS_GLOBAL = 600    # per hour, across everybody
_CODE_WINDOW = 3600.0


def _client_ip(request) -> str:
    """Who is asking, as well as can be known behind a proxy.

    X-Forwarded-For is written by the client and only appended to by the
    proxy, so this identifies an ordinary user and can be rotated by an
    attacker. That is exactly why it is not the only defence — the global
    ceiling below does not depend on it.
    """
    xff = (request.headers.get("x-forwarded-for") or "").split(",")
    first = xff[0].strip()
    if first:
        return first[:45]
    client = getattr(request, "client", None)
    return (getattr(client, "host", "") or "?")[:45]


def _code_guard(request):
    """Called before a code is looked up. Raises 429 if this is a sweep."""
    import time as _t
    now_s = _t.monotonic()
    ip = _client_ip(request)

    recent = [t for t in _CODE_TRIES.get(ip, []) if now_s - t < 60]
    if len(recent) >= _CODE_PER_MIN:
        raise HTTPException(429, "Too many tries. Wait a minute, then type "
                                 "the code again.")
    recent.append(now_s)
    _CODE_TRIES[ip] = recent
    if len(_CODE_TRIES) > 4000:
        for k in list(_CODE_TRIES)[:2000]:
            _CODE_TRIES.pop(k, None)

    fails = [t for t in _CODE_FAILS.get(ip, []) if now_s - t < _CODE_WINDOW]
    if len(fails) >= _CODE_FAILS_PER_IP:
        raise HTTPException(429, "Too many wrong codes from this device. "
                                 "Ask your teacher to check the code.")
    allfails = [t for t in _CODE_FAILS.get("*", []) if now_s - t < _CODE_WINDOW]
    if len(allfails) >= _CODE_FAILS_GLOBAL:
        raise HTTPException(429, "Too many wrong codes just now. Try again "
                                 "shortly.")


def _code_missed(request):
    """A code that matched nothing. Recorded per address and globally."""
    import time as _t
    now_s = _t.monotonic()
    ip = _client_ip(request)
    for key in (ip, "*"):
        seen = [t for t in _CODE_FAILS.get(key, []) if now_s - t < _CODE_WINDOW]
        seen.append(now_s)
        _CODE_FAILS[key] = seen
    if len(_CODE_FAILS) > 4000:
        for k in list(_CODE_FAILS)[:2000]:
            if k != "*":
                _CODE_FAILS.pop(k, None)


def _remote_throttle(who: str, per_min: int, whatfor: str):
    import time as _t
    now_s = _t.monotonic()
    seen = [t for t in _REMOTE_TRIES.get(who, []) if now_s - t < 60]
    if len(seen) >= per_min:
        raise HTTPException(429, whatfor)
    seen.append(now_s)
    _REMOTE_TRIES[who] = seen
    if len(_REMOTE_TRIES) > 4000:
        for k in list(_REMOTE_TRIES)[:2000]:
            _REMOTE_TRIES.pop(k, None)


def _remote_code(db) -> str:
    for _ in range(24):
        code = "".join(secrets.choice(REMOTE_ALPHABET)
                       for _ in range(REMOTE_CODE_LEN))
        if not db.query(RemoteLink).filter(RemoteLink.code == code).first():
            return code
    raise HTTPException(503, "Could not make a pairing code. Try again.")


def _remote_live(db, code: str):
    """The open link for a code, or None. Never raises for a bad code —
    the caller decides what to say, so that a wrong code and an expired one
    can be told apart."""
    if not code:
        return None
    link = db.query(RemoteLink).filter(
        RemoteLink.code == code.strip().upper()[:12]).first()
    if link is None or link.closed_at is not None:
        return None
    # SQLite hands back naive datetimes where Postgres hands back aware ones,
    # and comparing the two raises. Everything time-related here goes through
    # _aware for that reason.
    if link.expires_at and _aware(link.expires_at) < now():
        return None
    return link


class RemoteCmdIn(BaseModel):
    code: str = ""
    kind: str = ""
    payload: dict = Field(default_factory=dict)


class RemoteJoinIn(BaseModel):
    code: str = ""


@app.post("/api/craxlearn/remote/open")
def remote_open(user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """Turn this screen into a board a phone can drive.

    One open link per account: a second board would take the same commands
    and there is no way for a teacher to tell which one she is talking to.
    Asking again while one is open returns the same code rather than a
    second one, so a page reload does not orphan the phone in her hand.
    """
    live = db.query(RemoteLink).filter(
        RemoteLink.user_id == user.id,
        RemoteLink.closed_at.is_(None),
        RemoteLink.expires_at > now()).order_by(RemoteLink.id.desc()).first()
    if live is None:
        live = RemoteLink(code=_remote_code(db), user_id=user.id,
                          school_id=_school_of(user, db),
                          label=(user.name or "")[:80],
                          expires_at=now() + REMOTE_TTL)
        db.add(live)
    else:
        live.expires_at = now() + REMOTE_TTL
    live.board_seen = now()
    db.commit()
    return {"code": live.code, "expires": live.expires_at.isoformat()}


@app.post("/api/craxlearn/remote/close")
def remote_close(user: User = Depends(current_user),
                 db: Session = Depends(get_db)):
    """Stop taking commands. The phone is told next time it sends one."""
    n = 0
    for link in db.query(RemoteLink).filter(
            RemoteLink.user_id == user.id,
            RemoteLink.closed_at.is_(None)).all():
        link.closed_at = now()
        n += 1
    db.commit()
    return {"closed": n}


@app.get("/api/craxlearn/remote/poll")
def remote_poll(user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """The board asking what it has been told to do.

    Commands are handed over once and marked taken in the same transaction,
    so a board that reloads mid-lesson does not replay the last ten minutes
    of a teacher's remote at the class.
    """
    link = db.query(RemoteLink).filter(
        RemoteLink.user_id == user.id,
        RemoteLink.closed_at.is_(None),
        RemoteLink.expires_at > now()).order_by(RemoteLink.id.desc()).first()
    if link is None:
        return {"linked": False, "cmds": []}
    link.board_seen = now()
    rows = db.query(RemoteCmd).filter(
        RemoteCmd.link_id == link.id,
        RemoteCmd.taken_at.is_(None)).order_by(RemoteCmd.id.asc()).limit(20).all()
    out = []
    for r in rows:
        r.taken_at = now()
        try:
            data = json.loads(r.payload or "{}")
        except Exception:
            data = {}
        out.append({"kind": r.kind, "payload": data})
    db.commit()
    return {"linked": True, "code": link.code, "cmds": out,
            "phone": bool(link.phone_seen)}


@app.post("/api/craxlearn/remote/join")
def remote_join(body: RemoteJoinIn, request: Request,
                db: Session = Depends(get_db)):
    """A phone taking a code. No sign-in, on purpose — see RemoteLink."""
    _remote_throttle("join:" + (request.client.host if request.client else "?"),
                     _REMOTE_JOIN_PER_MIN,
                     "Too many tries. Wait a minute, then read the code off "
                     "the board again.")
    link = _remote_live(db, body.code)
    if link is None:
        raise HTTPException(404, "No board is using that code. Read it off "
                                 "the board again — it changes each day.")
    link.phone_seen = now()
    db.commit()
    return {"ok": True, "board": link.label or "the board",
            "code": link.code}


@app.post("/api/craxlearn/remote/cmd")
def remote_cmd(body: RemoteCmdIn, request: Request,
               db: Session = Depends(get_db)):
    """One instruction from the phone."""
    _remote_throttle("cmd:" + (body.code or "")[:12].upper(),
                     _REMOTE_CMD_PER_MIN,
                     "That is a lot of taps in one minute. Give it a moment.")
    link = _remote_live(db, body.code)
    if link is None:
        raise HTTPException(404, "That board is no longer listening.")
    kind = (body.kind or "").strip().lower()
    if kind not in REMOTE_KINDS:
        raise HTTPException(400, "That is not something the remote can do.")

    # A board that is switched off must not bank a lesson's worth of
    # commands and then run all of them at once when it comes back.
    waiting = db.query(RemoteCmd).filter(
        RemoteCmd.link_id == link.id, RemoteCmd.taken_at.is_(None)).count()
    if waiting >= REMOTE_QUEUE_MAX:
        raise HTTPException(409, "The board is not responding. Check it is "
                                 "awake and on this lesson.")

    # Trimmed here rather than trusted: this text is put on a screen in front
    # of a class, and it arrives from something holding only a six-character
    # code.
    data = body.payload if isinstance(body.payload, dict) else {}
    clean = {
        "page": str(data.get("page") or "")[:40],
        "arg": str(data.get("arg") or "")[:200],
        "topic": str(data.get("topic") or "")[:200],
        "level": str(data.get("level") or "")[:60],
        "to": str(data.get("to") or "")[:20],
        "i": int(data.get("i") or 0) if str(data.get("i") or "0").lstrip("-").isdigit() else 0,
    }
    db.add(RemoteCmd(link_id=link.id, kind=kind, payload=json.dumps(clean)))
    link.phone_seen = now()
    db.commit()
    # Say whether anybody is listening, so the phone can show "the board is
    # not awake" instead of appearing to work while nothing happens.
    fresh = (link.board_seen is not None
             and (now() - _aware(link.board_seen)) < dt.timedelta(seconds=25))
    return {"sent": True, "board_awake": bool(fresh)}


@app.post("/api/craxlearn/board/assign")
def craxlearn_board_assign(body: BoardAssignIn,
                           user: User = Depends(teacher_user),
                           db: Session = Depends(get_db)):
    """Set what is on the board as an assignment for one class.

    This is the whole point of teaching on a board that is part of the
    platform: the lesson the class just watched becomes the work they take
    away, without anybody retyping it. It appears in the students' own view
    and in the teacher's the moment it is created — there is nothing to
    publish, because an assignment nobody can see is not a draft, it is a
    mistake waiting to be noticed on the due date.

    Deliberately the same Assignment row that a typed assignment creates.
    A second kind of assignment would mean a second submission flow, a
    second review screen and two ways for a student to be marked, which is
    how a classroom product becomes unusable.
    """
    _own_class(db, body.class_id, user)

    # A subject teacher is locked to the subject they hold in this class, the
    # same as when they type one by hand — the board does not become a way
    # round that. The same check as saving a lesson, so a teacher cannot set
    # work under a subject she could not file a lesson under.
    subject = _board_subject(db, body.class_id, user, body.subject)

    topic = _cl.redact(body.topic)[:200]
    text = _lesson_to_body(body.lesson if isinstance(body.lesson, dict) else {},
                           body.task)
    if not text:
        raise HTTPException(400, "There is no lesson on the board to set")

    a = Assignment(class_id=body.class_id, teacher_id=user.id, kind="task",
                   subject=subject,
                   title=(body.title.strip() or topic)[:240],
                   body=text, board_topic=topic,
                   due_date=body.due_date.strip()[:20])
    db.add(a)
    db.commit()
    db.refresh(a)

    n = (db.query(func.count(ClassMember.id))
           .filter(ClassMember.class_id == body.class_id).scalar() or 0)
    return {"ok": True, "assignment": _asg_json(a), "students": n}


class ReviewIn(BaseModel):
    feedback: str = Field(default="", max_length=4000)


@app.post("/api/teacher/submission/{aid}/{uid}/review")
def review_submission(aid: int, uid: int, body: ReviewIn,
                      user: User = Depends(teacher_user),
                      db: Session = Depends(get_db)):
    """Mark one student's work as reviewed, with or without a comment.

    Marking it with nothing to say is allowed and is not a gap: "seen, fine"
    is a real outcome and the alternative is a teacher typing "good" forty
    times to clear a list.
    """
    a = db.get(Assignment, aid)
    if not a:
        raise HTTPException(404, "Not found")
    _own_class(db, a.class_id, user)
    sub = (db.query(Submission)
             .filter(Submission.assignment_id == aid,
                     Submission.user_id == uid).first())
    if not sub:
        raise HTTPException(404, "That student has not submitted yet")
    # `updated_at` carries `onupdate=now`, so ANY write to this row moves it
    # — including this one. Two things break if it is left to:
    #
    # 1. The student's "handed in at" jumps to the moment the teacher marked
    #    it, which is not when they handed it in and is visible to them.
    # 2. "Waiting again" is computed from updated_at > reviewed_at, and the
    #    review's own bump lands after reviewed_at — so every piece of work
    #    reappeared in the queue the instant it was marked.
    #
    # Assigning the old value explicitly wins over onupdate, which keeps
    # both meanings intact: updated_at is when the STUDENT last wrote.
    # Assigning the SAME value back is not a change, so SQLAlchemy leaves
    # the column out of the UPDATE and `onupdate` fills it in anyway — which
    # is exactly the bug this is here to stop, wearing the fix's clothes.
    # flag_modified forces it into the SET clause, and a column present
    # there is not touched by onupdate.
    keep = sub.updated_at
    sub.feedback = body.feedback.strip()[:4000]
    sub.reviewed_at = now()
    sub.reviewed_by = user.id
    if keep is not None:
        sub.updated_at = keep
        flag_modified(sub, "updated_at")
    db.commit()
    return {"ok": True, "reviewed_at": sub.reviewed_at.isoformat()}


@app.get("/api/teacher/inbox")
def teacher_inbox(user: User = Depends(teacher_user),
                  db: Session = Depends(get_db)):
    """Every piece of work waiting for this teacher, across every class.

    The thing that makes "review it anywhere" true. Without it a teacher
    walks class, then assignment, then submissions, three taps deep, once
    per class, to find out whether anything arrived — which on a phone
    between lessons means they do not look.

    Scoped by the same rule as everywhere else: a head teacher sees their
    school's classes, a subject teacher sees the classes where they hold a
    subject. Nothing here can reach another school.
    """
    head = is_head(user, db)
    t = teacher_row(user, db)
    if head:
        sid = t.school_id if t else 0
        q = db.query(Klass)
        classes = (q.filter(Klass.school_id == sid) if sid
                   else q.filter(Klass.teacher_id == user.id)).all()
    else:
        ids = {sl.class_id for sl in db.query(SubjectSlot)
               .filter(SubjectSlot.teacher_id == user.id).all()}
        classes = (db.query(Klass).filter(Klass.id.in_(ids)).all()
                   if ids else [])
    by_class = {k.id: k for k in classes}
    if not by_class:
        return {"waiting": [], "classes": 0, "total": 0}

    rows = (db.query(Submission, Assignment, User)
              .join(Assignment, Assignment.id == Submission.assignment_id)
              .join(User, User.id == Submission.user_id)
              .filter(Assignment.class_id.in_(list(by_class)))
              .order_by(Submission.updated_at.desc()).limit(300).all())

    waiting, reviewed = [], 0
    for sub, a, student in rows:
        # Reviewed, then edited again by the student, is waiting once more.
        # A teacher who has read version one has not read version two, and
        # treating it as done is how a resubmission disappears.
        fresh = (sub.reviewed_at is not None and sub.updated_at is not None
                 and sub.updated_at > sub.reviewed_at)
        if sub.reviewed_at is not None and not fresh:
            reviewed += 1
            continue
        waiting.append({
            "assignment_id": a.id, "title": a.title,
            "subject": a.subject or "",
            "class_id": a.class_id,
            "class_name": by_class[a.class_id].name,
            "student_id": student.id, "student": student.name,
            "resubmitted": fresh,
            "at": sub.updated_at.isoformat() if sub.updated_at else "",
        })
    return {"waiting": waiting, "classes": len(by_class),
            "total": len(waiting), "reviewed": reviewed}


async def _resolve_structure(client, name):
    """A real, measured 3D structure for a name — or nothing.

    The same sources, in the same order, as a board lesson uses, and for the
    same reason: most specific first, and nothing invented at any step. A
    name with nothing measured behind it returns nothing, which is the
    honest answer and the one that stops a classroom being shown a plausible
    arrangement of spheres captioned with a real compound's name.

    Factored out of _offer_scene so the board and this share one path. Two
    copies would drift, and the copy that drifted would be the one drawing
    the picture nobody checked.
    """
    name = (name or "").strip()
    if not name:
        return None

    got = _lattice.clean(name)
    if got:
        return _scene.clean(dict(got, kind="lattice", caption=name.title(),
                                 a=2.0, a_angstrom=got["a"], repeat=2))
    got = _layers.clean(name)
    if got:
        return _scene.clean(dict(got, kind="layers", caption=name.title()))
    got = _orbits.clean(name)
    if got:
        return _scene.clean(dict(got, kind="orbit", caption=name.title()))

    try:
        got = await _molecule.find(client, name)
    except Exception:
        got = {}
    if got and 2 <= len(got.get("atoms") or []) <= _scene.MAX_ATOMS:
        formula = got.get("formula") or ""
        return _scene.clean({
            "kind": "molecule",
            "caption": name.title() + (" - " + formula if formula else ""),
            "atoms": [{"el": a["el"], "x": a["x"], "y": a["y"], "z": a["z"]}
                      for a in got["atoms"]],
            "bonds": [list(b) for b in got["bonds"]],
        })

    if _protein.canonical(name):
        try:
            got = await _protein.find(client, name)
        except Exception:
            got = {}
        if got:
            return _scene.clean(dict(got, kind="protein",
                                     caption=(got.get("title")
                                              or name.title())[:110]))
    return None


@app.get("/api/craxlearn/structure")
async def craxlearn_structure(name: str,
                              user: User = Depends(board_or_reader)):
    """Put a real structure on the board, for anything we actually have one of.

    Free — every source behind it is either a table in this repository or a
    public database, and none of it is a model call. So a class can turn
    twenty things around in a lesson and it costs what one does.
    """
    name = _cl.redact(name)[:120]
    if len(name) < 2:
        raise HTTPException(400, "Name the thing you want to see")
    async with httpx.AsyncClient(follow_redirects=True, timeout=12) as c:
        scene = await _resolve_structure(c, name)
    if not scene:
        # No measurement — so somebody else's model of it, if the library
        # has one.
        #
        # "There is no measured structure here for 'human body'" is honest
        # and it is not a lesson. A heart has no parameters, and neither
        # does a kidney, a jet engine or a Chola bronze; all of them have
        # been modelled by somebody, and a class asking to see one should
        # see one. What must never happen is the two being confused, so a
        # model arrives labelled with who made it and under what licence,
        # where a measured scene says measured.
        async with httpx.AsyncClient(follow_redirects=True, timeout=10) as c:
            models = await _models3d.find(c, name, 8)
        if models:
            return {"name": name, "scene": None, "models": models,
                    "note": "No measured structure exists for this, so these "
                            "are models made by the people credited on them. "
                            "A drawing of the thing, not a measurement of it."}
        raise HTTPException(
            404, f"Nothing here for {name!r} — no measured structure, and no "
                 f"model of it in the open library either. Try the plainer "
                 f"word for it: 'heart' rather than 'human heart anatomy'.")
    return {"name": name, "scene": scene}


@app.get("/api/craxlearn/search")
async def craxlearn_search(q: str, user: User = Depends(board_or_reader)):
    """Search the open sources for something to show the room.

    A photograph where one exists, a measured structure where one exists,
    the diagrams from the school books where the topic is in them, and the
    licence beside each. Nothing here is generated: it is a search over the
    same public catalogues listed at /api/craxlearn/sources, which is why the
    result can carry a credit line that means something.

    Open to a board holding a subject code. It required a session, so the
    "Search the sources" tool was in the board's menu, drew its box, and
    answered 401 to the first thing anybody typed into it — the same fault as
    the simulations and the course list, in the third place.
    """
    q = _cl.redact(q)[:120]
    if len(q) < 2:
        raise HTTPException(400, "Type something to look for")
    async with httpx.AsyncClient(follow_redirects=True, timeout=12) as c:
        try:
            photo = await _images.find(c, q)
        except Exception as e:
            print(f"Source search picture failed: {type(e).__name__}: {e}")
            photo = {}
        try:
            scene = await _resolve_structure(c, q)
        except Exception as e:
            print(f"Source search structure failed: {type(e).__name__}: {e}")
            scene = None
    # And the chapters of the school books this is actually in.
    #
    # The catalogues above are the open internet; this is the shelf the class
    # is examined on. A teacher searching "refraction" wants the NCERT figure
    # from their own chapter at least as much as a photograph of a pencil in
    # a glass — and until now the books' diagrams had an API and nothing that
    # led anybody to it.
    chapters = []
    try:
        idx = _rag_index_only()
        hits = list(idx.search(q, 6)) if idx else []
        # Only the ones that are really about this.
        #
        # A search for "rocket" came back with Class 9 Science on forces —
        # which is right, a rocket is Newton's third law — and then Class 11
        # Physics and Class 11 Maths on limits and derivatives, which are
        # not. Three results where one was relevant reads as a broken search,
        # and worse, it pushes the open catalogues off the screen: the NASA
        # photograph of the thing they asked for is below the fold, under two
        # chapters that have nothing to do with it.
        #
        # Relative to the best match rather than an absolute floor, because
        # BM25 scores are not comparable between queries — a rare word scores
        # high everywhere it appears and a common one scores low even in the
        # chapter that is entirely about it. What IS comparable is the gap
        # between the best hit and the rest of the same search.
        best = max((h.get("score") or 0) for h in hits) if hits else 0
        for h in hits:
            if best and (h.get("score") or 0) < best * 0.85:
                break
            code = (h.get("slug") or "").strip()
            title = (h.get("title") or "").strip()
            if code and title.startswith("Class ") and not any(
                    c["code"] == code for c in chapters):
                chapters.append({"code": code, "title": title})
    except Exception as e:
        print(f"Source search chapters failed: {type(e).__name__}: {e}")
    return {"query": q, "photo": photo or None, "scene": scene,
            "chapters": chapters[:3],
            "found": bool(photo or scene or chapters),
            "sources": [s["name"] for s in _cl.sourcing()]}


@app.get("/api/craxlearn/picture")
async def craxlearn_picture(url: str, user: User = Depends(board_or_reader)):
    """One picture from the open catalogues, served from our own origin.

    Not a convenience. A remote image drawn onto a canvas TAINTS it, and a
    tainted canvas refuses toBlob and toDataURL — so a teacher who dropped a
    diagram of the eye onto the board would find that Save to the class and
    Download had both stopped working, with no error anybody could act on.
    Coming back through here, the bytes are same-origin and the board can
    still be photographed.

    The allowlist is the same one the lesson figures use, so this proxies
    Wikimedia, PubChem, the PDB and NASA and nothing else. Without it this
    route would fetch any URL in the world on the server's behalf, from
    inside the network the database is on.

    SVG is refused. It is an image everywhere else and a document that can
    carry script here, and serving one from our own origin is the whole
    shape of a stored XSS. Every catalogue thumbnail is a PNG or a JPEG.
    """
    url = (url or "")[:600]
    if not url.startswith("https://"):
        raise HTTPException(400, "Pictures are fetched over https only.")
    parts = url.split("/")
    host = parts[2].lower() if len(parts) > 2 else ""
    if not any(host == h or host.endswith("." + h) for h in _images._HOSTS):
        raise HTTPException(
            400, "That picture is not from one of the open catalogues.")
    try:
        async with httpx.AsyncClient(follow_redirects=True, timeout=15) as c:
            r = await c.get(url, headers={"User-Agent": _images.UA})
    except Exception as e:
        print(f"Picture proxy failed: {type(e).__name__}: {e}")
        raise HTTPException(502, "The catalogue could not be reached.")
    if r.status_code != 200:
        raise HTTPException(502, "The catalogue does not have that picture.")
    kind = (r.headers.get("content-type") or "").split(";")[0].strip().lower()
    if kind not in ("image/png", "image/jpeg", "image/webp", "image/gif"):
        raise HTTPException(400, "That is not a picture this board can draw.")
    if len(r.content) > 12 * 1024 * 1024:
        raise HTTPException(413, "That picture is too large for a board.")
    return RawResponse(content=r.content, media_type=kind,
                       headers={"Cache-Control": "public, max-age=86400"})


# Checked once per process. PhET's catalogue does not change during a
# lesson, and asking them twenty times on every page load would be rude to
# a free service a school depends on.
_PHET_CHECKED = {}


@app.get("/api/craxlearn/phet")
async def craxlearn_phet(subject: str = "",
                         user: User = Depends(board_or_reader)):
    """PhET simulations a class can drive, and only ones that really answer.

    Every candidate is fetched from PhET before it is offered. An id this
    codebase has wrong simply never appears — which is the only honest way
    to ship a list of external URLs into a classroom, where the cost of a
    wrong one is a 404 on the board with thirty people watching.

    Verified once per process and remembered. If PhET cannot be reached at
    all, the list comes back empty with a reason rather than a wall of
    frames that will not load.
    """
    want = _cl.phet_candidates(subject)
    todo = [s for s in want if s["id"] not in _PHET_CHECKED]

    if todo:
        async with httpx.AsyncClient(follow_redirects=True, timeout=8) as c:
            async def look(sim):
                try:
                    # HEAD first: it is the cheap question, and PhET answers
                    # it. Some CDNs do not, so a 405 falls back to a ranged
                    # GET rather than being read as "missing".
                    r = await c.head(sim["url"])
                    if r.status_code == 405:
                        r = await c.get(sim["url"],
                                        headers={"Range": "bytes=0-256"})
                    return sim["id"], r.status_code < 400
                except Exception:
                    return sim["id"], None      # unreachable, not absent
            for sim_id, ok in await asyncio.gather(*[look(s) for s in todo]):
                if ok is not None:
                    _PHET_CHECKED[sim_id] = ok

    live = [s for s in want if _PHET_CHECKED.get(s["id"])]
    unknown = [s["id"] for s in want if s["id"] not in _PHET_CHECKED]
    return {
        "sims": live,
        "subjects": sorted({s["subject"] for s in _cl.phet_candidates()}),
        "licence": "CC BY 4.0 — University of Colorado Boulder",
        "note": ("" if live else
                 "PhET could not be reached from this server, so nothing is "
                 "offered rather than a list of frames that will not load."
                 if unknown else
                 "None of the simulations in this list answered."),
        "unverified": len(unknown),
    }


class CalcIn(BaseModel):
    expression: str = Field(min_length=1, max_length=300)


@app.post("/api/craxlearn/calc")
def craxlearn_calc(body: CalcIn, who=Depends(_teacher_or_board)):
    """A calculator, worked by the same evaluator that checks the lessons.

    Not eval, and not a model. `maths.evaluate` parses to a syntax tree and
    walks it against an allowlist — numbers, arithmetic and a short list of
    functions — so an expression typed on a classroom board by whoever is
    standing at it can contain only arithmetic. That matters more here than
    anywhere else in the product: this is the one input box in a room full
    of teenagers who have just been taught what a sandbox is.

    Signed in, because it is a classroom tool and not a free API to point a
    load generator at.
    """
    expr = body.expression.strip()
    got = _maths.evaluate(expr, {})
    if got is None:
        raise HTTPException(
            400, "That is not arithmetic this can work out. Numbers, "
                 "+ - * / ^, brackets, and sqrt, log, sin, cos, tan.")
    # Trailing zeros off a float that is really an integer: a calculator
    # that answers 12.0 to "6*2" reads as broken to the room.
    if isinstance(got, float) and got.is_integer() and abs(got) < 1e15:
        shown = str(int(got))
    else:
        shown = f"{got:.10g}"
    return {"expression": expr, "result": shown, "value": got}


@app.get("/api/curriculum/groups")
def curriculum_groups(group: str = ""):
    """What we can teach, arranged the way a coaching centre buys it.

    Unauthenticated, for the same reason /api/craxlearn/sources is: "which
    syllabus do you cover" is the first question a centre asks and it is
    asked before anybody has an account.

    A school says "Class 9"; a centre says MPC, BiPC, NEET, JEE. Those are
    bundles across two years, and asking a centre to translate its own
    product into ours is asking it to do our work.

    Counted from the corpus on every call rather than from a list in the
    code. A hard-coded "yes we have Class 12 Biology" that the ingestion
    actually missed is not a stale number, it is a promise made to a customer
    that the product then breaks in front of a class. The passage count is
    shown for the same reason: a book present with nine passages did not
    ingest, and a centre should see that rather than a tick.
    """
    try:
        import sqlite3
        import groups as _groups
        if not os.path.exists(CORPUS_PATH):
            return {"groups": [], "corpus": 0,
                    "note": "No corpus is built on this deployment."}
        con = sqlite3.connect(f"file:{CORPUS_PATH}?mode=ro", uri=True)
        try:
            out = _groups.coverage(con, (group or "").strip().lower() or None)
            total = con.execute("select count(*) from passages").fetchone()[0]
        finally:
            con.close()
    except Exception as e:
        print(f"groups: {type(e).__name__}: {e}")
        return {"groups": [], "corpus": 0, "note": "Not available."}
    return {
        "groups": out, "corpus": total,
        # Said once, here, so it cannot be dropped by whoever renders it.
        # NCERT Physics is what JEE is built on and is not a JEE syllabus.
        "note": "These are the NCERT books each group is taught from. An "
                "entrance exam adds topics and sets its own weighting, and "
                "is not the same thing as the books it draws on.",
    }


def _school_only(db, user):
    """Papers and syllabuses are for accounts a school issued.

    Refused here rather than merely hidden from the menu. A menu item that
    is only hidden is a menu item, and #exams is five characters to guess —
    the same reason the job pages are closed by middleware and not by
    leaving them off the sidebar.
    """
    # The person sitting the exam, and nobody else.
    #
    # Not a teacher and not a school's office: they run the school, assign
    # the roles and post the updates. This was in their sidebar and then
    # refused them when they pressed Solve, which is the worst of both —
    # offered and then denied.
    #
    # A school's own pupil is in because their school bought it, and that
    # is the whole of the list. Refused here and not only hidden in the
    # menu, because a hidden menu item is still a menu item.
    #
    # **The site admin is NOT school staff, and used to be refused here.**
    # is_admin means whoever runs Craxle, not whoever runs a school — and
    # this line conflated the two, so the owner of the product could not
    # open the product. Two functions below, _at_school says the opposite in
    # as many words: "Admins pass, as everywhere — running the site means
    # needing every surface to debug it", and it never got the chance,
    # because this line refuses before that one is asked. Every other gate
    # in this file lets an admin through on its first line. This one now
    # does too; a school's teachers and office are still out, which was the
    # part that was actually decided.
    if teacher_row(user, db) is not None and not getattr(user, "is_admin",
                                                         False):
        raise HTTPException(
            403, "Past papers and entrance syllabuses are for the student "
                 "sitting the exam. A teaching or office account does not "
                 "carry them.")
    # A school's own pupil, and nobody else.
    #
    # Pro used to carry it for a personal account. It does not: this is the
    # material a school buys Craxlearn for, and selling the same thing to
    # somebody who walked in off the street undercuts the school that paid
    # for it. Decided twice — first as "Pro for the regular users", then
    # against — and it is the second answer that stands.
    if _at_school(db, user):
        return
    # Say what was actually seen.
    #
    # An account whose sidebar shows the Admin panel — so is_admin is true —
    # was refused here, and _at_school returns True for an admin on the
    # first line. Reproducing it locally gave 200. Guessing twice is how the
    # device-cap lockout went, so this reports the three facts the decision
    # was made on instead: whether it is an admin, whether it is staff, and
    # what scope it resolved to.
    try:
        why = (f"admin={bool(getattr(user, 'is_admin', False))} "
               f"kind={getattr(user, 'kind', '') or '-'} "
               f"staff={teacher_row(user, db) is not None} "
               f"scope={_scope_of(db, user)}")
    except Exception as e:
        why = f"could not be determined: {type(e).__name__}"
    print(f"exams refused user {user.id}: {why}")
    raise HTTPException(
        403, "Past papers and entrance syllabuses are part of a school's "
             "Craxlearn, and they come with the account your school gives "
             "you. A personal account does not carry them on any plan. "
             f"[{why}]")


@app.get("/api/exams/papers")
def exam_papers(q: str = "", kind: str = "", state: str = "",
                user: User = Depends(current_user),
                db: Session = Depends(get_db)):
    """Where a board actually publishes its own question papers.

    A teacher asks for past papers by board and year, and the honest product
    is a directory rather than a library. Every board owns the copyright in
    its papers; the sites that hold thousands of them do so without
    permission, and a school that buys a product built on those inherits the
    problem. So nothing is hosted and nothing is scraped — this points at the
    board's own page, which is also the only copy certain to be the real
    paper with the board's own corrections in it.

    For accounts a school issued. The links are public and hold nothing
    about anybody, so this is not secrecy — it is who the thing is for. A
    board's past papers belong to a classroom, and somebody who signed up
    here on their own to learn Python did not ask for a CBSE paper.
    """
    _school_only(db, user)
    try:
        import exams as _exams
        found = _exams.search(q, kind, state)
        all_states = _exams.states()
    except Exception as e:
        print(f"exam papers: {type(e).__name__}: {e}")
        return {"sources": [], "states": [], "note": "Not available."}
    return {
        "sources": found,
        "total": len(_exams.SOURCES),
        # A state board is reachable only by naming the state. The wrong
        # state's paper is the same subject, the same year and the wrong
        # syllabus, and it does not announce itself.
        "states": all_states,
        "state": state,
        # Said here so a renderer cannot drop it. "Past papers" means three
        # different things across these boards and a teacher should know
        # which one they are about to get.
        "note": "These are the boards' own pages. Nothing is copied here — "
                "a board owns its question papers. 'Specimen' means the "
                "board publishes sample papers rather than the sat ones, "
                "and 'login' means papers go only to registered centres.",
    }


@app.get("/api/exams/syllabus")
def exam_syllabus(exam: str = "",
                  user: User = Depends(current_user),
                  db: Session = Depends(get_db)):
    """An entrance syllabus, and which of it the school books do not cover.

    A candidate already owns the school books. What they cannot see is the
    difference — the units the exam adds on top — so every unit carries a
    flag for that, and the flag is the point of the page.

    Nothing here is a claim about a particular year. Authorities revise these
    and a list in a file goes stale without saying so, which is why every
    exam carries a link to the authority's own document as the thing that
    settles it.
    """
    _school_only(db, user)
    try:
        import exams as _exams
        if not (exam or "").strip():
            return {"exams": _exams.exam_list()}
        got = _exams.syllabus(exam)
    except Exception as e:
        print(f"exam syllabus: {type(e).__name__}: {e}")
        return {"exams": []}
    if not got:
        raise HTTPException(404, "No syllabus held for that exam.")
    return got


@app.get("/api/craxlearn/sources")
def craxlearn_sources():
    """Where the answers come from, with licences. Open to anybody.

    Unauthenticated on purpose. "Where does your content come from" is the
    first question an institution asks and it is usually asked before anyone
    has an account — by a procurement officer, a head of department, a
    parent. Making them sign up to read the answer is a bad answer.
    """
    return _cl.public_registry()


@app.get("/api/craxlearn/activity")
def craxlearn_activity(user: User = Depends(current_user),
                       db: Session = Depends(get_db)):
    """What has been asked, inside the asker's own institution.

    Two different answers to two different people, and the difference is the
    whole point:

    A **teacher or head** gets their school's activity as topic counts — what
    is being asked and how often, so they can see the class is stuck on
    stoichiometry. Aggregated, with no learner attached to any row. A school
    needs to know what its students are struggling with; it does not need a
    transcript of each child's questions to know that, and building the
    transcript view because it was easy is how a teaching tool becomes a
    surveillance tool. If a school genuinely needs per-student detail for a
    safeguarding reason, that is a deliberate feature with its own consent
    conversation, not a side effect of this endpoint.

    A **learner** gets their own, in full, because it is theirs.

    Neither can see another institution's, and nothing here reads a row
    outside the caller's own scope.
    """
    scope = _scope_of(db, user)
    ta = (db.query(TeacherAccess)
            .filter(TeacherAccess.user_id == user.id).first())

    if ta and _cl.is_institution(scope):
        rows = (db.query(LearnRecord.text, LearnRecord.kind,
                         func.count(LearnRecord.id).label("n"),
                         func.max(LearnRecord.created_at).label("last"))
                  .filter(LearnRecord.scope == scope)
                  .group_by(LearnRecord.text, LearnRecord.kind)
                  .order_by(func.count(LearnRecord.id).desc())
                  .limit(100).all())
        return {
            "view": "school", "school": ta.school or "", "scope": scope,
            "learners": (db.query(func.count(func.distinct(
                LearnRecord.user_id)))
                .filter(LearnRecord.scope == scope).scalar() or 0),
            "topics": [{"text": r[0], "kind": r[1], "asked": r[2],
                        "last": r[3].isoformat() if r[3] else ""}
                       for r in rows],
        }

    rows = (db.query(LearnRecord)
              .filter(LearnRecord.user_id == user.id)
              .order_by(LearnRecord.created_at.desc()).limit(100).all())
    return {
        "view": "mine", "scope": scope,
        "topics": [{"text": r.text, "kind": r.kind, "subject": r.subject,
                    "level": r.level,
                    "at": r.created_at.isoformat() if r.created_at else ""}
                   for r in rows],
    }


@app.delete("/api/craxlearn/activity")
def craxlearn_activity_clear(user: User = Depends(current_user),
                            db: Session = Depends(get_db)):
    """Delete my own record of what I asked. Only ever my own.

    A teacher clearing this clears their own questions, not their school's.
    Giving one account a button that wipes an institution's history is the
    kind of thing that gets pressed once and explained forever.
    """
    n = (db.query(LearnRecord).filter(LearnRecord.user_id == user.id)
           .delete(synchronize_session=False))
    db.commit()
    return {"ok": True, "deleted": n}


@app.get("/api/skills/unlocked")
def skills_unlocked(user: User = Depends(current_user),
                    db: Session = Depends(get_db)):
    """Everything this learner has finished, and who is hiring for it.

    The count beside each skill is the argument for having learned it, and
    it is the same count the careers page shows — read from the live board
    rather than from a claim in a syllabus. A skill with no matcher word
    still appears, with no count: the learner earned it, and a résumé line
    is worth having whether or not a job board has a word for it.
    """
    rows = (db.query(SkillUnlock)
              .filter(SkillUnlock.user_id == user.id)
              .order_by(SkillUnlock.last_at.desc()).limit(200).all())
    out = []
    for r in rows:
        tokens = [t for t in (r.tokens or "").split(",") if t]
        jobs = 0
        for t in tokens:
            # The skills column is a comma-joined list written at ingest, so
            # a bare LIKE would match "sql" inside "postgresql". The commas
            # are what make the boundary.
            #
            # Concatenated with Python's + rather than func.concat: that
            # compiles to the || operator, which both SQLite and Postgres
            # have. CONCAT() only arrived in SQLite 3.44, and the local
            # database is whatever the machine happens to ship.
            padded = "," + func.coalesce(Job.skills, "") + ","
            jobs = max(jobs, db.query(func.count(Job.id)).filter(
                Job.is_open == True,                            # noqa: E712
                padded.like(f"%,{t},%")).scalar() or 0)
        out.append({"skill": r.label, "tokens": tokens, "jobs": jobs,
                    "times": r.times or 1,
                    "since": r.created_at.isoformat() if r.created_at else ""})
    return {"skills": out, "total": len(out)}


class TalkIn(BaseModel):
    said: str = Field(min_length=1, max_length=600)
    subject: str = Field(default="General", max_length=60)
    level: str = Field(default="Intermediate", max_length=60)
    # The last few turns, so "why?" means the thing just said rather than
    # nothing at all. Kept short deliberately: a conversation that resends its
    # whole history grows its own bill on every turn.
    history: list[str] = []


@app.post("/api/ask/talk")
async def ask_talk(body: TalkIn, user: User = Depends(axle_user),
                   db: Session = Depends(get_db)):
    """One spoken turn of a conversation.

    Deliberately not the board's lesson shape. A lesson is a page — headings,
    steps, code — and reading a page aloud is not a conversation, it is a
    lecture nobody can interrupt. This returns two to five sentences, written
    to be *heard*: no bullet points, no symbols that do not survive being
    said, and an answer that stops so the other person can speak.
    """
    if not ASK_ENABLED:
        raise HTTPException(503, "The AI tutor is not switched on")
    said = body.said.strip()
    level = (body.level or "Intermediate").strip()[:60]

    # Cached on the question plus the immediate context. Everyone asks "what
    # is a JOIN" out loud eventually, and the second person should not cost
    # anything.
    #
    # The key says "dalia" rather than "talk" on purpose. The rows under the
    # old key were written by a different prompt with a different persona and
    # no control tags in it; served under this endpoint they would be a
    # tutor who can never open anything, for as long as the cache lives.
    tail = " | ".join(body.history[-2:])[:300]
    scope = _scope_of(db, user)
    qkey = _cl.key(scope, "dalia", _norm_q(level), _norm_q(tail),
                   _norm_q(said))[:500]
    # Recorded before the cache is consulted, not after. What a learner
    # asked is a fact about them whether or not it cost a model call, and a
    # record that only catches the misses is a record of nothing useful —
    # the popular questions, which is to say the ones a school most wants to
    # see, are exactly the ones that hit.
    _record_learning(db, user, scope, "talk", said, body.subject, level)

    row = db.query(AskCache).filter(AskCache.qkey == qkey).first()
    if row:
        row.hits = (row.hits or 0) + 1
        db.commit()
        # Parsed on the way out rather than stored parsed: the raw reply is
        # what was cached, so a cache hit opens the same panels the first
        # asker got. Storing only the spoken half meant the second person to
        # ask about the handshake heard about a packet capture that never
        # appeared.
        say, controls, skills = _dalia.parse(row.lesson)
        return {"say": _spoken(say), "board": controls,
                "skills": _record_skills(db, user, skills), "cached": True}

    _ai_enforce_limit(db, user)
    prompt = _dalia.talk_prompt(said, body.history, level, body.subject)
    try:
        text = (await _ai_text(prompt, 400)).strip()
    except Exception as e:
        print(f"Talk failed ({AI_PROVIDER}): {type(e).__name__}: {e}")
        raise HTTPException(503, _ai_error_message(e))
    if not text:
        raise HTTPException(502, "Nothing came back — say that again?")

    say, controls, skills = _dalia.parse(text)
    if not say:
        # Every word of it was tags. Nothing to say and nothing to play.
        raise HTTPException(502, "Nothing came back — say that again?")

    _ai_bump(db, user)
    # The raw reply, tags and all. What is spoken is derived from it on
    # every read, so changing how a tag is handled changes every cached
    # answer too instead of only the ones asked after the deploy.
    db.add(AskCache(qkey=qkey, subject=body.subject[:60], level=level,
                    question=said[:2000], lesson=text[:4000], hits=0))
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
    return {"say": _spoken(say), "board": controls,
            "skills": _record_skills(db, user, skills), "cached": False}


@app.post("/api/ask/image")
async def ask_with_image(image: UploadFile = File(...),
                         question: str = Form(default=""),
                         subject: str = Form(default="General"),
                         level: str = Form(default=""),
                         user: User = Depends(axle_user),
                         db: Session = Depends(get_db)):
    """Ask Axle a question about a picture.

    The scanner reads a problem and solves it. This is the other half: a
    photograph you want to ask something *about* — a diagram you do not
    follow, a graph in a paper, a slide, a specimen, a circuit, a page in a
    language you do not read. The question is yours; the image is context.

    It returns the same lesson shape as a typed question, so the board renders
    it with no idea an image was involved.

    Cached on the image plus the question, because the pairing is what was
    asked. The same photo with a different question is a different question.
    """
    raw = await image.read()
    if not raw:
        raise HTTPException(400, "That photo was empty")
    if len(raw) > _scan.MAX_MB * 1024 * 1024:
        raise HTTPException(400, f"Photos need to be under {_scan.MAX_MB:.0f}MB")
    mime = (image.content_type or "").lower().split(";")[0].strip()
    if mime not in _scan.MIMES:
        raise HTTPException(400, "Send a photo — JPG, PNG or WEBP")
    require_paid_or_trial(db, user, "scan", "Asking about a photo",
                          "three free photo questions")
    if not ASK_ENABLED:
        raise HTTPException(503, "The AI tutor is not switched on")

    q = (question or "").strip()[:400]
    subject = (subject or "General").strip()[:60]
    # Empty is the normal case now that the level chips are gone, and it
    # must stay empty: coercing it to "Intermediate" here would pitch a
    # question about a photograph differently from the same question typed.
    level = (level or "").strip()[:60]
    digest = hashlib.sha256(raw).hexdigest()[:32]
    scope = _scope_of(db, user)
    # RECIPE here too. This route builds its lesson with _ask_prompt, the
    # same prompt the typed question uses, so a change to that prompt has
    # to reach both — otherwise the photo of a question keeps serving the
    # old answer forever while typing the same question gets a new one.
    qkey = _cl.key(scope, "askimg", RECIPE, digest,
                   _norm_q(level), _norm_q(q))[:500]
    row = db.query(AskCache).filter(AskCache.qkey == qkey).first()
    cached = _cached_json(db, row)
    if cached:
        row.hits = (row.hits or 0) + 1
        db.commit()
        return {"lesson": cached, "cached": True}

    _ai_enforce_limit(db, user)
    prompt = _ask_prompt(
        q or "Explain what is in this image, and what it is showing.",
        subject, level) + (
        "\n\nThe user has attached an image. Look at it first. Describe what "
        "is actually in it before explaining anything, so they can tell "
        "immediately whether you are looking at what they meant. If the image "
        "does not show what the question implies, say so plainly rather than "
        "answering the question you were expecting.")
    try:
        lesson = _parse_lesson(
            await _ai_vision(prompt, raw, mime, 1800), q or "this image")
    except Exception as e:
        print(f"Ask with image failed: {type(e).__name__}: {e}")
        raise HTTPException(503, _ai_error_message(e))

    found, verdict = _check_lesson(lesson)
    review = await _review_lesson(q or "this image", lesson)
    if review:
        found = review + found
        if any(r["severity"] == "critical" for r in review):
            verdict = {"cache": False, "confidence": "low", "state": "flagged"}
        elif verdict["confidence"] == "high":
            verdict = dict(verdict, confidence="medium", state="checked")
    if found:
        print(f"Checks on image question: {verdict['state']} — "
              f"{found[0]['problem'][:120]}")
        lesson["findings"] = _note_findings(found)
        lesson["confidence"] = verdict["confidence"]

    _ai_bump(db, user)
    _trial_consume(db, user, "scan")
    if not verdict["cache"]:
        return {"lesson": lesson, "cached": False, "checked": verdict["state"]}
    db.add(AskCache(qkey=qkey, subject=subject, level=level,
                    question=(q or "(about an image)")[:2000],
                    lesson=json.dumps(lesson), hits=0))
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
    return {"lesson": lesson, "cached": False}


